window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210115-10","meetingId":"r03-cm01","date":"2021年1月15日","dateIso":"2021-01-15","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"議席の割り振りについておよび(3)常任・議運・特別委員会の構成等","agenda":"議席の割り振りについておよび(3)常任・議運・特別委員会の構成等","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今回はそれでいいのかと思いますが、今後、変わっていくのかどうか。私は今回のは、座席としては、議席としては少し違和感を感じますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"すみません、私の聞き違いだったら恐縮なのですが、今回、自・無が６名になったということは、今現在、共産が２名、議運に出ていますよね。自・無はそのまま３名という形で残るということか尋ねました。","respondent":"石田（秀）委員長","answer":"それから、ネット、しな無も２名ということになります。自・無で１２番目、１３番目の数を決定していくということになるという、先ほどの説明のとおりであります。","id":"exchange-002"}]},{"id":"topic-02","title":"附属機関等議会選出委員についておよび(5)各種団体評議員","agenda":"附属機関等議会選出委員についておよび(5)各種団体評議員","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから会派構成の人数の変更に伴って一つ一つ確認をしているところではありますけれども、基本的には現状どおりでいいかと思います。一言述べさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-03","title":"その他各会議の構成等","agenda":"その他各会議の構成等","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"今、高橋伸明委員から、広報会議のサブリーダーということですよね。サブリーダーのバランスもどうかなと思っていたところではあったので、今そういう提案もあったので、共産党として引き受けたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":6304,"voices":39}},{"id":"r03-20210119-6","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"区民委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"令和２年陳情第６２号 目黒川沿いに設置されている喫煙所撤去に関する陳情","agenda":"令和２年陳情第６２号 目黒川沿いに設置されている喫煙所撤去に関する陳情","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"歩道橋というのですか、その橋から下りてくるところがあるのですけれども、そこの下が完全にふさがっていました。この場所に関して利用者のほうが多過ぎて、このような危険な状態が生じているかどうか、そこに関してどの程度把握していらっしゃいますか尋ねました。","respondent":"黛生活安全担当課長","answer":"今、委員ご指摘のとおり、非常に多い、特に昼休みの時間帯ですが、あの喫煙所に２０人ぐらいですね。ただ、その灰皿の近くになるべく寄って、周りの人に迷惑がかからないように使ってくれというふうに指導をしているというような状況でございました。","id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"１日の中で昼休みの時間帯、どうしてもその近くの喫煙所に行かなければならない、結果的に利用者が多くなって密になってしまう。３点目が、その３点が考えられるのですけれども、そこに関しての所感を説明するよう求めました。","respondent":"黛生活安全担当課長","answer":"ただ、また、これこれこういう理由であるので協力をお願いしたいということまで丁寧に説明をしてまいりたいというふうに考えております。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問・要望","question":"近隣にもう１か所開設できないかどうか、どうしても拡充というか、近隣にもう１つ設置する必要性があるだろうなと。ですので、そこに関しての改善策をしっかりと前に進めていただきたいなという部分に関して、この陳情に関しては賛成をしようかと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"とっていけたらなというふうにおっしゃっていたのですけれども、そういう方法というのは、今どのようなことが頭にあるのかというのを伺いたいのですけれども。","respondent":"黛生活安全担当課長","answer":"先般、煙とか臭いの出ない加熱式専用たばこの喫煙所に模様替えをするなどというような、様々な案があろうかと思います。まだ全然検討段階で、今申し上げましたのは、このようなオプションもあるというような中でご認識をいただければというふうに思います。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私はもう本当に考えていただきたいなと、東京都医師会の尾崎会長も、こういった受動喫煙防止に関しておっしゃっているのですよね。ぜひともコロナが明けた際にはとかではなくて、もう今からやっていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"黛生活安全担当課長","answer":"皆様方が健康被害に遭わないようなうまい仕組みなどがないのかなど、一生懸命考えて、これは実現に向けて努力をしてまいる所存です。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、本当にここは緊急にやっていただきたいなと思いますし、でも、たばこを吸う人、喫煙者というものは年々減ってきていますよね。区としてはこうした喫煙所のことをこういうふうに考えていると、今おっしゃられたようなことを話し合われたことというのはあるのか尋ねました。","respondent":"黛生活安全担当課長","answer":"この町会の方と当該喫煙所についてお話合いをする機会というのは、今までございませんでした。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"地元区民の皆様がこれだけの思いをされて声を上げているわけですから、そこはご説明いただいたほうがいいのではないかなというふうに思います。ですから、１日も早く撤去または被害を抑えられる場所への移動、いかがか尋ねました。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、１日も早く、こちらの喫煙所に対してそういう対策をとるか、あるいは、ほかの場所に適地があれば適地のほうへ移動するなど、対策のほうをしっかりとっていく必要があるというふうに考えております。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"これは陳情が出されたのが１１月２５日で、一番と言えるか分かりませんけれども、喫煙者がはみ出ているというのが大きな問題意識であると思います。２か月弱あったわけですけれども、まだ明確にはないように見受けられるのですけれども、そこはまだ明確にないということでよろしいか尋ねました。","respondent":"黛生活安全担当課長","answer":"最大時において、そこからあふれるぐらい多くいた喫煙者が、今のところはやや落ち着いているような状況も見受けられている旨の報告のほうは受けているところです。","id":"exchange-008"},{"speaker":"松本委員","kind":"確認","question":"落ち着いているということなのですけれども、落ち着いているということは、逆にゼロではないというふうに思います。ここは確認ですけれども、路上喫煙禁止・地域美化推進地区であることは間違いないという認識でよろしいか尋ねました。","respondent":"黛生活安全担当課長","answer":"ご指摘のとおりです。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"そうすると、はみ出している人たちは条例違反ということでよろしいか尋ねました。","respondent":"黛生活安全担当課長","answer":"厳密に申しますと、これは条例違反というふうに捉えられるかと存じます。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"この間、この１年ぐらいでいいですけれども、ここのはみ出している人たち、何人ぐらい罰則が適用されたのか尋ねました。","respondent":"黛生活安全担当課長","answer":"申し訳ありません。こちらの喫煙所付近で何人かというところについては手持ちで数字がございませんのでお答えできませんが、６１件ということで。","id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"この路上喫煙の、喫煙所があると思うのですけれども、私もグーグルでくにば委員から教えていただいて拝見しました。はみ出ているかどうかというのがなかなか分かりにくいところで、路上に喫煙所がある、これはその喫煙所の外だというふうにみなせばいいのか尋ねました。","respondent":"黛生活安全担当課長","answer":"まず、もう少し灰皿のほうに寄ってくれということでお願いをするというような感じで、実務上は運用させていただいているところです。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問・要望","question":"運用を本当は変えていただきたいですけれども、中に入ってくださいみたいなことを言うと、どこまでが範囲なのかというのが分からないと思うのです。喫煙者の方たちも分からないと思うので、そこまではやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"黛生活安全担当課長","answer":"たばこを吸われる方も認識しやすいというところがあろうかと思います。持ち帰らせていただいて、どの程度で何ができるのかということで、しっかり検討の課題とさせていただきたいと思います。","id":"exchange-013"},{"speaker":"小芝委員","kind":"質問・要望","question":"ほかの適地をぜひ探していただきたいなと思うのですけれども、そういった仕組みというのは、これまであったのでしょうかね。そういうような制度を展開されたことというのは。","respondent":"黛生活安全担当課長","answer":"ご指摘のとおり、今後、民間のお力をお借りするというのは有効な手段の１つであるというふうに認識をしております。今後、そうした制度の創設に向けて調査研究のほうを進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"この町会の代表である町会長がこういう陳情を出してこられて、ここの地域のお声なのでしょう。私を信頼してもうちょっと任せてくれませんかみたいなご意見だったと思うのですけれども、まず、それはそういうことでよろしいのか尋ねました。","respondent":"黛生活安全担当課長","answer":"そういう事実があるというところを重く受け止めまして、これは何とかしなければいけないという思いは、私ども担当としても持っているところです。何とか早く、その問題の解決に向けて手を打っていきたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"要望をして、何かいい結果を出していただきたいと考えています。だからここで、今日、私の意見は、ここでもう決めないで、継続をしていただきたいということを付け加えて、私の質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのが、どういうふうになって設置が決まっていくのかというのを、教えてほしいと求めました。今後の対応、町会とか地域の方たちへの対応みたいなことはどういうふうにしていくのか、教えてほしいと求めました。","respondent":"黛生活安全担当課長","answer":"しかる後に、周辺の方々にご説明などを申し上げながら設置をするというような手続きで、今まで進んできたところです。説明する機会などは、必要な説明のほうをさせていただいて、町の方々にもご理解をしていただけるように進めてまいりたいと考えております。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"道路とは別の、回遊まではできないですけれども、少し集まれるみたいなところもあったりすると思うのですよね。様々検討していっていただきたいのですけれども、そういった活用とかも、その辺についてはどういうお考えか尋ねました。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、あらゆる可能性を排除しないで、できることがあればそれをどんどん検討していくというようなスタンスでやってまいりたいというふうに考えております。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"質問・要望","question":"先ほど藤原委員の質疑の中でも確認ができたところでありますが、それはぜひ、引き続きしっかりとやっていただきたいなというふうに思います。これは、もう平成１５年ですから、２０年近く前ですよね。","respondent":"黛生活安全担当課長","answer":"あの周りに、その中に灰皿が置いてあるというような状況ですので、少なくとも車が通る場所ではないというふうには認識はしているところです。たばこを吸う方も、吸わない方もご納得がいただけるような措置のほうを一生懸命検討してまいりますので、よろしくお願いいたします。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"実際に生活安全サポート隊も現状を確認して、そこは車道ですか、歩道ですか。この立っているところは車道なのか尋ねました。","respondent":"黛生活安全担当課長","answer":"少なくとも、車道にあふれているような状況があるというのは、これは間違いがないところです。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問","question":"車道上にこういう歩行者であろう人たちがたむろしている状況というのは、道路交通法上、何か規制等はあるのでしょうか。所管が違うから、分からなければ結構です。","respondent":"黛生活安全担当課長","answer":"少なくとも、車道上にたむろするというか、そういうことは道路交通法上で認められた行為はないというふうに、私のほうでは認識をしています。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ですから、１人１人のモラルにきちんと、これはもっとやったほうがいいと思うのですよね。ですから、どうしようではなく、この課題をどうしようかねというところで対策をとっていく必要はあるのだろうなと。","respondent":"黛生活安全担当課長","answer":"いわゆる、ここで吸っちゃだめですよ、程度だったような気がしております。しっかりと説明をしたり、丁寧な説明をしながら、しっかりととってまいりたいと考えております。","id":"exchange-022"},{"speaker":"小芝委員","kind":"意見","question":"と言っても、今すぐに撤去するとなると、撤去に伴う弊害というのは必ず出てくると思います。直ちに撤去というふうには、私は考えておりませんで、今回の件に関しては継続でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"継続にしたいと考えております。先ほども質疑の中でも確認させていただきましたけれども、先ほど藤原委員の質疑の中で念押しの確認がされましたが、しっかりと見据えながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうした喫煙所は撤去していただきたいという思いですが、この陳情から言うと、早急な移動が必要だなというふうに考えています。そして生活、私はこの陳情は採択して、議会が後押しする形で撤去へ向かっていくということをしていくべきだなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"くにば委員","kind":"意見","question":"恐らく５、６名程度がきちんとした喫煙所、実際の利用状況にそぐわない場所に設置されていると思います。この近隣にもう１か所喫煙所を開設するということで、どちらにいたしましても、今回の陳情に関しては採択という立場でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"松本委員","kind":"意見","question":"それはやはり評価されるべきことだと思っていて、１回今回は継続させていただいて、まだまだやれることというのはあるのではないかと思っています。ですので、今日結論を出すのではなく、一旦継続というふうに考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-02","title":"しながわ活力応援給付金事業の進捗状況","agenda":"しながわ活力応援給付金事業の進捗状況","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いします。一番上の内容は、これは目的だと思うのですけれども、区全体の活力を取り戻すために給付金を給付したことですが、区全体の活力は取り戻せましたか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"生活・家計の足しになりましたといった言葉や、ぜひ、このもらった給付金については商店街で使いたいというようなお声もいただいているところです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜこんなことを言うかというと、この施策はすばらしいという意味で一応言っていますので。やはり区民の方というのは本当にこれを喜んでいるのですねということを改めて確認して、担当課長もそれをひしひしと感じて、。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"この間、区民の方から、大変、コールセンター等やお手紙等でも、お礼の声ですとか、そういったものをいただきまして、大変励みになり、この事業を、まだ新生児の給付金の給付がありますが、進めているところです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちのところにも、耐え忍んできたけれども、やはり店を閉める、または解雇された、こうした相談はまだまだ続いているのですね。こういう対策が今後も必要になってくるのではなかろうかと、私は思うのですけれども、区の考えはどうなのか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"このしながわ活力応援給付金事業につきましては、区民の皆様の負担軽減、区の活力を取り戻すということで、事業を行っております。新生児の方の給付というのを進めている中で、改めてという考えにつきましては、今のところございません。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に暮らしの１つの助けになりますし、私たちも要望はしていきますけれども、対応をしていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"松本委員","kind":"質問","question":"お伺いしたいのが、次がもしあるとしたら、どこまで給付の期間を短くできるのかというのが大切になるのかなと思います。どういうふうに短縮可能なのか、念頭に置かれているのか、その点についてお考えをお伺いできればと思います。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"特別定額給付金での事務状況というのを伺っているところですので、適切な人数で委託しまして、開封作業等の対応というものもしてきました。ですが、今時点では、特別定額給付金を担当した部署との連携等というのはしていない状況です。","id":"exchange-032"},{"speaker":"松本委員","kind":"質問・要望","question":"これはあくまで要望なのですけれども、これは考え方があると思うのですけれども、優先順位をつけるかどうかというところがあるかなと思っています。以上は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"つる副委員長","kind":"確認","question":"確認させてください。その期限というのはいつになるのか説明を求めました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"１２月１１日から１２月３１日生まれの新生児の申請書を１月２２日に発送しまして、申請期限は３月１５日を申請期限とする予定です。","id":"exchange-034"},{"speaker":"つる副委員長","kind":"質問・要望","question":"その確認。行政も求められるところであると思うのですが、直近で見れば大きい経験が２回あるわけですから、その現状だけ教えてほしいと求めました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"その中で、申請がされていない世帯につきましては、勧奨通知というのを改めて送りまして、申請を促すという対応をする予定です。給付を早めるためには、やはり同数程度の経費というのがかかる見込みではあろうかと思いますが、見直しというのも図れればと考えているところです。","id":"exchange-035"}]},{"id":"topic-03","title":"ＬＩＮＥを活用した住民異動届出書等作成ツールの運用開始","agenda":"ＬＩＮＥを活用した住民異動届出書等作成ツールの運用開始","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"何点か確認をさせていただきたいのですけれども、この申請書自動交付機付記載台というのは、これは窓口のほうにあるということですか。それとも、ロビーの記載台の近くにあるということですかね。","respondent":"木村戸籍住民課長","answer":"今、ロビーのほうにございまして、正面玄関から入ってきていただいた大きなロビーの中にあります。","id":"exchange-036"},{"speaker":"小芝委員","kind":"質問","question":"これから適用される、対象となる届書が増えてくるわけなのですけれども、そうすると、何かイメージでは、この自動の交付記載台のほうの行列が出てくるのではないかという、そういった懸念もあったりするのですけれども、その辺どのようにお考えか尋ねました。","respondent":"木村戸籍住民課長","answer":"想定としては、私どもは本当にそうなっていただけるとという言い方は変なのですけれども、お客様の待ち時間も少なくなるというところではあります。ＰＲも進めてまいりたいと思いますが、すぐ行列というような形は、今のところ考えていないところです。","id":"exchange-037"},{"speaker":"小芝委員","kind":"質問・要望","question":"やはりＬＩＮＥというのはどうしても世代的には若い方々が多いので、これをやはり、ぜひ取り組んでほしいと求めました。言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"このツール運用とはちょっとずれるかもしれないけれども、どうしても言わざるを得ないので言いますが、いいでしょうか。よそには絶対流れませんよという保証が、だって個人情報とか入れてやるわけですから、その辺についてはいかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"高齢者の方を忘れないで対応をです。寄り添った対応という話がありましたけれども、なかなかどこにどう何を書いていいのかという部分もありますので、それは直接ご案内をしています。","id":"exchange-039"}]},{"id":"topic-04","title":"飲食店・医療従事者応援プロジェクトの実施","agenda":"飲食店・医療従事者応援プロジェクトの実施","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"幾つか確認をします。平日と土曜日ということで、１月１８日から日曜日以外は毎日という認識でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"基本的に毎日、平日月曜日から金曜日と土曜日という形で進めしています。","id":"exchange-040"},{"speaker":"小芝委員","kind":"質問","question":"配達は、先ほどレンタカーをお借りするということだったのですけれども、区職員のほうでされているのでしょうか。それとも、区内の業者の方にお願いをしているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"知っている方と言うのですか、雇って、配達をしていただいているというような状況です。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問","question":"何点か伺うのですけれども、まずは、こちら今回は区内２病院ということなのですけれども、この２病院を選んだ理由を伺いたいです。きちんと説明できるような理由があるのかどうか、そういった部分を踏まえて、２病院になった理由を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの２病院以外にも、幾つか声はかけさせていただいたところです。こういう形で病院に飲食店が配達という形をお話ししたところ、こちらの２病院の方が、決してこの２病院だけ声をかけたというわけではございません。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問","question":"すみません。なぜその協力という形で、関係がなっているのか、ちょっとそこに関してもう一度ご答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"協力というか、ご賛同いただいたというところだったと思うのですけれども。そういう人員の関係もあるのかなというふうに考えておりますけれども、いろいろとお考えがあるようですので、この２病院が手を挙げていただいたです。","id":"exchange-043"},{"speaker":"くにば委員","kind":"意見","question":"例えばそれが４病院とか５病院ぐらいだけしか声をかけずに、そこに関して、どれぐらいの病院にきちんとお声かけをしたのか。なぜそこが、もしくはご賛同いただけなかった理由に含まれているのか、その２点を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"私どもとしては、お声をかけてさせていただいた全ての病院に対応できるような体制は一応とれるというふうに考えていたところです。うちのほうで引き下がるというか、承知いたしましたと、また次回よろしくお願いしますというような形で対応させていただいたです。","id":"exchange-044"},{"speaker":"くにば委員","kind":"質問","question":"もう一度具体的に伺いますけれども、それでは、今回この２病院以外に、トータルで何病院にお声がけをしたのか。それで、お声がけをした病院の選定基準を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"その中で、すみません。幾つの病院かということになりますけれども、こちらのほうで一定の基準にというところで声をかけさせていただいたです。","id":"exchange-045"},{"speaker":"くにば委員","kind":"質問","question":"例えば、これが今回２病院だけしか、もちろんほかの様々な区内の医療従事者の方は不公平感を感じる方が少なからずいると思います。なぜあの病院だけ、なぜうちの病院では声もかけてもらえなかったのか、具体的にもう一度答えるよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今回の選定基準といたしましては、いわゆるコロナの関係で、一定のご協力をいただいているところというのが、選定の一番大きなところです。そこで、逼迫しているというので、大変だというところで選ばせていただいたです。","id":"exchange-046"},{"speaker":"くにば委員","kind":"質問・要望","question":"その中で、あとは、そういったようにならないようなオペレーションというのを考えていただきたいなというのが１点目です。それとも発注先は区のほうでももろもろ検討して最終的に決めたのか、こちら、誰がどういう基準で決めたのかということを伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"こういうことをやります、あるいは、先ほど言ったしながわテイクアウトマップをやってらっしゃるところにはそれぞれ通知しているというような形で聞いております。","id":"exchange-047"},{"speaker":"くにば委員","kind":"質問","question":"これは必ずこの条件を満たしているところであるのかどうかが１点と、営業時間２０時まで等、この「等」の部分が気になるのですね。必ず営業時間２０時まで、その営業時間２０時まで「等」の部分で、伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"今回もちょうど１人、１店舗６万円ですか、あちらのほうの条件にもなっているかと思います。ここは、というところであれば、そこはすぐに撤回していただくというような形で考えているところです。","id":"exchange-048"},{"speaker":"くにば委員","kind":"質問","question":"はもう１点、実際に２０時までを毎日やっていたかどうかのチェックをしないのかどうか、時間短縮することができない。そういった部分に関して区商連に任せ切りになってしまうのか、チェックをするつもりがあるかどうか、ご答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"現実問題として、全ての店舗を私どもが毎日把握するというのはなかなか厳しい部分があろうかと考えています。こちらの、商店街連合会のほうにも、きちんとこういう部分については確認するようにということで申し伝えたいというふうに考えております。","id":"exchange-049"},{"speaker":"くにば委員","kind":"質問・要望","question":"実際に２０時まで、毎日必ず要請に従っていたかどうかというチェックは必要だと思う、お伝えいただきたいなと思います。２月６日から３月６日、状況に応じてはそれこそ４月６日まで延長があり得る、予算に関してのお考えを説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"２月いっぱいぐらいまで延びるのではないかみたいなことが、一応、想定としては２月いっぱいまでは延ばせるかなというふうに考えているところです。まだ考えておりませんが、今のところ、２月末ぐらいまではできるかなというふうに考えているところです。","id":"exchange-050"},{"speaker":"くにば委員","kind":"意見","question":"こちらに関しては、おっしゃった形で、状況に応じて柔軟な対応をぜひともしてほしいと求めました。余りにも長期化する部分に関しては、どうするかというのを、そこに関してはぜひとも柔軟に対応してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"大倉委員","kind":"質問・要望","question":"１食８００円ということなのですけれども、８００円の基準はどういうあれなのですかという。６００円でやっていました、８００円というのはどういうところから出てきたのかというのを教えていただきたいのと、その辺について説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"最大で８００円で、それに対して１０分の１０を補助しますという形になっておりまして、店舗で負担されるのかという形になっているです。","id":"exchange-052"},{"speaker":"大倉委員","kind":"確認","question":"どこかが負担するという形になっているということの確認と、他の３つをクリアしていれば参加できるということだと伺ったのですが、商店街以外のところにも促しているということでいいのかという確認したいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"９００円だった場合というのは、その１００円の部分は、そういう形で対応いただくような形になっております。恐らく今回の募集で、こういう形で参加いただく場合には、その形で参加いただく方のほうが多いのかなというふうに考えているところです。","id":"exchange-053"},{"speaker":"大倉委員","kind":"質問","question":"最後に。商品券が使える店舗というのは、そうすると、商店街連合会に加盟しているということは前提だということになるのですかねという。","respondent":"遠藤商業・ものづくり課長","answer":"そうですね。全くというのはなかなか商店街連合会のほうでも支援しづらいところもあろうかと思いますので、一応、スキームとしてはそのような形にしています。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問","question":"４１店舗が参加予定ということだったと思うのですけれども、それで、そのうちの４１店舗なのかというのは分からないですかね。分かれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"本当は入れておかなければいけない数字だったのですが、大変申し訳ございません。広く商店街さんを通じてやっているところですので、一応、手を挙げたところで断っているというところはないような状況です。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで、この事業予算のところは、これはもう品川区だけが出す、都からとか、国からとかは入っていない、区の単費ということでいいですかね。","respondent":"遠藤商業・ものづくり課長","answer":"特に特定財源は入っていないような状況です。","id":"exchange-056"},{"speaker":"つる副委員長","kind":"確認","question":"確認があったところなのですけれども、先ほどご答弁のあった参加店舗数については４１店舗で、発注をかけるという理解ですかね。合計が７２店舗となっているわけですが、現在そこが４１店舗でスタートして、増減というのも当然あるということなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"一応、期限を決めて店舗を募集させていただいたので、店舗につきましては、これ以上は一旦は止めるような形になろうかと考えています。募集をしていないので、新たに追加というのは難しいので、今ある中で個数を増やしていくなどという形になるのかなというふうに考えております。","id":"exchange-057"},{"speaker":"つる副委員長","kind":"質問","question":"それは従来じゃなくてとか、その辺の、この4)についてはどういう立ち位置でそういうふうな線引きをしたのか。来店客数が減っちゃうから、ふだんはテイクアウトをやっていないのだけれどもテイクアウト用のお弁当を作ってという、そこのところなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"4)で想定していたのは、検討するような形になるのかなと思いますけれども、いわゆる飲食店をやられているというところが全て対象になっているところです。","id":"exchange-058"},{"speaker":"つる副委員長","kind":"質問","question":"予算のところなのですが、これは、もともと当初とか、また補正があったわけではないと思うので、流用だと思うのですが、その元の財源は何を活用して、今この事業を、プロジェクトをやっているのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらのほうで使わせていただくということで、今、進めているところです。","id":"exchange-059"},{"speaker":"つる副委員長","kind":"質問","question":"その衛生管理の部分というのが、非常に、コロナは関係なく、あると思う、食べ物ですから。第３案、第４案があるのか、そのあたりがあれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"あくまでも私どもの意味合いは飲食店といいますか、そういうほうの支援という形で、商業・ものづくり課でやらせていただいているところです。お話しいただいた際にはいろいろな形で、別の方法なども含めて、いろいろ考えていければなというふうに思っているところです。","id":"exchange-060"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"つる副委員長","kind":"意見","question":"これは、いわゆる一般的な入館料の運用を横引きしているのだと思うのですが、２０名以上の団体で２割引とあるのですね。この展示期間が３月２１日までと短い期間であるのだけれども、そこまで感染がどうなのかなというのがあるので、そこだけ指摘をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":44554,"voices":160}},{"id":"r03-20210119-7","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"厚生委員会","time":"午後 １時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"の(3)から聴取いたします。 それでは、(3)「こころの健康づくりカレンダー」配布","agenda":"の(3)から聴取いたします。 それでは、(3)「こころの健康づくりカレンダー」配布","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"どのぐらい相談が来ているのかということをお伺いしたいのと、活用の仕方としては、配布したというようなことなのでしょうか。それ以外の活用の仕方というところで、こういうふうにやっていますよということがおありになるなら、お教えほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"申しわけありませんが、外出ができないので、特に妊婦や産婦の保健センターへの電話相談などについて非常に増えていることは把握しています。例えば１月、２月を開けていただきますと、お待ちしているところになります。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ぜひ記録して、どこかの節目で報告が上がると、もっともっと展開が広がるかなと。ほかの施策にもすごく応用が利くのかなと思ったので、負担にならない程度で情報収集をされたりという要望なのですが、ご所見をお願いします。","respondent":"鷹箸保健予防課長","answer":"大変前向きといいますか、ご配慮もいただくご質問ありがとうあります。これから考えてまいりますが、快いお返事をいただいているところですので、このような取組みが全体に広まればいいなと思っているところです。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。余裕があるのであれば、そういうところもぜひまた、考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうのがあったら教えていただきたいのが１つと、それから、中小企業向け啓発カレンダー等の配布というところからつくられたということですよね。そういう点では、「こころの健康づくりカレンダー」を配布・活用していくという考えはどうなのかという点についても説明を求めました。","respondent":"鷹箸保健予防課長","answer":"学校は各フロアの廊下とかにも貼っていただこうと思っておりまして、今後増刷した分はそうしたところに配布する予定にしています。単にかわいいというだけで終わっては意味がないので、その辺との考え方の中で、いい形の着地点を見つけていきたいなと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ区民向けというところもまた検討してほしいと求めました。これはこれで、第１回目で本当にすてきなものができたなと思うのですが、そこのところも含めてご検討いただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"連日、品川区でも数十名の新たな感染者が出ていて、たしか多いときには７０名の新規感染者が出たりしている状況です。もう少し具体的に伺いたいのですけれども、現在の特徴はどういうものだと認識されているのか、そこら辺のことをまずお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"明日訂正をする予定なのですが、先週ですと５６２名という状況なのですが、例えば本日朝の時点で把握している自宅療養者の数は３１２名になります。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"今の説明で、よく理解できていないのかもしれないですが、入院療養の調整中という人の数字は、今の説明とはまた別の話なのですか。それを伺おうと思っていたのですけれども、今、いろいろ詳しくご説明なさったので、そこのところの関係もお伺いしたいのですけれども、お願いします。","respondent":"鷹箸保健予防課長","answer":"東京都で別々に出ているものは、区の毎週更新している統計では、入院待ちの人、施設療養待ちの人も合わせて、その時点で家にいるので自宅療養者の中に入っています。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"では、例えば三百何人の自宅療養者の中で調整中の方は何人というのはわかるのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"もちろんわかりますが、毎日、それから時間で変わるので、それをこのグラフに反映させることは、申しわけございません、ほぼ不可能です。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、それは医療機関でやっていることになると思うのですが、検査ができる医療機関というのは大体何カ所になったのでしょうか。それをお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"最新のデータが都から送られてきますが、私の記憶では１２月１０日の１３４カ所というのが最新のものと記憶しております。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"上の表は割ると１２％ぐらいになると思うのですが、その点、いかがでしょうか。その点どのようにお考えなのか、ご所見を伺いたいと思うのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"無症状であっても非常に重要だと考えますので、検査を実施可能な医療機関について、区内での検査の実施はしっかり担保されていると理解しております。申しわけございませんが、保健所で把握しておりませんので、そこまではお答えできかねます。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"１つお伺いしたいのは、マスクをせずに１５分以上、この基準にエビデンスはあるのでしょうか。その点、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"確認","question":"今の質疑の中で新しい情報があったので確認したいのですが、まず１点目が、これは行政検査でやってくださるということなのでしょうか。この２点、説明を求めました。","respondent":"鷹箸保健予防課長","answer":"先ほどお話しした１.５メートル以内、診療所のほうで濃厚接触者かどうかをお一人お一人確認していただくということを同時にお願いしております。ですから、唾液を郵送でみたいな医療機関は、先ほどの１３４カ所には入っていません。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"国としてやっていることなのかわかりませんが、そういう流れになったということなのか、それとも品川区独自の動きなのか。あそこに行って受けてみたらどうですかといったときに、どういう感じになっているのか、その辺の感覚を説明するよう求めました。","respondent":"鷹箸保健予防課長","answer":"先週の１４日に私も出ている都内の保健所の課長会がありまして、今週中に、ですから都内全域になる予定です。２月に入るかもしれませんが、ご住所の周りの何カ所か、そこにお問い合わせしていただいて紹介していただくのが一番いいかと考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"３９度何分が３日ぐらい続いて、もっと早くにＰＣＲ検査を受けられるというドクターの判断にこれからなっていくというのはあるのでしょうか。結局家族１人が陽性になってから、あともう１人の方は無症状だったので、そういう形で回っていくということになるのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"もとは、連休を挟んだ結果、検査をしてからご本人に結果が伝わるのがかなり遅かったという事例があったというのは認識しているところですけれども。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"検査センターというのですか、受入れてもやり切れなくて、そういう実態はそんなに一般的にはなっていないということなのでしょうか。どうでしたかと聞いていたのですけれども、結果がやっと来ましたというのが１５日にメールで来たので、あとはそれほどないのか尋ねました。","respondent":"宮尾高齢者福祉課長、鷹箸保健予防課長","answer":"９月の補正予算で予算をいただいて、ＰＣＲ検査を実施させていただきました。検査総数ですが、最終的には３,９５６人に対して実施いたしました。そうすると、お一人の方に２回、３回検査をして、やはり陽性となる場合は確かにあるので、そういうケースだったかもしれません。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１,０００台買えば２５０万件できると言われておりましたが、また、その点についての考え方も改めてお聞かせほしいと求めました。高齢者施設や障害者施設の入所者・通所者、そこの従事者、そういう点についてはいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"申しわけありませんが、既に４,０００人近くの方が一度検査されたわけですけれども、その段階ではないと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう１つ、そういう中で品川区も医療機関への支援を出されたということは、本当に評価されることだと思います。支援金はもう支給されたのかということと、慰労金についてはどうなのかということについてもお聞かせほしいと求めました。","respondent":"高山健康課長","answer":"ご質問いただきました、補正予算でお認めいただきました慰労金、そして支援金に関しましては、今、医療機関と最終的な調整をしているところでございまして、お認めいただいた限られた予算を功労に応じて等しく分配するという観点から、今、最終的な調整をしています。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"医療機関は本当に大変な状況で、減収補填という考え方が政府にないので本当に苦労していますし、もともと医療機関はどこもゆとりがない中で、今回のコロナというところで本当に大変な思いをされているので、ぜひなるべく早くの支援をということでよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"２つあって、１つは、どういうふうに言ったらいいのかなというのが１つ。それからもう１つは、その辺の状況について、わかる範囲で説明を求めました。","respondent":"鷹箸保健予防課長","answer":"ただ、それは別に区民というわけではありませんので、そこをご理解いただければ、患者、重症化については都内全般と同じようだと認識しております。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"品川区がどうかということは、安心というわけではないのですけれども、品川区が特別にということでないことは説明します。少し改善するのではないかということですから、ぜひそういった点を考慮していただいて、お仕事してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"確認","question":"毎日１回、保健所の方がご連絡されて健康状態を確認されていると聞いていますが、東京都でフォローアップセンターを立ち上げると。先ほど食べ物の配送はというお話はあったのですけれども、そちらも手を挙げていらっしゃるということでいいのか、確認したいと求めました。","respondent":"鷹箸保健予防課長","answer":"今の点、先ほどの説明で漏れまして申しわけございません。そこも頼む予定になっていますが、昨日説明会がありまして、来週からそのシステムに区も乗るように手を挙げております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"「１.届出週別、１月４日から１月１０日までで４９７人とあがっているのですけれども、品川区で感染が判明したということで捉えていいのでしょうか。ＮＨＫのところでも毎日出ているのですが、そこのところではこんなに多い数字ではないので、そこの数字の違いだけ説明を求めました。","respondent":"鷹箸保健予防課長","answer":"品川区保健所が対応している数ですので、区民以外の重症な入院患者、入院したらコロナとわかった方というのも全部入っています。ですので、多くなるということです。","id":"exchange-022"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"障害者団体ヒアリングの実施、この１３団体、前にも伺ったのかな、どの団体かを教えてください。それから、２３区の他区での説明会の実施状況をご存じなら教えてほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"こちらにヒアリング実施予定の団体を記載させていただいているところです。他区の説明会の実施状況ということで、自治体によっては実施されているところもあるということを聞いてはおりますけれども。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問","question":"把握しているところだけでも教えていただけますか。","respondent":"築山障害者施策推進担当課長","answer":"具体的な自治体というところでは、今、手元に資料があるわけではないので回答できないのですが、やっているところもあるということは聞いております。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"教えていただきたいということと、先ほどのご説明の中で、障害者サービスを受けている方全てにアンケートを行ったということでよかったのでしょうか。そこを確認したいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"１点目、私もなぜ５％という数字が出てきたのかがわからないものでして、恐らく陳情者の知り得るところで計算されたのかなと認識しています。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、今ここに配布数が６,４６２とあるのですが、サービスを受けていた方ということでよろしいのですか。８２ページの配布数のところを見たのですけれども。","respondent":"築山障害者施策推進担当課長","answer":"６,４６２というのは、障害福祉サービスを使っていない方も含まれておりまして、手帳を取得しているけれども、特にサービスは使っていないという方も入っております。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、いわゆる品川区が考える障害者の方の全数調査ということでの認識でよろしいか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"障害福祉サービスを使っていらっしゃる方は全員に行いまして、サービスを使っていない方、手帳を持っているだけの方については、抽出で行っております。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"大田区は、新型コロナ感染拡大防止の観点から、１２月２２日から１月１２日まで説明動画の配信をしたということです。当事者の方々が計画を知ることで、障害者理解の促進ということでも説明会を位置づけてやるべきではないかなと私は思うのですが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"よって、必要な方は皆様、相談につなげているという認識です。パブリックコメントですとか障害者団体ヒアリング等を実施する中で、ご意見等をお聞きしながら進めていきたいと考えております。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者の方々が社会で差別なく当たり前に生活できるという共生社会をつくっていこうということを掲げているわけですから、その点どうかということ。やってほしいと当事者が求めているのに、やらない理由というのは何かあるのか、その点についても伺います。","respondent":"築山障害者施策推進担当課長","answer":"区ではさまざまな事業を展開しておりますので、そういったところから区民の方の障害者理解につなげていきたいと考えております。個々の相談に応じて対応しているところですので、説明会という形で実施するのではなく、相談支援事業所等を通じて個々に対応していくという考えです。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そういうものと併せて、この説明会がさらにそれを深めるという、もう１つの機会として使えるのではないかなと思うのです。そういう本当にいい機会になるのにもかかわらず、やらない理由がよくわからないのですとの意見を述べました。","respondent":"築山障害者施策推進担当課長","answer":"先ほどもご説明しましたとおり、または差別解消法の例でいきますと、障害者差別解消法ハンドブックの配布等もしております。いろいろな形で普及啓発も行っておりますので、そういう中で理解を深めていただきたいと考えております。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やり方についてはコロナに合わせた形で検討していただきながら、ぜひ説明会はしていただきたいと要望させてほしいと求めました。それから続けて、障害福祉計画のほうは、皆さん、いいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いいですか。私は３年前のときにぜひそういうところを入れていただきたいとお願いしていたのですけれども、それがしっかりと明記されて、ありがとうあります。","respondent":"築山障害者施策推進担当課長","answer":"素案の閲覧につきましては、配布もありますし、ホームページからもご覧いただくことができます。希望がございましたら、障害者福祉課からお渡しすることも可能です。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１２月２２日の３回目も踏まえた形での計画と考えていいのでしょうかというのが１点と、改めて第６期にこういうふうに充実するようにというふうに国の指針で書かれているところが、今回どういうふうに反映されているのかということについてもお聞かせいただけたらと思います。","respondent":"築山障害者施策推進担当課長","answer":"３８ページの「人材の確保・育成」の部分の、専門的な人材の育成を図るというところ、こちらに記載しております。こちらでは強度行動障害というところで、高次脳機能障害の記載はございませんが、高次脳機能障害も含めて、専門的人材の育成を図るという考えです。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"団体の皆さんもいらっしゃいますし、さまざまな要望も出されており、本当にもっと充実していただきたいという要望を聞いておりますので。それから２６ページですけれども、白い丸の下から２番目の２行目に、障害者福祉のしおりとはまた別にこういう情報のものがあるのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"まず「（１）安心して暮らせる地域生活の支援」というところでは、地域生活を支援するというところに重きを置いているところです。「（３）社会参加の促進」と「（４）地域共生社会の実現に向けた取り組みの推進」というところでは。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから３５ページの一番下なのですけれども、地域生活支援拠点、自立支援協議会の分科会としてつくられている組織ということなのでしょうか。マネージャーは地域生活支援拠点１カ所につき１人という考え方でいいのか尋ねました。","respondent":"松山障害者福祉課長","answer":"それから３５ページの地域生活支援拠点検討会ですが、こちらは、地域生活支援拠点が区内に３拠点あります。その３拠点の拠点マネージャーが集まりまして、区と一緒に地域生活支援拠点を充実させようということで検討会を開いていくものです。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところの確認と、それから2)のところに黒丸が５つあって、それはいかがでしょうか。その確認も教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうですか、すみません、見きれなくて。とりあえず、いろいろ細かくごちゃごちゃとすみませんけれども、今のところをお答えいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"人工呼吸器の方によってその状態像がかなり大きく左右されるものと認識しておりますので、検討という形にさせていただければと考えています。５４ページの表の一番上ですが、成果目標の中に２カ所ということで明記しています。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"令和元年１８８人から、令和元年からすると４０人増やすという見込みを立てられているのですけれども、その点についてはいかがでしょうか。令和４年には８日、令和５年には９日ということで、誘致のために区としてどう取組むみたいな方針があったら教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"初めに、医療的ケア児・者の支援関係機関連絡会の開催見込みについてのお尋ねです。それから６９ページの計画相談ですけれども、今のところ、３月にもう１カ所増える予定です。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。どういうふうに把握されて、待機者はどれくらいいるのか、そこのところを教えていただきたい。","respondent":"松山障害者福祉課長","answer":"現在のところ、計画相談の相談員あるいは地域拠点の相談員がアセスメントをする中で、ご本人とご家族から把握しています。昨年１０月時点での数になりますけれども、施設入所とグループホーム合わせて大体４２名となっております。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうすると、１０４人は他の自治体のグループホームに入られていると考えていいのか、その確認をお願いしたいと思います。それから、これだけの計画を組めるような体制整備をどういう形でしようとしているのかということについてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"６７ページの障害児の計画相談なのですが、ここの数字は請求ベースの数字となっております。〔「全員につくっているのですか」と呼ぶ者あり〕 民間相談支援事業所を含めて、障害児の計画相談は現在では７事業所あります。３月にもう１カ所できるので、８事業所という予定ですので… ８８名の方が入所されておりますので、８８名以外の方については、区外のグループホームということになっております。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"相談支援事業所とかも本当に少ないところから出発したのが、さまざまなご努力によってかなり増えてきましたし、まだまだグループホームとか足りない部分もありますので、これから本当に充実させていっていただきますようにお願いして、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけ確認させてください。どういう体制を想定されているのかということと、リーダーシップを発揮していただきたいのですけれども、そういった点についてはいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"地域自立支援協議会の子ども支援部会というところが動いておりまして、あとは、あるいは横断的な組織ということになっております。年齢によって関係機関も全く異なってまいりますので、もう少し区の中でしっかり練った上での体制を構築していきたいと考えております。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"意見","question":"今お話があったように、そういう組織はあるのですが、今後の課題というか、どうやっていこうということを今検討されているということなので、また機会を改めてお尋ねしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"西村委員","kind":"意見","question":"さまざまに考え、取組んでいただいていることが理解できました。パブコメに関しましては、昨年から品川区の公式ＬＩＮＥアカウント等もありますので、こちらの活用などもご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いいたします。陳情自体はパブリックコメントの前にということですが、これからスタートするということもありますし、今回は不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"団体の方を７団体ですか、委員としてご意見を伺えるようであったり、それが反映されているわけですから。今回、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"おくの委員","kind":"意見","question":"最も大事な計画の当事者の方に十分納得いただいて計画は定めるべきだと思いますので、説明会は一番重要な手続きだと思います。採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"今度、そこの中で実際に障害をお持ちの方あるいはそのご家族等のご意見を丁寧に伺っていただくこと等が大切なのではないかと思います。計画策定について情報を収集していると思いますので、あえて説明会は必要ないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-04","title":"を再度聴取いたします。 それでは、(1)「品川区成年後見制度利用促進基本計画（素案）」に係るパブリックコメントの実施","agenda":"を再度聴取いたします。 それでは、(1)「品川区成年後見制度利用促進基本計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ご本人の人間としての尊厳が最後の最後まで担保されるというのが一番大事なことだと思うのです。その２点について、大きなところで伺っておきたいと思うのですが、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"それから順番が逆ですけれども「意思決定支援」、こういったことをしっかり認識しているのだということをここではっきりと意思表示することが。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私なんかもいろいろとお世話になってきたなと思うのですけれども、これは新たにネットワークの構築ということでできていくということなのでしょうか。地域連携ネットワークのイメージがもうちょっとわかるように、１９ページのところをご説明いただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"品川区の考え方としては、もちろん１００％、この中身についてはそれほど大きな変更はないと考えております。それから１点補足しますと、ずっと取組んでいますので、そういったことも計画にしっかり落とし込んでいければと考えています。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それとも、ネットワークということで、改めて成年後見制度の今回のこの計画で変わることというのは特にネットワークのところではないということでいいのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"今の副委員長のご指摘の、協議会という名称のものは今現在、存在しておりません。国が定めているものの中で、いわゆるベースとなるようなものについては、既に運営委員会という形で実際に動いていると考えております。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"品川区は成年後見センターという形で、かなり具体的なところではその方に寄り添った形でやっていただいたなという思いを私はしているのです。今までずっとされていて、今回計画をつくるにあたって、品川区としてここがこう変わりますみたいなものはあるのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"繰り返しになる部分もありますが、協議会、中核機関といったものの位置づけをまず明確に計画の中に落とし込んでいくということがあります。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"１９ページを見ると、品川区と品川区社会福祉協議会の２本立てになっているのですが、これは普通のパターンなのですか。ほかにも何かそういうふうな例示とかがあるのかどうかということが１つと、何か検討とかがあるのかどうか、教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"区もしっかりやっているのだということはやはり安心の一つにつながると思いますので、ここは入れていきたいなと、今の段階では考えています。恐らくそういった経緯でこういったメンバーの人選になっているです。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"ということは、中核機関に自治体が望ましいと国が言っていて、それと２つ並列して、並べているというやり方は、割と独特な感じと捉えておいていいのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"区の職員、区の実際の部署がこの業務に携わっているというところで、そんなに多くあるケースではないと。むしろ区の職員がそういった実務を日々やっているということについては、ひとつ特徴的なのかなと考えています。","id":"exchange-054"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西村委員","kind":"質問","question":"１個お伺いさせてください。2)のほっとサービスの部分は、コロナになってからはどんなご依頼があるのかとか、もしおわかりだったら教えていただけますか。","respondent":"寺嶋福祉計画課長","answer":"６５歳以上の高齢者の方が対象になっているのですけれども、場合によっては衣替えを頼んでいるとか、こういったものがあると聞いたことがあります。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問","question":"さわやかサービスは、お掃除とかを頼んでいらっしゃる方が多いのかなという印象だったのですけれども、高齢者の方にとって、ほっとサービスとどういうすみ分けになっているのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"支援員がやっていることになりますので、やっていただける方はこういった志の高い方にやっていただいているというところでの違いぐらいですね。かなり際どい線引きになっているところではあります。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つ目のほっとステーションですが、目的の２行目に、教えてほしいと求めました。もう１つは、右側のページの（２）外出自粛に伴う云々のところですけれども、高齢者の方に届くようにされているのか尋ねました。","respondent":"寺嶋福祉計画課長、菅野高齢者地域支援課長","answer":"考え方としては、それがもともとの設置の目的で、かなりのウエートは占めていると認識しています。数字が出せなくて大変申しわけないのですが、つながる確率としては、コーディネーターはかなりのウエートを占めていると認識しておりま… ２つ目の、まだまだ外出自粛は長引くと思いますので、そういったことも活用させていただきたいと思います。どうもありがとうございました。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問","question":"要支援高齢者の発見という言葉がいいかどうかはあれですけれども、重要な役割と今伺ったので、よろしくお願いします。広報のほうは、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"右側の２番の表で、再開したところで、実際の参加者はどんな感じなのか教えてほしい。減っていたのかどうなのかということと、仕掛けていこうと考えているのか、そこだけ説明を求めました。","respondent":"菅野高齢者地域支援課長","answer":"おおむね８割ぐらいの方には参加していただいたのですが、まだまだ感染が怖いということで今回は辞退しますというお声もありました。例えばおうちでも運動できるような体操等をケーブルテレビ等を通して放映したりするなど、いろいろな仕掛けをしていきたいなと考えております。","id":"exchange-059"},{"speaker":"渡部委員","kind":"確認","question":"体を動かしてほしいと、品川区にはケーブルテレビがあるのだから、そこで１０分でも１５分でも高齢者体操番組みたいなものをぜひ何か仕掛けてほしい。予算に関わることかもしれないのであれなのですけれども、そう思ったので、確認だけしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１回３０分２００円ということですが、これもボランティアの方の組織が大変と伺っていたのですけれども、その人数も教えてほしいと求めました。１カ月１３回くらいになる感じなのですが、例えば１５町会あったら、１つの町会で１カ月１件くらいという感じと考えたらいいのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"ご本人が嫌がっているので、これは難しいということです。それと、ほっとサービスの人数ですけれども、調べて、後ほどお答えさせてください。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いろいろな取り組みをされていますが、これは全て介護保険の地域支援事業にあたるもの、介護保険でやっているものと考えていいのでしょうか。研修を受けても実際に登録する方が少ないとお聞きしたのですけれども、そこら辺がどれくらいなのか、教えてほしいと求めました。","respondent":"菅野高齢者地域支援課長、寺嶋福祉計画課長","answer":"１点目の一般介護予防事業、全て介護保険の地域支援事業の中での実施事業ということでご紹介させていただいたものです。１教室に運動指導員のリーダーがいて、法人全体で… 先ほどの地域支援員の人数の関係ですけれども、定期訪問については１,１９１件、訪問していないのです。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１事業者あたり１００名弱みたいな感じで、でも、実際は件数としてはそんなに多くない感じなのですかね。やはりコーディネートしてボランティアにお願いするという形で、特に今はコロナ禍ですから少ない状況になっているとは思うのですけれども。","respondent":"寺嶋福祉計画課長","answer":"地域支援員は、先ほどの地域づくりの中の１つに、さまざまな活動をしていただいています。活動の１つの項目としてはあるので、みんながフル回転して訪問をやっているかというと、そういうわけでもないということです。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":62642,"voices":177}},{"id":"r03-20210119-8","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"建設委員会","time":"午後 １時００分～午後 ５時０６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"東京都市計画 都市計画区域の整備、開発及び保全の方針の変更","agenda":"東京都市計画 都市計画区域の整備、開発及び保全の方針の変更","exchanges":[{"speaker":"田中委員","kind":"意見","question":"多分５Ｇの話などが関係するのかなと思うのですけれども、５Ｇのアンテナ基地局の設置場所について、品川区内の状況について区は把握をされているのかどうかといった部分をお知らせいただければと思うのですがとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"区の所管全体とすると、例えば情報推進課等がありますが、そうした意味で区が把握しているかというところですと、そこまで確認しておりませんので分からないのですが、都市計画課、私としてその基地局を把握しているかというお尋ねであれば、私としては把握していないところです。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"趣を感じられるといった部分で、どういったところを注目させていきたいというか、そういった部分を伺いたいと思います。そういった活用としてこの立会川だったり、勝島だったりというのが、東京都とお話をされていないのかなといったところを伺いたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"最後のトランジットの対応の部分は、次の便までの数時間、６時間だったりとか、その少しの時間ですぐに戻れる、電車１本で来られる範囲での、旅行者の方たちが気軽に楽しめて戻れるようなところということで、この地区という話をしたので、ぜひそういった観点も考えていただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"このＡ３の資料の裏面のほうに書いてある「天王洲」とか「北品川」とか、ここに書いてあるのは駅ですか。それとも、これから先、こういうふうにしていくということなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"当然、そこは全体的な広域的な観点から東京都が調整をして、最終的には東京都もこの改定の検討の中でしっかり整合を図りながら進められてきたです。何か文化観光の視点でやっているかというのは、私も勉強不足でお答えできないところで… 都市計画を定めて、駅前広場ですとか公園、都市基盤を整備してまいりました。形成が進んでいるというところで、日常の生活機能の集積・更新は、今後もしっかりしていきたいというような意味合いでの記載になってあります。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、西大井のほうですけれども、あそこの駅ができて、ただ、あの駅も反対側に改札口をつくってほしいとか、いろいろ意見があるわけです。そこも明確なビジョンを立てていただけるとありがたいなと思いますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、都市計画などのコントロールがきかなくなってしまうのではないかと思うのですけれども、区の受け止めはいかがでしょうか。計画方針の改定にあたって、区への意見照会というのはあったのか、そしてまた、どのような意見を出したのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それに合わせて後追いでこの方針を変えてきているわけではなくて、うたうべきところはうたって、改定が進められてきているものです。先ほどご説明したものは、区としてまちづくりビジョンも作っておりますので、そうした形でやり取りをさせていただいたです。","id":"exchange-006"},{"speaker":"のだて副委員長","kind":"質問","question":"そうすると、区の意見としては、大体今までどおりで、特に立会川・勝島のところを追加してほしいという意見だったのかなというふうに思います。そうしたもとで、変えていかなければならないのではないかというふうに思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"コントロールができないというよりも、そうした意味での記載だです。今後のまちづくりを、それを受けて今後の計画にどう書いていくかというところが重要なところになってくるのではないかというふうに考えてあります。","id":"exchange-007"},{"speaker":"のだて副委員長","kind":"意見","question":"そういったことだと思うのですけれども、あと距離をとるということはやっていくけれども、大本のところは変わらないということだと思います。コロナ（禍のもと）での再開発ですとか、特定整備路線等の巨大道路を進めていくというのは、やめるべきだというふうに私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはどうしてかというと、羽田空港から飛び立つのが１２時台が結構多い。そういうものも品川区のマスタープランなのだから、それも１つのまちづくりになるわけだから、ぜひそれはお考えいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"これ、どういうような考え方で書き違いがあるのか、教えてください。ゾーニングに該当するような表現があってしかるべきだと思うのですけれども、どういう取り扱いをしたのか、説明を求めました。","respondent":"鈴木都市計画課長","answer":"変更前といいますか、この計画の変更以前は、説明があったのは。ちょっと答えとしてどうかというのはありますが、以上です。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"もうちょっと都のほうでも、そのうちゾーニングも決まってくるのでしょうけれども、そこのところにちぐはぐさを感じたので質問させていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"東京都市計画 都市再開発の方針の変更","agenda":"東京都市計画 都市再開発の方針の変更","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"その変更案のところの、２の策定の効果の5)のところで、「市街地再開発事業の社会資本整備総合交付金交付要件の一つに位置付けられている」と。どういったことから変わって、どういうふうになるのかというのが、ちょっと勉強不足で教えていただきたいと思うのですけれども。","respondent":"多並都市開発課長","answer":"市街地再開発事業を進めていく際には、国の補助金を導入しながら進めているところであります。それを公表しながら整備を進めていく、今はこのような形で進めているという、そこら辺の流れの今の最新の形で書いたというふうに認識しています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"そこはある程度、東京都も認識をしていただいているのかなという期待は持っているのですが、そこはどうなのでしょうか。そこにマンションを建ててしまうみたいな、そういう手法がやはりまだまだ主流なのか、それは東京都はどういう考え方を持っておられるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"従前の計画も大きな建物を建てることを第一に据えて計画や方針が作られてきているわけではございませんで、(1)で説明した方針（都市計画区域の整備、開発及び保全の方針）があって。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"違うイメージをもうそろそろ作り上げるような形に、東京都も方向転換してほしいし、品川区もいろいろな経験を踏まえて。そうなったときに、お金も出してくれみたいな状況まで踏み込んで言える状況になってくれたらいいなと思うのですけれども、その辺はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"開発及び保全の方針）と今回のもの（都市再開発の方針）については、あるいは、これからもそういう観点でしっかりやっていかなければいけないです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうことをサポートするのが区の役割だと思っているので、ぜひそういう形で。主体は地域住民というふうに思っておりますので、ぜひその辺は東京都とうまく調整を図って進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"先ほどの交付金の部分は、難しくて何と質問していいか分からないので、また別の機会にもう１回まとめて伺いたいと思います。４８ページの地図の荏原地区であることは分かるのですけれども、そういったものとかも書いていないので、教えていただけますか。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた４８ページに描いてある絵が、裏面の２ページ目の下段のほうに、横線で描かれてあります。上は上大崎の辺りから、東五反田は入っていないですかね、位置的には荏原を中心としたこの絵のとおりです。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのときは例えば行政の判断で、どこの地域だろうと、やると言ったらやれるという判断でいいのですか。ほかの話だと、地域からいろいろ話があってやっていくではないか尋ねました。","respondent":"多並都市開発課長","answer":"まちの動きが活発に動くように、そういう形で誘導していくための１つの方針というところがありますので、そういう位置づけというところです。今ありましたような形で、そういう部分でも１つの位置づけというのは、ちょっと違うところというのは１点はあるところであります。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"１号の向こう側があるとして、ＪＲとか、こっちの周りもあると、行政側が主導で、これは２号再開発で一緒にやるとかあるではないですか。行政がやると言ったら、それはできるという理解でいいのか尋ねました。","respondent":"多並都市開発課長","answer":"今のは恐らく第一種市街地再開発事業と第二種市街地再開発事業の違いかと思います。〔「そう、それです」と呼ぶ者あり〕 行政が自ら再開発事業を進めていく場合ということで、皆さんで考えていただいて、混在するということはあり得ないかと思います。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"ちょっとイメージがつかないのです。品川区で第二種市街地再開発事業で行政主導で開発を進めているところはあったのか尋ねました。","respondent":"多並都市開発課長","answer":"私が確認してきた中ではないと認識しています。私、今のところ、聞いたことはないです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"では、今進めようとしている品川区の中での再開発の中で、第二種市街地再開発事業というのはないという認識でいいか尋ねました。","respondent":"多並都市開発課長","answer":"今はなく、地域の方と一緒につくっていくということで今は進めているところであります。","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問","question":"武蔵小山駅の補助２６号線の南側とか、これは区の計画ではないですけれども、都の方針なので都の考えがある。先ほどとも一緒ですが、照会とかがあって、どのような意見を出したのかというところを伺います。","respondent":"多並都市開発課長","answer":"この考え方ですけれども、５ページで示されているこの方針に従って、全体的な考え方の中で都とも協議しながら進めているところであります。今後も地域の皆様のいろいろなご意見をお伺いしながら進めていくべきということで考えているところであります。","id":"exchange-021"},{"speaker":"のだて副委員長","kind":"質問","question":"広げると言うとおかしいですか、重点的に東京都では感染が多いわけですから、そういった考え方を変えていくということが必要だというふうに思います。そうしたもとで、今回、広町地区も加えて対象拡大をしていくということはやめるべきだというふうに思いますけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"その１１地区すべてにおいて、超高層の建物を建てて開発を進めていくという記載がされているわけではございません。したがいまして、すべてが開発、高層の建物を誘導するための計画だと、そうした形での記載でされているということではございません。","id":"exchange-022"},{"speaker":"のだて副委員長","kind":"質問","question":"いかがでしょうかということと、環境問題としても、建設時にも８年分程度のＣＯ２の排出がされるということが建築学会の論文でも出ています。この超高層再開発を進めるという考えは変えていくべきだというふうに、そういった考えを変えていくべきだと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"都市開発課長からもご説明しましたが、具体的にはどういう形で、個々の都市計画あるいは地区計画等の手法で進められていくものです。ＣＯ２を生み出すですが、まちづくりの基本的な考え方の中にカーボンマイナスという考え方は、以前から定着して進められているという内容です。","id":"exchange-023"},{"speaker":"のだて副委員長","kind":"質問","question":"どういう個々のまちづくりの解決をしていくかというのはそれぞれだということでした。開発した後の排出量は、比べてしっかりマイナスになっているということなのか、その具体的なデータがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"カーボンマイナスの、総量として従前の排出量を軽減しましょうという考え方は、基本的な考え方で進められているものがあります。考え方がしっかり示されているというのは間違いない話でございまして、考え方は東京都の計画の中でも、しっかり考え方として示しています。","id":"exchange-024"},{"speaker":"のだて副委員長","kind":"意見","question":"特にこの再開発の部分のところでどうなっているかというところです。そういった環境の面からも言って、やはりこの再開発を進めていくというのはやめるべきですし、この方針には反対をしたいというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"田中委員","kind":"確認","question":"１点だけ確認をし忘れてしまって。東京都と品川区のほうで、方針（案）に入れる際に、どういったお話があったのかなというところを伺いたいのですけれども。","respondent":"鈴木都市計画課長","answer":"これは都の計画の中で都の広域的な視点から記載されているものだというふうに認識しているものです。それから、あるいは記載を今改める方向で考えているというところは、今現在のところは区としては聞いてございません。","id":"exchange-026"}]},{"id":"topic-03","title":"戸越公園駅周辺まちづくりビジョン駅前広場計画編（素案）の策定","agenda":"戸越公園駅周辺まちづくりビジョン駅前広場計画編（素案）の策定","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"今後のスケジュールのところで、素案の説明に対して対象が関係町会および関係団体へ説明ということだったのですけれども、関係町会、関係団体の、そこに当てはまる、その町会などをお知らせいただきたいと思うのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"こちら、戸越公園駅付近の８町会２商店街について、まずそちらのほうで説明をしていきたいというふうに考えてあります。再開発も進められている組合がありますので、そちらにも説明に行きたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"そこの地域住民の方へのお知らせということはないのでしょうかということと、区内の方だったら説明を聞けるような機会を設けていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"地域に限らず誰もが説明をというところですけれども、別紙２の本編の２ページをご覧ください。ですので、今回は地域限定に特化して説明をしていきたいというふうに考えてあります。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"資料の中で、この「定期」という意味もあとで伺いたいのですけれども、地域の方に限らない利用者の方たちがいるのかと私は読み取ったのです。ということは、やはり説明会は広く対象を広げていかれるべきではないかということを思ったので、そこは伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"パブリックコメントを実施するかですが、この計画についてパブリックコメントを実施する予定はございません。そこに住まわれている方たち、その先に利用しやすくなりますよという形で地域のいろいろな方たちに説明をしていきたいというふうに考えてあります。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"この駅周辺の課題について、４つの課題があるといったことで理解しました。その中で戸越公園駅周辺まちづくりビジョンがこうやって先行されたという、その選ばれた理由をお知らせほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"引き続き７ページで、こちらのほうはバスの状況を示しています。国道や都道まで３００ｍ、１８０ｍといったところで離れている、駅としてはちょっと使いづらい部分があるというところで示しています。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"高齢者や障害者の方たちから、どういった声が届いているかというご答弁がなかったと思うので、そこをお知らせほしいと求めました。障害児者の施設もありますし、戸越公園駅周辺まちづくりビジョンの素案が先に上がってきた理由を改めてお知らせほしいと求めました。","respondent":"鈴木都市計画課長、中道まちづくり立体化担当課長","answer":"旗の台駅周辺地区については、その中でもう既にしっかりバリアフリー対応の歩行者視点のまちづくりを進めていくというところは、そうしたところで。計画、方針を定めていくですので… まず１つは、昨年度行いました基本計画編のパブリックコメントの意見の中に、駅前広場を作って欲しい。こういったときにも、やはり駅前で乗り降りができるようなスペースをつくってほしいという言葉をいただいているような状況です。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区内全体のバリアフリーというところを考えてほしいというのは、たしかこの前の決算特別委員会のときにもお話しさせていただきました。品川区内でも、いろいろな意見の聴取をしていただきたいと思うのですけれども、そこの部分をお知らせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"西本委員","kind":"確認","question":"スケジュールだけ確認をしたいと思います。将来的な広場をつくるにしても、スペースがなかったら広場はできないわけであって、具体的にはどう進められていくのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"今、補助第２９号線は事業中というところ、また、連続立体交差事業は、いつ事業をするかというところは、今現在、未定です。今現在、こういった駅前広場の考え方とか、または昨年度ございました要望書等で活動しています。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"それだとちょっと残念なので、見立てはあるのでしょうか。立体化になって、踏切も解消になって、それで広場もできてというのが同時にできるわけではないか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"品川区としましても、そうした位置づけがきちんとしている路線ですので、事業化に向けての現実性は非常に高いというふうに考えてあります。そうした中で、今こういった活動をしています。","id":"exchange-034"},{"speaker":"西本委員","kind":"意見","question":"なかなか進まないと、がっかり感というか、やはり不安のほうが募ってきてしまうと思うので、皆さんにこういう状況になっていますという情報は発信されると思いますが、いいことであるので、ぜひ皆さんに夢を与えていただけるような情報発信をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"確認で、先ほど、素案の説明は対象の方以外にはしないけれども、今後、広く説明をするといったご答弁があったではないですか。その説明をされるときには、ここはこうしてほしいといった意見が反映されるときなのかというところだけ確認したいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"それで都市計画案という流れになってくるのですけれども、そのタイミングで、都市計画決定に向けて説明会を開くです。そのときにまた意見をもらったりというタイミングがありますので、そのときに意見をいただくような形です。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"そのときの都市計画素案の決定についての説明会は、この地域に限らず区内全域に対して縦覧とかも求められるのですねということだけを確認させていただきたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"今度は都市計画決定になりますので、都市計画の窓口のほうで、そうした都市計画資料は縦覧が可能となっています。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"そのときの説明会についても伺いたいのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画法の中で、第１６条と第１７条の説明会というものがあります。第１７条のほうでの説明会のときに、区民全員参加可能な説明会が開かれるところです。","id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"お願いしたいのですけれども、緊急事態宣言下ですので、委員の皆さんにおかれましては、やはり委員長の指導のもとに効率的で重複しない、まとまった要点を心得た質問に心がけるよう、指導方、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"この戸越公園駅周辺の問題は地元の問題なので質問させてほしいと求めましたけれども。やはり今回新たにこの駅前広場計画編というのを作るわけですから、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"今後の進め方ですが、連続立体交差事業は東京都が行うという……。","id":"exchange-040"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"今回、駅前広場の候補地ということで９番地区のところが示されているわけですけれども、世帯数等を含め教えてほしいと求めました。そういったところで区としては、どのように利便性というか、必要性を考えていらっしゃるのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"別紙２の本編のほうの１２ページですが、ここに一定程度の将来の交通ネットワークも記載しています。補助第２９号線や補助第２６号線が整備されると、ここは利用する方々、そういった整備をしてまいります。","id":"exchange-041"},{"speaker":"のだて副委員長","kind":"質問","question":"いろいろ道路の開設などで交通広場としての必要性が高まるというお話でしたが、補助第２６号線が大井町と武蔵小山を結んでいるわけですね。その基盤整備を行っていくという駅前広場になっているのではないかという問題を感じているのですけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"再開発と駅前広場の関係性ですけれども、そこについて直接的な関係は特にございません。ですけれども、そういったことも併せまして、駅前の一体的な整備というのは考えていきたいというふうに思ってあります。","id":"exchange-042"},{"speaker":"のだて副委員長","kind":"質問","question":"実際に道路整備などが行われて、バスルートも将来的なネットワークのところで必要性があるということでしたが、ここにバスが通る可能性はあるのか、区としてそこのバス停をつくっていくですとか、そういったお考えがあるのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"その場での発言ではもちろんないのですけれども、補助第２９号線または補助第２６号線については、バスの路線としては非常に魅力的な路線ということは聞いてあります。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"スケジュールのところで、やはり何回伺っても分からないので、区民意見が確実に反映されるタイミングだけを示すよう求めました。","respondent":"中道まちづくり立体化担当課長","answer":"都市計画決定をする前に都市計画案の段階で、説明会または都市計画資料の縦覧、意見募集を行いますので、その際に意見をいただければ区のほうに届きます。","id":"exchange-044"}]},{"id":"topic-04","title":"東京都の土砂災害警戒区域等の追加指定予定","agenda":"東京都の土砂災害警戒区域等の追加指定予定","exchanges":[{"speaker":"西本委員","kind":"質問","question":"５０箇所、３８箇所になるのでしょうか、それは公表するのでしょうか。どういう内容で、どういう対応をしていくのかということを、中身だけ説明を求めました。","respondent":"長尾建築課長","answer":"実際に今回追加指定が予定されている場所の航空写真に警戒区域、あとは、そのチラシを併せて資料としては配布する予定としております。防災課も載せておりまして、今後の避難情報等に関しての問合せに対しても対応するような形をとっております。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"住民は何をすればいいのでしょうか。そういう説明の中に建物をどうしろとか、何か具体的な行動を要請されるのか尋ねました。","respondent":"長尾建築課長","answer":"区域の指定を受けて区民の方がすぐに何かしなければならないというわけではございません。大雨等が降ったときに、そういう崖地に関しての認識を持っていただいて、認識をしていただくというところが主になります。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"例えば、危ないからどこかに引っ越そうとかといったときに、当然ながら、そこは危険箇所だということで売れない可能性もあるわけではないですか。そういう場合はどう対応するのか尋ねました。","respondent":"長尾建築課長","answer":"基本的には建物を建てることができないというところです。助成については区のほうで対応しておりますので、調整を図りながら進めていくということになります。","id":"exchange-047"},{"speaker":"田中委員","kind":"意見","question":"具体的に御殿山小学校の中のどういった面になるのかといったところを知りたくて。子どもたちへの影響が、もしそういうときに大丈夫なのかといったところが知りたいのですけれどもとの意見を述べました。","respondent":"長尾建築課長","answer":"土砂災害警戒区域の話が出る前から、学校側でも敷地の中の部分についてはきちんと擁壁を造って安全化を図っている。落石等も防ぐ措置も学校の敷地側のほうでやっているなど、安全対策は学校側で可能なところはやっているというふうに聞いております。","id":"exchange-048"},{"speaker":"田中委員","kind":"意見","question":"ご説明で分かったのですけれども、対応はされているといったことだったのですけれども、でも、今回指定されたということで、やはり不安になる保護者と子どもたちもいるのではないかと思うので、そういった説明はどのようにされるのかといったところをお知らせくださいとの意見を述べました。","respondent":"長尾建築課長","answer":"今後、庶務課とも情報を共有しながら、学校側でできることのお話と、あと、やはり民地側でどうしてもご対応いただくお話と両方あると思いますので、可能なところを進めていって、より安全なところを建築課としても支援していきたいと考えております。","id":"exchange-049"},{"speaker":"のだて副委員長","kind":"質問","question":"いろいろやっていくべきだと思うのですけれども、登録している人数は何人になるのか、伺いたいと思います。なかなかそれで進めていくというのが難しいということで、この支援拡充をぜひやるべきだというふうに思うのですが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"建築課と防災課で共に情報発信なども行っておりますので、そういったところでの周知も今後継続して努めてまいりたいと考えています。","id":"exchange-050"},{"speaker":"石田（秀）委員","kind":"意見","question":"イコールというのは必要だと思うのだけれども、どこかで整理はしてほしいと思うのだけれども。これは所管が違うというなら答えなくてもいいけれども、ぜひそこの２つ、お願いしますとの意見を述べました。","respondent":"長尾建築課長","answer":"今回、その建築工事が終わりましたので、追加調査を都のほうで令和２年になってから行って、今回の追加指定予定となったというところです。避難場所に関しましては、所管としては防災課になりますので、防災課のほうで今後対応をしてくると思われます。","id":"exchange-051"}]},{"id":"topic-05","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"のだて副委員長","kind":"意見","question":"のだて稔史ですとの意見を述べました。","respondent":"中島防災課長","answer":"施設の管理者などに対しまして周知をするとともに、令和３年度に避難確保計画の作成および避難訓練の実施を支援してまいります。２、令和３年１月２７日に防災会議を開催する予定でしたが、計画に反映をしてまいります。","id":"exchange-052"}]},{"id":"topic-06","title":"令和２年度品川区地域防災計画の修正","agenda":"令和２年度品川区地域防災計画の修正","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々としても、では、議会でやろうというのなら議会でもやるけれども、そういうところをぜひ考えていただきたいと思っている。どうお考えなのかなと、直していくのは非常にいいことなのだけれども、そこら辺のお考えをぜひ聞きたい。","respondent":"中島防災課長","answer":"具体的な施設名とかはなかったので、今回は明確にして分かりやすく、かつ安全に避難していただけるように考えております。地域の方々にご説明する機会でありますとか、様々な媒体を通じまして、何度も繰り返し分かりやすい形の周知をしていきたいと考えております。","id":"exchange-053"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"留守番をされている方がいらっしゃるわけではないですか。そういうときでは余計怒ってしまうような気がしてならないので、そちらのほうもぜひ体制整備もしていただきたいということだけ要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところはどういうふうにお考えになっているのか、聞かせていただきたいのが１つ。それと、地図ですけれども、資料１の別添１で「ＳＣ」と書いてあるのは、これは何か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"大沢委員","kind":"質問・要望","question":"別添２のほうは、きちんと「後地小」とかと漢字で書いてくれるから分かるのだけれども、確かにシルバーセンターは長くなってしまうから。では、最初の部分だけご答弁いただきたい。","respondent":"中島防災課長","answer":"ちょっと曖昧だったところがありましたので、それが原因と考えて、今回、しっかり明確に避難施設を示していきたいということが考えです。明確でなかったというところに原因を思いまして、少し明確にするということで、今回見直しをさせていただいたものです。","id":"exchange-056"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、前回のところは周知不足だったということで、前回のものをさらに十分に周知するという作業をするということになると、そもそも案自体は見直しをされていなくて、前回あったものをさらに周知をするという。","respondent":"中島防災課長","answer":"指定の考え方の見直しというところになりまして、地区部に１から２施設をしっかり決めていって、このときはここが開設されますというところを明確にするという考え方の見直しということで捉えていただければと思います。","id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"どうしてもあまり代わり映えのしないような、施設の見直しではなくて、考え方の見直しというふうに捉えればいいということですよね。どうか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"シルバーセンターの中から、台風の状況に応じて選定をして、さらにそれを周知をするという状況になっておりました。自主避難施設については１３か所を固定して開きますという形で周知をしますので、ここは考え方も含めた見直しとご理解いただければと思います。","id":"exchange-058"},{"speaker":"西本委員","kind":"確認","question":"もう１つ確認ですが、開設対象施設というのは、これは近いところに行っていいということですね。庁内の方々、区民の皆様方にどうやって伝えたらいいのかというところがありますので、お考えを説明するよう求めました。","respondent":"中島防災課長、滝澤災害対策担当部長","answer":"２の避難施設の考え方についてですが、そういう定義なのですけれども、そこも含めてしっかり説明はしてまいりたいと思います。そういう地震との違いというのは、先ほど来ありますとおり… 当然、区の職員だけでは開けないので、そのところは災害も震災も風水害も同じようにしようということで考え方としてはまとめました。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１回、２回でうまくいくなどとは到底考えられない。ぜひそれは考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"田中委員","kind":"提案","question":"今の案をどのように提案して、そしてどうやって聞き取るのかといったところと、そういったところをお知らせください。このときにはこういったことも必要だといった、施設自体の周知とともに、そこら辺についてもお知らせほしいと求めました。","respondent":"中島防災課長","answer":"まだ施設側と調整はしておりませんが、そういうところを見据えまして、しっかり目に見える形での周知も努めてまいりたいと思います。昨年、やはり避難するということも緊急の対応の１つですので、そういうところも併せてしっかり周知をさせていただきたいと思います。","id":"exchange-061"},{"speaker":"田中委員","kind":"意見","question":"地域への説明と声の聞き方についてですけれども、町会長会議を基本ということだったのですけれども、町会に入られていない方たちにもやはり声を聞いていただけるような工夫をぜひしていただけたらと思いますが、そこら辺についてもとの意見を述べました。","respondent":"中島防災課長","answer":"地域の中のできるだけアクセスがしやすいような場所を考えたのですが、１３地域センター全体のバランスなども勘案しまして、全体の考え方を説明したいと思います。","id":"exchange-062"},{"speaker":"田中委員","kind":"確認","question":"今回の修正案については、これからホームページとかでの公表とかがあるのかといった部分もお知らせください。確認で、歩行困難者の方たちが避難に使えるエレベーターの設置について、この施設全体的に。","respondent":"中島防災課長","answer":"そのほかに広報しながわとか、様々な媒体で何度も周知をしてまいりたいと思います。あくまで施設管理者としてしっかり利用者を避難できるように考えていただくというコンセプトですので、特にそこまでは把握する予定はございません。","id":"exchange-063"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"事前の周知をしていくということで、これは私たち区議団としても求めてきたものですので歓迎したいと思います。この避難施設の考え方を伺いたいのですが、そこが分からなかったのでお聞きしたいというところと、そういった視点での考えを伺いたいと思います。","respondent":"中島防災課長","answer":"１点目の自主避難施設の開設にあたりまして、現時点での考え方は、開設をするかしないかを台風の規模などに応じて判断をしていくです。こちらも検討の中で、やはり畳があるということのいい面も十分考えたところなのですが、その中から選定をさせていただいたです。","id":"exchange-064"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"城南小学校については大丈夫という判断だとは思いますが、どういった検討をされてきたのか、そこを伺いたいと思います。資料１のところで、そういったことをやるべきではないかと思っているのですが、そこの考えも伺いたいと思います。","respondent":"中島防災課長","answer":"これも今回検討する中で慎重に検討してみたところなのですが、今回、案として掲載させていただいたところです。土砂災害の避難場所から外れる２校につきまして、様々な媒体を通じまして、避難の情報をしっかりと伝達してまいりたいと思います。","id":"exchange-065"},{"speaker":"のだて副委員長","kind":"質問","question":"要配慮者利用施設の指定のところで、大体４年ぐらい経つことになると思うのですが、施設の指定が今になったという経緯を伺いたいと思います。そういったところでの避難の考え方などもありましたら伺いたいと思います。","respondent":"中島防災課長","answer":"２点目が、避難訓練の実施ということで、こういうときにはこうするみたいなところのタイムラインは含まれるものだと考えております。恐らく平屋の場合は、垂直避難ではなく、そういうところも必要に応じて指導等をしてまいりたいと思います。","id":"exchange-066"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"やはり命に関わることでもありますので、ぜひこれは迅速にやっていただきたいというふうに思います。併せて、そして避難訓練の実施ということができるように、区としても指導して支援をしていっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"田中委員","kind":"質問・要望","question":"この機会にぜひ調べて、ほかの関係部署と連携して調査していただきたいということを思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"先ほど、災害対策担当部長のご答弁で、いわゆる超大型台風のときはすべての５２か所の避難所を開けざるを得なくなるでしょうというお話がありました。この３で言うと、９７０ｈＰａ以上は「在宅避難とし、合っているのか尋ねました。","respondent":"中島防災課長","answer":"この資料１の３のところの表ですが、すみません、数字が入っていたためにちょっと紛らわしくて。この９５０ｈＰａよりも左側の、過去３０年ぐらいでないような台風が上陸した場合の話で、左側の話をさせていただいたところです。","id":"exchange-069"},{"speaker":"若林委員","kind":"確認","question":"１つ確認ですけれども、２の自主避難施設に載っているところは、４の自主避難施設に対応している。２の区民避難所は、この表の、今回の見直しの表には対応していないというところの確認したいと求めました。","respondent":"中島防災課長","answer":"４のところに該当するものでございまして、２の真ん中の避難場所については、５の避難場所の見直しについてです。３の一番左側というところと、ちょっと分かりづらいところですが、しっかりと整理をしまして周知に努めてまいりたいと思います。","id":"exchange-070"},{"speaker":"若林委員","kind":"質問・要望","question":"うまく最大限に工夫していただいて、要配慮者のほうは、複数の委員から平屋建てがどうという話がありました。平屋かどうか、ちょっと違和感を感じたので、改めて答弁を求めたいと思います。","respondent":"滝澤災害対策担当部長","answer":"今回、法令が改正されまして、今年度、浸水区域に該当する施設をすべて洗い出しました。その義務づけの中に支援とありますけれども、その支援の中で、訓練はどのようにやりますというサポートを我々防災課のほうで実施しますので。","id":"exchange-071"},{"speaker":"若林委員","kind":"質問","question":"このやり取り、また議事録をもとに、私たちも、ある意味では区民に説明するということに当然なるわけではないですか。工夫と言うしかないのかな、さっきの確度と一緒で、重々お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-07","title":"防災タブレットの更新","agenda":"防災タブレットの更新","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはこれでぜひやっていただきたいと考えていますが、１６の町会・自治会がありますけれども、８割方の方は置きっ放しだと思っています。","respondent":"平原防災体制整備担当課長","answer":"こういったものに使えます、ふだんからこういうものでやっていくのですというようなことをきちんと一番最初のときに説明していきたいと思います。地域から様々な声をいただきましたら、個別にも丁寧に対応してまいりたいというふうに考えてあります。","id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"高齢者の人には３回言っても分からないので、８割ぐらいの人しか理解してくれないと思うし、多分もっと分からないと思うのです。要望で、答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"予算額を伺いたいと思います。契約が年間契約なのかどうかといったところや、そこら辺をお知らせいただきたいのと、お知らせほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"実施ですけれども、緊急事態宣言の期間との関係で、会議が開催されるところから順次お配りしてご説明させていただきたいというふうに考えてあります。こちらは対応してございませんので、そういったところも含めて、改めて調べさせていただければというふうに思ってあります。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、サービスとタブレットの契約ということだったので、そうなると、また契約が変わってきてしまうということですか。そこら辺をお伺いできればと思います。","respondent":"平原防災体制整備担当課長","answer":"大変申し訳ございません、現在対応してございませんでしたので、そういった観点からもいろいろ勉強させていただければというふうに思ってあります。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問・要望","question":"庁舎で使っている通訳は、通訳のサービスもついた上での契約になっていて、それに対応できるタブレットを契約しているということなのですね。やはり、ぜひ研究を早急に進めていただき、対応していただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"のだて副委員長","kind":"質問","question":"さっき導入経費ということでは１台当たり３,５７９円、毎年というか、１台当たりの値段ということになるのか。ランニングコストのところを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"現行タブレットと同様に、地域の方々が中心ということになりますので、想定している対応といたしましては大きく変わるものではございません。","id":"exchange-078"}]},{"id":"topic-08","title":"令和２年度区内一斉防災訓練の実施結果","agenda":"令和２年度区内一斉防災訓練の実施結果","exchanges":[{"speaker":"のだて副委員長","kind":"質問","question":"１点だけ。それに対して今後どう対応していくのか、特にコロナの対応等を含めて何か課題がありましたら伺いたいと思います。","respondent":"大森災害対策担当課長","answer":"その中で人数をすごく縮小した形で実施して、この状況の中で、そういった分野についてもある程度注力していかなくてはいけない。区としても柔軟な対応を心がけて、しっかり検討していきたい、このように考えているところです。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212900?Template=document&Id=4312#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":69417,"voices":246}},{"id":"r03-20210119-9","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"文教委員会","time":"午後 １時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"大変なのではないですかという質問が１つと、それとアンケート結果ですが、最初のほうですか。各学校の現場にはどのようにこれの活用を求めているのか、方針を出しているのか、その３点を伺いたいと思います。","respondent":"篠田学務課長","answer":"そのことによってクラスの学級編制の枠を超えてしまえば、そこで増やす必要がありますから、そういった対応を取るということになります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ですから、これを学校改善に活かすということはちょっと無理があるのではないかと、率直に今の答弁を伺って思いました。それともう一つ質問なのですけれども、昨年や一昨年は大体何人ぐらいだったのか、分かればお伺いします。","respondent":"篠田学務課長","answer":"中学校と義務教育学校の後期課程に関しましては、昨年、一昨年ともに兄弟枠で入れなかった方は１人もいらっしゃらないということです。なかなか見込みが立てづらいのですけれども、最大でいけばそういった数字になってくるのかというふうに考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それと今のご答弁、最大３３名ですか、後期課程は去年も一昨年もゼロということなので、中学校のほうですか。選択制がなければ、別に兄弟がばらばらになる必要はないわけですから、これはちょっとデメリットだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"確認","question":"多分そのように教えていらっしゃるのだと思うので、違う形で載せられたほうがいいのではないかと思うのですが、いかがでしょうかということです。そうすると、そこを教育委員会としては、この選択制がどのように機能しているかということをどのようにお考えかということをお伺いしたいと思います。","respondent":"篠田学務課長","answer":"１年生の時点では何とか受け入れられても、そういった場合には、翌年度以降に支障がないように対応していくというものです。確かに表現としては、入学予定見込数というのは分かりにくい部分はあろうかと思います。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"１月末と２月末、それぞれで締め切るということだったのですが、その際に何か発表のようなことをされたりするのでしょうか。結構３月ぐらいまでご連絡が続いたりして、タイミング、どうなっているかを説明するよう求めました。","respondent":"篠田学務課長","answer":"基本的には学校選択の繰上げに関しまして、これ２月末で終わりますので、基本的に３月はございません。この学校選択で入れなかった方が一部指定校変更などを希望されていて、３月の、私どももできるだけ早く対応したいと思っていますけれども。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"それぞれ１月末、２月末を過ぎても、まだ行く学校が決まらないというお子さんというのは、大体例年何％ぐらいいらっしゃるものなのでしょうか。割となじむような気がするのですけれども、その方向での検討もされているのか尋ねました。","respondent":"篠田学務課長","answer":"指定校変更は年によって違いますけれども、１００件ぐらいのケースが出てきますので、そのぐらいの方は常にいらっしゃるという状況です。今後そういった部分で、何らかのメリットが出てくるようなことが見込まれるようであれば、検討を進めていきたいと思っているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"意見","question":"中学校、４クラス１４５名のうち２８７名が無抽選で入れるということになっておりますけれども、数が多いところがそういったことで対応できるのかと。特に日野学園などは、そうした対応で大丈夫なのかということを少し疑問に思ったのですけれども、その点いかがお考えなのかを説明するよう求めました。","respondent":"篠田学務課長","answer":"そういった対応もあるです。仮に受入れできないということになれば、先ほど申し上げたとおり、教室の数を増やすなりして、対応していくというふうに考えているものです。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"１クラスの人数を４０名にしたりして対応されるということで、その教室の転用というものが、それほどすぐにできるものなのでしょうか。やはり物理的な問題があると思うのですけれども、何かうまくやられている事例など、そのようなものがありましたら示すよう求めました。","respondent":"篠田学務課長","answer":"教室の転用ですけれども、例えばこの時期に急に１教室増やさなければいけないとなると、正直なかなか対応が難しいというところがあります。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問","question":"調査の対象が、今は学校選択を希望した方ということなのですが、希望しなかった方にも聞いてほしいと思うのです。その辺のちょっとお考え、今答弁を聞いていますと、アンケートを見直していくというようなところはお考えがありますか尋ねました。","respondent":"篠田学務課長、工藤指導課長","answer":"この機会とは別に様々な形でアンケートを保護者の方、児童・生徒の方には取っていますので、その中でこの学校選択に係る部分の設問等も設定しているものです。 やはり兄弟が通っているであるとか、そういったことで特段選択をしないなどの報告を以前していますが、そういったところでもアンケートを取っているところはあります。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"隣接するお隣の学校には支援学級があって、通常級に行くのだけれども安心できるとか、そういった方もいらっしゃるのです。そこのところも、やはり今後この学校選択のところで検討していっていただきたいと思うのですが、その辺のお考えをお願いします。","respondent":"篠田学務課長","answer":"まずは学校選択におきましては、私どもとしては、理由については今のところそれに基づいた整理等はしていないというものです。これに関しましては、基本的な考え方、根本的な考え方になりますので、理由に基づいた選択を導入するいう考えは、今のところないです。","id":"exchange-010"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、あと兄弟に関する部分は２０２４年度までということで、現在はよろしいでしょうか。確認したいと求めました。","respondent":"篠田学務課長","answer":"兄弟在学中に経過措置として対応するですので、その部分に関してはさらに先まで、２０２４年までという形になってくるものです。同じようなことはホームページのほうでも掲載してまいりますので、そういった点で周知ができるのかなというふうに考えているところです。","id":"exchange-011"}]},{"id":"topic-02","title":"令和２年特別区および東京都人事委員会報告","agenda":"令和２年特別区および東京都人事委員会報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そこの（２）のライフ・ワーク・バランスの推進のところなのですが、このような意見に対してどのような取組みというものを推進していて、どう実効性を確保しようとしているのかを改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"品川区におきましては、品川区においての働き方改革プランを学校に示した上で、様々な取組みを行っているところです。改善に努めるというところで指導もしているところでございまして、そういった教員が少なくなるようにということで取り組んでいるところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"教育委員会としてはある程度把握されているのか、超過勤務の時間ですとか、そういった効果についてはどのように把握しているのでしょうか。伺いたいと思います。","respondent":"工藤指導課長","answer":"いわゆる月の単位でいうと４５時間を超えないというところで、そういったところで少なくなるように、それが常態化しないようにということで努めているところです。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"それで、品川区ではこれについてどのように検討しているのか、教育委員会でお分かりでしょうか。（６）番。","respondent":"工藤指導課長","answer":"そういった意味では、そういった把握をしていますので、いわゆる保育教諭というところで勤務している方というのはいないところではあります。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"なので、品川区としてはどのような見解になっているのか、分かれば教えてくださいということなのですけれども、今ちょっと教育委員会だけになってしまっていますが、一応文教委員会でこれは出てきているものなので、もし教育委員会で分からなければ、後半に引き継いでほしいと求めましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"まさに教育委員会の方にお伺いする以上に、委員長にご相談をすべきことだと確かに思います。一応文教委員会で出てきている中でのお話なので、後半、所管のほうに引き継いでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"筒井委員","kind":"意見","question":"この特別区人事委員会の報告の３ページで、東京都人事委員会のほうでも２ページ目で、ソフト・ハードの両面でさらに環境を整えるべきと。教育現場でやはり生徒に対しては、どのように推進していくのか、具体的に今後どのようにこれに関して取組みをされていくのかを説明するよう求めました。","respondent":"工藤指導課長","answer":"今も現状進めてありますし、そういった対応ができる環境もありますし、学びを止めない工夫という観点では進めたいと思ってあります。それもテレワークの一種というふうにお考えいただければ、臨機応変にそれは行っていきたいと、また行っているところです。","id":"exchange-017"}]},{"id":"topic-03","title":"品川区立図書館の休館日変更","agenda":"品川区立図書館の休館日変更","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"１件確認させてください。あるいはその２つの館については日数変更になるかと思うのですが、契約の変更ですとか、そのようなことというのはやっているのか尋ねました。","respondent":"横山品川図書館長","answer":"ご指摘いただきましたとおり、荏原図書館、五反田図書館につきましては、休館日が月２日から１日になり、逆に言うと指定管理業務については１日増える形になりますので、令和３年度予算におきまして、各１日分を補償する形で予算を確保しております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"この３館がずらすということなのですが、近くに第２木曜日でも開いているという、そのようなことはなかなか難しいことなのか尋ねました。","respondent":"横山品川図書館長","answer":"実はこの変更につきましては、１年間プロジェクトチームをつくって検討してまいりました。営業したときの影響だとかということを検討しましたけれども、事実上、品川図書館だけが変更しているような形ですので。","id":"exchange-019"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"１００ＭＢを１ＧＢに今変えるということなのですが、光ファイバーとか、そのようなものを導入するということでしょうか。ちょっとそのインターネット環境の状況をお聞きしたいと思います。","respondent":"篠田学務課長","answer":"今回１ＧＢにアップするということで、基本的には１ＧＢの体裁にはなっている、現状の制限を取っ払って１ＧＢにするというような形での対応をしていくものです。","id":"exchange-020"},{"speaker":"あべ委員","kind":"確認","question":"このインターネットのボリュームなのですけれども、これは学校規模によらずということなのでしょうか。ではその残った時間でどう定着と発展を図っていくかというところというのは、どのような仕組みをされているのかを説明するよう求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"インターネットの規模ですけれども、基本的には今、全ての学校を一律に１００ＭＢにしていますので、今回も一律に１ＧＢに増強するです。その辺はちょっと実情を見ながら、状況を見ながら必要に応じて… は使い方マニュアル等も、より一層の簡易なものという形で、これまでも先生方にお示しをしています。私どもで情報を得たものは、この通信のような形でも共有するなどして、学校での活用を図っていきたいというふうに考えてあります。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"さらに教育委員会として各学校に働きかけていくというようなことがあってもいいのかなとも思っているのですが、その辺はどのようにお考えでしょうか。いかがか尋ねました。","respondent":"工藤指導課長","answer":"現状、さらにそういった活動も含めて、１人１台タブレットを効果的に活用できるように進めたいというふうに考えているところです。この１人１台タブレット、しっかりと押さえながら、またきめ細かい学習を進められるように進めたいと思ってあります。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"その来年度以降の先進的な取組みを行っていく、ある程度モデル研究校的な仕組みを新たにつくるということでしょうか。あるいは使っているソフトが違うから、どうなのか尋ねました。","respondent":"工藤指導課長","answer":"初めは、いわゆるモデル校として、活用重点校ということで、私どもで３校程度指定をして進めたいというふうに考えているところはあります。","id":"exchange-023"},{"speaker":"あべ委員","kind":"意見","question":"４月からきちんと授業が始められる、違いぶりというものは大きくなると思いますので、そこはぜひ配慮をお願いしたいと思います。とりあえずここまでですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"それと前回の１回目のときの質疑で、それは何時間とか、もう決まったのでしょうか。お伺いしたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"ですので、要は事業者がいろいろと考えていただいている部分もあるので、このアプリだけを取り出して幾らという形にはなっていないです。それから休業中の対応についてですけれども… 使える時間帯につきましては、朝７時から夜９時までという設定をしてお渡しをするというところで考えております。ただ、いわゆるインターネット検索などは朝７時から夜９時までしかつながらないという設定でお配りをするです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"今の取組みの状況というのですか、私のほうから質問したことはなかったのですけれども、どうなのか。ではどこまで取り組まれているのかということをお伺いしたいと思いますし、どのようなイメージなのかということをもう少し説明を求めました。","respondent":"篠田学務課長、工藤指導課長、齋藤教育次長","answer":"ですので、３分の２の機械は、言ってみれば、全部補助金で対応していると。これだけではなくて、引き続き利用するものもあったりするものですから… 自分たちにない視点を気づいて、ああ、このような見方もあるのかということを取り組みながら授業を進める。… 授業時間がずっと短縮しますので、その中でまとめの時間を持ちながら、クラス全体の方向性や学習への理解というものに取り組めていくと思います。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区としては今どうなっているのか、最後、そこの実態ですか。縛りというとマイナスイメージですけれども、効果を発揮しているのか、その辺について最後に尋ねました。","respondent":"矢部教育総合支援センター長","answer":"東京都からは、以前そのような名前で、スタンダードという名前で資料が配布されたこともありまして、それは参考として提示はしています。","id":"exchange-027"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３月からの全校活用に向け、もしあれば教えていただきたいということと、品川区はアプリ込みで１台４万５,０００円だから実質ただということでした。そうすると大体７万円前後するものが国の補助を受けて、ただになるという形なのか、そこをもう１回教えてほしいと求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"できるだけ早めにということで取り組んではきたのですけれども、６年生、９年生分の調達が１２月には難しいというような状況がございました。ですので、先ほど説明もございましたけれども、それに代わる機械等を使って… 今説明がありましたように、昨日から研修用として、いわゆる児童・生徒に配るものと同じセルラーモデルのｉＰａｄを各校に１台ずつ配付しています。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"確認","question":"先ほど説明があったのでしょうか、ロードマップではそのように出ていましたので、これからやられるということですね。確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"芹澤副委員長","kind":"提案","question":"それか、例えばこのような機能がこの学校で使えるのではないかというような提案型の業務をされるのかを教えていただきたいということと。例えばロイロノートを１つ取っても、それとも職員の方、もしくは教員の方々で確認し合って共有する場が何かあるのかを説明するよう求めました。","respondent":"篠田学務課長、工藤指導課長","answer":"行くときに全て伺って対応するということ、そういったものに関わる部分も、お答えできる範囲ではサポートするという形でなってあります。これはまだ業者が決まっているわけではないので、確定ではないのですけれども… 区内も含めて進めていきたいと思いますので、やはり全教員向けと、また学校のほうに広めていただくような形でも考えているところです。そのようなものも活用していきたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"モデル校３校というお話だったと思うのですけれども、別の学校もモデル校を３校抽出してやっていくというお考えなのですか。今、何か副委員長のご質問にご回答がなかったかなと思ったので。","respondent":"工藤指導課長","answer":"実際に活用の重点校ということで、よりその推進を図る意味で先進的な取組みなどを行っていただくという学校を３校程度充てて行っていきたいと。その中で、よりそこに重点的に、情報発信も含めて行っていただきたい学校を指定するという方向で考えているところです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"それは今のＩＣＴの推進校から３校選ぶということですか。それともゼロベースで選ぶということか尋ねました。","respondent":"工藤指導課長","answer":"現状あります推進校との関連というものは、特に考えているところではございません。現在、これから進めるＩＣＴの中で、いわゆる全校対象の中でです。","id":"exchange-032"},{"speaker":"あべ委員","kind":"確認","question":"とすると、これは単にＩＴの専門家というだけではなくて、ある程度学校教育についても理解のある方が来られるという意味でよろしいのでしょうか。確認したいと求めました。","respondent":"篠田学務課長","answer":"なかなか実際問題、教育の中身にまで立ち入っている方、要は理解している方というものは難しいと思うのです。ですので、例えば教材の、いわゆる教育内容の中身まで踏み込んだものというところまでは考えていないところです。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"それと前回のときにも少し質問をさせていただいたと思うのですけれども、そうしたことにも活用を広げていかれると期待をしているのですが、そこはどのような感じで考えていらっしゃいますか尋ねました。","respondent":"篠田学務課長","answer":"その辺はこれから試行錯誤していくことになると思うのですけれども、いずれにしてもその機械を活用できるなら、対応を取っていければというふうに考えているところではあります。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問・要望","question":"公教育ですので、いろいろな事情や背景があるから結果的に違うということになっても、対応にあまりばらつきがないようにしてほしいと求めました。支援学級などでも、それぞれに応じたソフトを入れて使っていらっしゃるというように考えてよろしいのか尋ねました。","respondent":"篠田学務課長","answer":"特別支援学級につきましては、現状も今ｉＰａｄを使って、２人に１台の体制で様々なアプリを使っているという状況です。支援学級のお子さんは、それはそれぞれの支援学級等の状況を見ながら、導入をしていくということを考えているところです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"これも前回もちょっとお伺いしましたけれども、例えば保護者との連絡ですとか、プリントの共有ですとか、そのような公務といいますか、家庭との共有といった使い方というのも、一部の学校では試行されていると聞いているのですが、これはどのような形で進めていかれるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"あくまで学習を支援するものということは大前提で、お子さんの学習に障害がなければ、家庭でどこまでやれるかということはこれから検討していきたいと考えております。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"区固有教員の方で、ＩＣＴの推進の役割を担っていらっしゃる方というのは、何名ぐらいいらっしゃるのか尋ねました。","respondent":"工藤指導課長","answer":"今ちょっと手元に名簿はないのですけれども、私の記憶で申し訳ございませんが、今のＩＣＴ推進リーダーの中に固有教員は４名は入ってあります。２月に予定しておりますので、やはりスキルを上げていただきたいということで、区固有教員独自の研修も予定しています。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"区の固有教員以外の方とはまた別の部分で、大変重要な役割を担っていただけるのかなというところを期待しているのですけれども、どのようにお考えか尋ねました。","respondent":"工藤指導課長","answer":"区固有教員向けには、そうした、いわゆる複数の免許の取得も含めて助成する制度、またはそういったものを学習する制度もありますので、そういったものをやはりＩＣＴにも適用するということは可能ですので、前向きに検討していきたいと思ってあります。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問","question":"この「ＩＣＴ通信」にあるような授業実践という、この写真にあるような状況というのは、今現在できるものなのでしょうか。私から見ると、私は３月に収まるのかなとちょっと疑問ですので、そういった取組みが今現在だとできる状況なのか尋ねました。","respondent":"工藤指導課長","answer":"教育総合支援センターより通知を出したところですが、ですからこの対面でという、理科室でのこういった授業というものは行わないということで進めているところです。","id":"exchange-039"},{"speaker":"せお委員","kind":"意見","question":"ちょっとずれてしまうのですけれども、感染症対策も大事なのですが、あまりやり過ぎた対応はいかがかなと思っているので、重要なところは実践などに取り組んでいただいて、ちょっとめりはりつけたところでお願いしたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-05","title":"の２の報告事項に戻りまして、(5)八潮北保育園の運営業務委託","agenda":"の２の報告事項に戻りまして、(5)八潮北保育園の運営業務委託","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その上で質問なのですけれども、応募５社ということでしたが、ほかの応募４社はどのようなところが応募したのでしょうか。いわゆる天下りなのですけれども、いわゆる天下りの人数の方というのは何人なのか、分かればお伺いします。","respondent":"吉田保育施設調整担当課長","answer":"保育に対する区の方針と合致しているか、地域等の連携についてはどうなっているか、財務状況は問題ないかという評価項目になっております。それから元幹部職員でというところは、現在１名いるものと記憶しております。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"そもそも民間委託するのはどうなのかという立場なのですが、これからは公開すべきなのではないですかという質問なので、お考えを伺わせてください。何か品川総合福祉センターが選定されると、区立のままでよかったのではないですかと思うのですけれども、それに対するお考えを尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"上位３社につきましては、その辺も分かりやすかったりとか、公設民営に引き継いでいく際の引継ぎ内容などに実効性があったところです。障害を持つお子さん、例えば医療的ケア児の方についての保育にも対応が可能ということで、委員全員の賛同により選定した次第です。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"特に今回の場合は、議会でも民営化はすべきでないという意見が、私たちも含めて幾つか出ているわけではないですか。どのような選定をしたのですか、区立の保育園を民間に変える必要があるのですかということは、やはりしっかりと見なければいけないと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あべ委員","kind":"確認","question":"そうした補助制度の対象に乗ってくるのかということを確認させてください。１年間のならし期間もあるということなのですけれども、それとも、ある程度は新しい法人に移られたりということがあるのかどうかを説明するよう求めました。","respondent":"吉田保育施設調整担当課長","answer":"このプロポーザルをやる際に事業者向け説明会をやるのですけれども、実際は１社は申し込まれなかった、辞退されたところでございました。三ツ木保育園も同じように昨年の１２月から保育士が入って、現在の区の保育士と一緒に保育の引継ぎを進めているところです。","id":"exchange-044"},{"speaker":"あべ委員","kind":"確認","question":"途中から合同保育になって、品川総合福祉センターに移って引き続きこの保育園に勤務するということはないということでよろしいでしょうか。確認です。","respondent":"吉田保育施設調整担当課長","answer":"それから区の職員なのですけれども、令和４年４月１日から品川総合福祉センターの職員が全員、そこで切り替わるという形になります。そこまでの間の、令和３年１２月から令和４年３月３１日までの４か月間は、引継ぎのための実務的な合同保育を行うという形になります。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問","question":"新たな八潮北保育園では、医療的ケア児の受入れが予定、対応可能である体制になるということでよろしいのでしょうか。もう少し詳しい資料を示していただいたほうがいいのではないかと思いますが、今後、ぜひご検討ほしいと求めました。","respondent":"吉田保育施設調整担当課長、立木保育課長","answer":"医療的ケア児の今後の受入れにつきましては、まだ確定というわけではなくて、今現在進めているというところ、調整をしているというところの段階です。４月… 対応可能なような体制を今構築していますので、そういった意味で、八潮北保育園でも検討しています。今後分かるように出してほしいという内容ですけれども、選定内容の公開につきましては、今後検討させていただければと思います。","id":"exchange-046"}]},{"id":"topic-06","title":"上大崎三丁目教育・保育施設の整備計画","agenda":"上大崎三丁目教育・保育施設の整備計画","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区内で何か所目になるのか、また改めてどのような施設なのか、簡単に伺えればということが１つです。施設整備等に関する工事が、説明があると思うのですけれども、それはいつぐらいを予定していて、どのような形で行うおつもりなのかを伺います。","respondent":"若生保育支援課長","answer":"今後説明会を予定している時期につきましては、これは令和３年度に入ってから、どのような施設にしていくのかという内容を近隣の皆様にご説明します。併せまして擁壁の改修工事等もありますので、その前に擁壁の工事の内容、こちらについても併せて説明する予定になってあります。","id":"exchange-047"},{"speaker":"安藤委員","kind":"質問・要望","question":"保育園ができた後の駐輪の問題ですとか、送り迎えの問題ですか、あと子どもの声についての不安というものもちょっと出されているのは事実なのです。ある程度そのような案の段階から住民の声も伺って、その辺について、先ほどの時期の問題と併せてご見解を伺いたいと思います。","respondent":"若生保育支援課長","answer":"令和３年度の説明会の時期ですけれども、令和３年度になるか、３月から４月ぐらいというような予定で聞いているところです。具体的には申し上げられないのですけれども、今後の近隣説明会の際には、そういったところも踏まえてご説明させていただければと考えています。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"ごめんなさい。聞き落としたかもしれないのですけれども、石綿調査等ということですが、アスベストは大丈夫なのか尋ねました。","respondent":"若生保育支援課長","answer":"今回も改めて調査を行いまして、一定アスベストのほうは検出されているということで、こちらについては法令に基づいて適切に処理してまいるです。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"２月着工だからまだですよね。これは住民の方には、そうしたこともきちんとご説明してご理解いただいているということでよろしいか尋ねました。","respondent":"若生保育支援課長","answer":"こうしたアスベストの関係も、先ほど申しました１１月３０日のときの解体工事の説明会で説明をさせていただいたところです。","id":"exchange-050"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そのようなものをやはり示してほしいではないですけれども、情報提供してほしいという声を複数のところでいただきまして、いかがでしょうか。その２点だけ尋ねました。","respondent":"若生保育支援課長","answer":"保健所のほうと密な連携を取りながら、少しでも現場の不安を払拭できるような形で、私ども保育支援課のほうも対応させていただいているところです。そういったところでは保健所の指導というか、保健所のほうのご意見も伺いながら、臨機応変に対応してご案内しています。","id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"何かもう少し、さらに不安に寄り添っていただいて、丁寧にやっていただければ幸いです。もうやっているかもしれないのですけれども、重ねてお願い申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"２点ほどお伺いしたいと思います。２点目なのですけれども、既に手続きが始まっていると思うのですが、現段階での配布状況が分かれば説明を求めました。","respondent":"立木保育課長、若生保育支援課長","answer":"保育教諭に関しての考え方なのですけれども、今、保育教諭という職の在り方を特別区として整理を進めている最中だというふうに聞いております。実質的には保育教諭と同様の扱いといいますか… こちらは１２月から、事業者のほうに区のほうで支給を開始しておりまして、順次進めているところです。若干遅れている部分の園もあると聞いておりますので、その辺は柔軟に対応させていただければと思ってあります。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/247429?Template=document&Id=5022#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":57128,"voices":144}},{"id":"r03-20210119-5","meetingId":"r03-cm01","date":"2021年1月19日","dateIso":"2021-01-19","committee":"総務委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"令和３年１月１５日付組織改正","agenda":"令和３年１月１５日付組織改正","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"保健整備担当は、部長級ということですけれども、品川区保健所との役割分担についてご説明ほしいと求めました。","respondent":"佐藤企画調整課長","answer":"新設する保健整備担当の役割ですが、主に新型コロナウイルス対策の全般を担うというところです。４月に設置した保健体制整備担当はＰＣＲ検査の業務を担うもので、今回設置するのは文字通り予防接種を所管しますので。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる日常的な保健所業務は品川区保健所が行うということでよろしいのか確認させていただきたいのと、あと、誰がどこからいらっしゃるのか。どこも大変ですけれども、専門性が高いといったらいいのか尋ねました。","respondent":"佐藤企画調整課長、榎本総務部長","answer":"前段のご質問ですが委員ご指摘のとおり、日常的な保健所業務も当然ありますので、それに関しましては品川区保健所等が担うということです。 基本的には、秋山選挙管理委員会事務局長がこの担当部長を兼務するという発令を出しております。新型コロナウイルス予防接種担当につきましては、豊嶋をこの担当課長として置くとしております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"部長級の保健整備担当ですけれども、選挙管理委員会事務局の局長が兼務ということなのでしょうか。そういうドクターだったり保健師だったり様々な専門的な視点での判断というのが求められると思うのですけれども、もう少しご説明いただけますか。","respondent":"榎本総務部長","answer":"感染症対策に専念してもらうためにはほかのいろいろなことがこれから発生するので、それをこの担当部長のほうで取りまとめてもらって、より効率的にいきたいという形です。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今、体制としては分かりましたけれども、そのほか職員の人数とかは、どうなるのか尋ねました。","respondent":"榎本総務部長","answer":"資料の左下に「保健体制整備担当（主査）制」とあるのですけれども、ここに新たに４名をつけまして、その４名が新型コロナウイルス予防接種担当の下について準備を進めていくという形です。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"その４名の方というのは、ほかからの異動というか、区全体の中でどのように考えてどこからどのように持ってきたのかとか、新しい人が入るのかとか説明を求めました。","respondent":"榎本総務部長","answer":"異動したのは１名、残りの３名は兼務という形になっていますけれども、一応籍としては前の部署の籍も残していく形です。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、それとも基本しばらくこの体制でいって、何か次にまた変える事情があったときに変えるのか。それとも基本的にこれでずっといって、また変える事情があったときに変えるという考え方なのか、その辺を教えていただけますか。","respondent":"佐藤企画調整課長","answer":"２月下旬の医療機関の従事者を含めて来年度以降も続けていきますので、その辺が一定目途がつくといいますか終わるまでは、こういった組織が必要だと考えております。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"何を言いたいかというと、会派の要望の中では、教育・医療とかいろいろな分野でコロナ対策の対応がばらばらに行われているわけではないですか。品川区で新型コロナウイルス感染症の専門部署というところを設けてほしいという要望を出したのですけれども、それとはまた違うということですね。","respondent":"佐藤企画調整課長","answer":"本日ご説明している組織に関しましては新型コロナウイルス感染症の予防接種とＰＣＲ検査、仮に委員ご指摘の全庁体制というのは新型コロナウイルス感染症対策本部会議というのが設置されておりますので、そちらのほうで今後決めていくというところだと考えております。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"新型コロナウイルス予防接種担当が新設されましたけれども、これもちょっと聞いたのですが、第１回ワクチン会議というのが開かれたとお聞きしたのですけれども、その内容などは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"第２４回品川区世論調査","agenda":"第２４回品川区世論調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"防災対策から災害対策に変えたその理由を伺いたいと思います。つまり、もうずっと今回で言う災害対策が上位にあるだけに、表現を変えたのはどうしてなのかと思いまして、ご説明ほしいと求めました。","respondent":"大澤広報広聴課長","answer":"より分かりやすく区民の方にこちらの意図するところが伝わるようにと思って、修正を幾つかしているところがあります。災害を防ぐということだけではなくて、災害が起きた際の対応も含めて表現したいということで、「災害」という表現に変更しております。","id":"exchange-009"},{"speaker":"新妻副委員長","kind":"質問","question":"この２,５００人が増えている数なのかということをお伺いしたいのと、回収率がそのことによって何か変化があったのかということもお知らせください。今頂いているものは概要版ですが、冊子の調査結果には、年齢別にどういう声が挙がっていたのかというのは出されるということでよろしいか尋ねました。","respondent":"大澤広報広聴課長","answer":"前回までの有効回答数１,０００を得るために対象人数を増やして、１,０００以上の有効回答を求めたものです。ただ今回品川区の場合は、他区と比べて６１％とかなり高い回収率になりましたので、前回よりも有効回答数は増えております。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"逆に４ページの重点施策については、その上の「子育て支援」も２５.０％から２０.３％というふうに要望にかなり大きな開きが出ているということは。２年たって、このように急激な変化があるということは、やはりチョイスの面で課題もあると考えておいたほうがいいのか尋ねました。","respondent":"大澤広報広聴課長","answer":"一つ今回の調査では回収方法を訪問から郵送に変えたことで、女性の方の回答率がかなり高くなっています。積極的にお答えいただけたのかという考えを持っていて、そういう意味では、今の時点で推測できるのかなと思います。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、どういう方が答えてくれるかによって相当変わってきてしまうということは、頭に入れておかなければ駄目だということですか。どうか尋ねました。","respondent":"大澤広報広聴課長","answer":"抽出の時点ではかなり細かく１５０地点に分けて、今回の調査のまだ感想ですけれども、今後少し細かく分析していきたいと考えています。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問","question":"もっと災害についてより強く区民の方にこういうことをやっているということを知ってもらう広報、告知、啓発が必要なのかどうか。ちょっとお考えだけお聞きしたいと思います。","respondent":"大澤広報広聴課長","answer":"「品川区世論調査あらまし」には載せていないですけれども、質問の中で、災害の場合にどういう手段で情報を入手しているかという質問が入っておりますので、その辺、結果をまた細かく分析して、それに対応する形でやっていきたいと考えております。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"課長もおっしゃるとおり、いろいろ取り組んでいただいているのは分かっているので、これから本当に所管のほうと連携を取ってやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"今聞きたいのは、この「災害に強いから」という言葉は、どういう意味でお選びになったのか。ちょっとお話を伺いたいのと、そう言われてみればどういう意味なのかなと思ったので、教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"言葉の選び方については今後も所管と相談しながら、より適切にこちらの聞きたいことが伝わるように工夫をしてまいりたいと思います。質問項目とか選ぶ項目も考えていただき、そのあたりの知恵も拝借しながら進めていきたいと思います。","id":"exchange-015"}]},{"id":"topic-03","title":"新型コロナウイルス感染症緊急事態宣言下の対応","agenda":"新型コロナウイルス感染症緊急事態宣言下の対応","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"質問は６番の職員の応援派遣等ということですけれども、例えば人数で言えば昨年と今とどのぐらい変化があるのか、単純に伺いたいと思います。体制が追いついていないという認識はあるのか、どのようにお考えなのか、そこを伺いたいと思います。","respondent":"黒田人事課長","answer":"今、別に２０名くらいの規模で保健所に応援を入れて、そういった電話をかける業務に当たっております。そういった対応をしていくというところで、当面３月末まではこの体制で、各部からの応援を入れながら体制を組んでいきたいと考えておるところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"家族３人自宅待機になりまして、さらなる体制強化が必要だと私は実感をするのですけれども、改めていかがか尋ねました。","respondent":"黒田人事課長","answer":"なかなか人の配置は保健所のほうも苦慮しているということですので、庁内で応援できるところについては応援して、引き続き体制を図っていきたいと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、今の現状の感染拡大の深刻さからすると、やはり支援が追いついていないと私は思っております。さらに職員の応援の実施・強化を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"感染防止策を徹底して開催ということと、それから中止というのは、あくまでそれぞれの所管での判断ということなのでしょうか。品川区としては、こういうことで感染防止策は徹底しようというような方向性を決めているのか、その辺について伺いたいのですけれども。","respondent":"立川総務課長","answer":"いわゆるイベントの開催はどういった形で実施するかにつきましては、新型コロナウイルス対策本部会議等で全体調整を図るという流れになっております。それに伴いまして、そちらの基準を最低限クリアした上で、所管として開催すると判断した場合は開催していくところです。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちょっとその辺の流れについて、開催の可否にばらつきがあるということが気になるので、教えてほしいと求めました。","respondent":"立川総務課長","answer":"まず、高齢者作品展を開催した理由を簡単に申し上げますと、期間中のいわゆる来場者数見込みというのがかなり限られるというところがまず１点です。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"思いのほかたくさん来るということもあるわけですから、ぜひそういう区としてのガイドラインを持ってしかるべきではないかと思います。もし何かお考えがあれば、説明を求めました。","respondent":"立川総務課長","answer":"区といたしましてはそのガイドラインを重視しつつ、なるべくできることなら開催という方向で、今後もやっていきたいとは考えているところです。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"品川区の中でも自宅療養中、それからあとはホテル療養中も含めてそうなのですが、入院や療養先の調整中という方もかなりいらっしゃるのですか。もし分かれば説明を求めました。","respondent":"立川総務課長","answer":"ただいまのご質問ですが、本日厚生委員会で保健所の対応について詳しく説明をされているですので、いただきましたご意見につきましては、現状の所管のほうに伝えたいと思います。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"運動に対してもこうやって制約を受けるということが果たしていいのかというのを、私は総務課でも企画調整課でもやはりきちんと考えてほしいです。今、逆に今度悪い方向に一部の人は進んでしまうのではないかと思いますので、そういうことを総務課のほうでも私は考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問・要望","question":"１点お聞きしたいのですけれども、一応ここに書かれているのが全てなのかどうか分からないのですが、そういう選択肢を考慮した上で中止になったのかというのを教えてほしいと求めました。","respondent":"立川総務課長","answer":"こちらの主なものということでお示しさせていただきました。例えば、戸越三丁目と西大井三丁目の２カ所で実施する予定でございましたけれども、状況を見ながら３月に延期ということで現在考えているところです。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"意見","question":"もちろんそういうお話し合いもあったのだとは思うのですけれども、今後も延期ができるものかどうかというのをしっかり考えていただきながら、こういうことで中止だということがなければと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"緊急事態宣言下ということですから、これは１月８日から当面２月７日、多分会場はそれほど直前に取ることはなかったと思うのです。そういうどこでキャンセルしたか、１月８日からしか還付の対象にならないのか、その期間というのは設定があるのか尋ねました。","respondent":"立川総務課長","answer":"対象者ですけれども、１月８日から３月３１日までの期間に施設を使用する者ということで、対象者を特定しています。それから、申請の取り下げの受付期間につきましては、さかのぼりまして１月４日から、現状のところ２月２６日としております。","id":"exchange-026"},{"speaker":"松澤委員","kind":"質問・要望","question":"質問より要望になってしまうのですけれども、やはりこの主なイベントの中で所管が判断となると、所管が駄目というならもう駄目なのですよね。何とかできるように対応してほしいという、改めて要望だけになってしまうのですが、そのようにやってほしいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"令和２年職員の給与等に関する報告の概要","agenda":"令和２年職員の給与等に関する報告の概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２３区の平均がもし分かれば教えていただきたいのと、国等の目標が幾らなのか、現状を伺いたいと思います。区としては、取得率が目標に達していない、つまりは低いその原因についてはどのようなお考えをお持ちなのか、併せて伺いたいと思います。","respondent":"黒田人事課長","answer":"正確な数値がお答えできないのですが、短期間であっても育児休業を取るという職員が増えてきてありますので、そういった意味では子育てをしながら仕事をするというような環境の整備には努めてまいりたいと考えています。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"０歳で入らないと１歳児では入りづらいというこの現実がある中で、さらなる認可保育園の増設など、必要な社会的資源の構築が必要かなと思います。ここをしっかり取り組んでいただきたいなという思いで指摘させていただいているのですけれども、最後に伺いたいと思います。","respondent":"黒田人事課長","answer":"先ほど言った環境を整備して取り組んでいただいて、職員に限らず全体的に取り組んでいるところですので、そういうところも含めて今後の取組を進めてまいりたいと考えています。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"これが必要ですよとか、例えば２の（１）の「リモートでの業務遂行の課題を解決し、その辺の読み方を教えていただきたいのが一つです。これはどういうことを区に対して意見として特別区人事委員会がおっしゃっているのか、どのように受け止めておられるのか伺いたいと思います。","respondent":"黒田人事課長","answer":"例えばその「保育教諭等への対応」というのは、そういった意味では「引き続き検討」というようなことが書かれているということです。そういった細かいところについて、そういった２３区としての制度の関わりについても、今回特別区人事委員会のほうで報告として触れているです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。では、そちらの冊子のほうを拝見して、さらに分からないことがあったら、改めて別の機会で質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、これだけ民間の現在の実態とかけ離れたこういう概要の報告書が出るというのはどうなのかなということだけは、私は指摘しておきたいと思います。こういう取りまとめの時期もやはり今後考えるように、特別区人事委員会に区として意見を言っていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]},{"id":"topic-05","title":"会計事故防止のための対応策","agenda":"会計事故防止のための対応策","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは１点だけなのですけれども、この対応というのは、例えば２３区の中でも品川区の独自のものなのか。品川区を含め、事故が防げる対応につながっていくのではないかと思うのですけれども、その点だけお伺いしたいと考えています。","respondent":"中山会計管理者","answer":"今の指定金融機関に伺ったところ、品川区のみが今回これを採用するということで、当然ながら他区のどこも採用している仕組みではございません。","id":"exchange-033"},{"speaker":"須貝委員","kind":"意見","question":"もう間違いが起きないように改善をされたということに関しては、私は感謝しているし、やはりすばらしいものだと思います。ではうちの区でもとは、本当にいい制度・ルールを作っていただいて、私は逆にありがとうありますという感謝を申し上げますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"吉田委員","kind":"確認","question":"確認なのですけれども、今までご説明を伺う中では、品川区の方の対応さえきっちりやっていれば防げるようなシステムになっているのか。具体的にこういう実務を知っているわけではないので、イメージがわかないところがあるのですけれども、その辺をぜひ伺いたいと思います。","respondent":"中山会計管理者","answer":"今回やはり一番分かりにくかったのが、データを送信した、でも届いていないというようなお話がありました。指定金融機関側もはっきりとその事実を認識するということになりましたので、品川区の責は問われないというような形にはなろうかと考えています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"だから、いやいやこういうふうになっていますということを品川区としてちゃんと主張できるようなシステムになったという理解でよろしいのでしょうか。ちょっとその辺をお願いします。","respondent":"中山会計管理者","answer":"そのとおりです。この画面のコピーにつきましては、指定金融機関のほうでもしっかりとチェックをしていただいているところです。","id":"exchange-036"},{"speaker":"湯澤委員","kind":"質問","question":"この説明文の中で、「協議が整い口座払と随時払については」というふうに書いてあると思うのですけれども、この「ついては」という表現だと、ほかにも何かあるということなのか尋ねました。","respondent":"中山会計管理者","answer":"給与は４日前、そういう意味ではその時間的な余裕において指定金融機関側でもしっかりとチェックを取れる体制にあるということになっています。今回この２つについては決済後方式に、変更することといたしました。","id":"exchange-037"},{"speaker":"湯澤委員","kind":"質問","question":"今回こういった事故があった原因としては、その人的なものと、二重送信できないようなシステムに今回対策を取られたというふうに認識をしました。今回の防止策によって、会計管理室内でも、それから指定金融機関との間でも起こることはなくなっていくと判断してよろしいか尋ねました。","respondent":"中山会計管理者","answer":"当然ながら職員にルールを徹底しましたのと、まずここでほぼほぼ二重払いはないという形で考えております。二度と起こさないようにということで、会計管理室でも、また指定金融機関とも一緒に協議をしたところです。","id":"exchange-038"},{"speaker":"湯澤委員","kind":"質問・要望","question":"職員の皆様も本当にご自身の責務を一生懸命果たされていると思いますし、今の説明で安心したところでありますので、過誤がないように、そして二度とこういった事故が起こらないように、これからも対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"それに対する苦情とか、あと衣装その他着物ですけれども、それに対するキャンセル料に対する費用などの苦情とか、そういうこともあったのでしょうか。逆に、今回の対応は、よかったのではないかという様々なご意見があったと思うのですが、もしありましたら説明を求めました。","respondent":"立川総務課長","answer":"遠方から、ツイッターで、遠方だけれどもオンラインなので参加ができてとてもうれしいですといった感想も頂いております。晴れ着のキャンセル料についての補償等の問い合わせについては、現在のところないという状況です。","id":"exchange-040"},{"speaker":"新妻副委員長","kind":"質問","question":"記念品が毎年参加された方にはあるかと思います。その記念品の対応もどうされるのか、お伺いしたいと思います。","respondent":"立川総務課長","answer":"今週中に配布する予定ですが、例年大体５０％ぐらいの方が参加されるので、全員分がないのです。それが約２カ月かかるということで、３月下旬にお届けしますということを、新成人の方に通知でお知らせする準備をしています。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問","question":"実行委員の１２名とおっしゃいましたね。そのときに、職員の方かどうか分からないのですけれども、職員の方は当日きゅりあんの会場にスタッフとして何名ぐらいいらっしゃったのか尋ねました。","respondent":"立川総務課長","answer":"やはり周知が行き届かなくて、結構な方がお見えになるかとは想定していたのですけれども、そうではなかったのですが、総務課の職員は全員出ておりまして、なおかつ副区長、教育長等も会場にいましたので、そういった状況で開催されたということです。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/740650?Template=document&Id=2188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":28295,"voices":110}},{"id":"r03-20210120-14","meetingId":"r03-cm01","date":"2021年1月20日","dateIso":"2021-01-20","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"６号棟について、これは１年半、情報がありましたらこの場でお伝えほしいと求めました。","respondent":"佐藤企画調整課長","answer":"町場のほうに入っていただいて、きちんとご説明をしていただきたいというのは区のほうからも何度も伝えていますので、区と国でまた考えているです。地域の方々にご不安を与えないように、丁寧に対応していきたいと考えております。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"いろいろと対応もしてほしいと言っているのだけれども、その方との個別対応や協議、そういうものはどのように進展しているのか。あるいは話し合いがどのぐらい進んでいるのかということをお伺いしておきたいと思います。","respondent":"佐藤企画調整課長","answer":"これまでの説明の確認になりますが、その方自体の近況とか、そういったお話し合いをしています。原案をつくって、また丁寧に対応していきたいというところで、引き続き区としてはお話をしています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"もちろん丁寧に対応していただかなければいけないのですけれども、ご納得されるような方向で話し合いが進んでいるのかどうなのか、もう少し具体的にお話を伺えればいいかと思うのですけれどもいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"納得していただけるように引き続き丁寧な説明をしていくというところで、まずは情報共有と、お考え等の確認をしていくです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の説明で、解体が２年ぐらいかかるということだったと思うのですけれども、そうすると、解体への着手というのはいつになるのでしょうか。令和３年、４年の２年間で、６号棟に関して解体が行われる、峰友寮と併せて３年、４年という形で行われるということになるのか尋ねました。","respondent":"佐藤企画調整課長","answer":"令和３年度、４年度に解体工事を行いますというところでありまして、区側にはまだ提示されていないところです。２点目のご質問の説明会はいつかというところも、設計が終わらないとなかなか時期は明確に言えないということですので、今そういった状況です。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、解体はとりあえず令和３年、４年のところで、おおよそ令和４年度中には終わると考えていいのでしょうか。そしてその後、解体が終わった令和４年度で取得をしたらすぐに工事が始められるということで、そういうところは進めているということなのか尋ねました。","respondent":"佐藤企画調整課長","answer":"基本設計、実施設計のほうを国が解体している間に進めたいと考えておりますので、そういう形で進めていくところを内部で検討しているところです。まずは国が設計を終わらせて、またスケジュールを新たにお示ししていきたいと、そのほうが確実でいいと考えております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都有地、峰友寮、それから６号棟のところの敷地のそれぞれの平米数を教えていただけないでしょうか。売買契約締結予定が今年の２月ということで書かれているのですけれども、あと、ここのところも幾らなのかというのも教えていただけたらと思います。","respondent":"佐藤企画調整課長","answer":"令和元年に住民説明会をさせていただいたときの内容、防災倉庫、障害者施設というところを軸に進めていくというところは方針で書いています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それから、建物の設計というか、おおよそどんな建物かというのはいつ頃に分かるのかということも説明を求めました。","respondent":"佐藤企画調整課長","answer":"申し訳ございません。建物の実際の中身に関しましては、そちらに関しましては、今後また予算の計上について議会のほうにお諮りすることになるかと考えています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区としてもできる部分があるのではないかと思うのですが、そういうのは具体的にこういう対応ができますとかというのは、ご当人とお話しされたりはしているのか尋ねました。","respondent":"佐藤企画調整課長","answer":"ご質問は、国が行う解体の際の騒音の防止を区で行うかというご質問ですか。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"例えば、これは区が施設を建設していくわけなので、区の事業に協力してくださる家庭への対応ということで、例えば、従前居住者住宅とかをその間活用していただくとか、そういう対応というのも可能なのではないかと思ったのですけれども、そういうのというのはいかがなのか尋ねました。","respondent":"佐藤木密整備推進課長","answer":"私のほうからお答えしますが、今回、この保育園等の建設に当たっての事業に協力という意味での入居というのは難しいと考えております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"様々な訴えがされておりますので、ぜひどういうことができるのかということも含めて丁寧なご説明、対応をお願いしたいと思います。近隣の方にとってはかなり大変な思いをされることになると思いますので、そこの説明会というのもしっかりと丁寧にやっていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認をさせてください。解体の設計は終わりましたかとか、終わったらすぐに解体してくださいという連絡は取り合っていると思うのだけれども、そこだけ確認したいと求めました。","respondent":"佐藤企画調整課長","answer":"解体工事に向けた国との連携の状況ですが、敷地内であれば国のほうにお願いしますので、その辺は緊密に連携を取ってやっているところです。今後も引き続き丁寧に対応してまいります。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"これを詳しく教えていただきたいのですけれども、イルカショーへの批判の声が水族館の生物全体に及ぶというのはどういうことを想定されているのか。３ページ目の、もう少し詳細にというか、具体性を持って言うとどういうことが望まれているのかということを教えてほしいと求めました。","respondent":"高梨公園課長","answer":"要するによくないような対応をしているのではないかというような形で、イルカショーに関連して、よろしくない管理運営をしているといったような形で。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"このアンケート結果の中でも如実に出ていて、しながわ水族館が品川駅とつながってしまうというのは大いに想像できるところです。3)とか4)、令和３年度からの検討ということを進めてほしいと求めましたけれども、何かありましたら最後に一言お願いいたします。","respondent":"高梨公園課長","answer":"今いただいたご意見は、検討委員会、専門家会議で出たご意見の方向性に沿うものと感じておりますので、まだ今年度、検討が進んでおりますけれども、しっかりと検討を今年度に完結させて、来年度、またそれを踏まえて進むべき方向性について検討を進めていきたいと思います。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"どういう水族館なのだというのが、何とか何とかしながわ水族館みたいなものがあるというのもいいのかと思ったりもしますので、ご参考にしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"芹澤委員","kind":"質問・要望","question":"数点お伺いしたいのですが、いわゆる海洋生物だったり、動物のショーに対して何か話が出ているというものではないという認識でいいのでしょうか。今、これの今後の方針というのは令和３年度から始まるということで、今は特にそこの議論には至っていないという認識でよろしいのか尋ねました。","respondent":"高梨公園課長","answer":"決めていこうと考えていますが、区民公園を活かした、水族館と一体となるといったところのご意見をいただいているところです。水族館を活かした公園づくりということで、水族館の魅力を向上させるようなしつらえをして、公園の再整備を行ったといったところです。","id":"exchange-015"},{"speaker":"芹澤委員","kind":"質問","question":"最後に１点だけ、今、そういった財源をどこかで確保してというような議論もここに含まれているのでしょうか。説明を求めました。","respondent":"高梨公園課長","answer":"どうしていくのかという大きな方向性を出した上で、細かなところについては議論をしていくということになろうかと思います。別の水族館だとしっかりと認識をしていただくような名前というものを検討するべきではないかというような話は、会議の中でも出ているところです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、やはり前回、本当に大人の知的好奇心を刺激するような社会教育施設としての役割を持った水族館であってほしいと思っています。入館料と、それから区の一般財源からどれぐらい出されているのか、財源のところを教えていただけたらと思います。","respondent":"高梨公園課長","answer":"冒頭の委員会でもご説明をさせていただきましたが、負担金として約２億円を一般財源から支出している、このような状況です。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"しながわ水族館に求められるもので、これが前向きな話なのか、後ろ向きな話なのか。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須貝副委員長","kind":"意見","question":"３番目にしながわ水族館に望まれる役割というのがありますけれども、継続のほうにこれだけ文面が割かれていて、少し残念だと思いました。では、課長、お願いいたしますとの意見を述べました。","respondent":"高梨公園課長","answer":"今年度行っています専門家会議や検討委員会では、水族館の存廃、どちらかを前提としますといったような条件はつけてございません。本年度の会議での検討のご意見であったり、来年度以降、進めていく方向性について検討していきたいと考えています。","id":"exchange-019"},{"speaker":"大沢委員","kind":"質問・要望","question":"それを前提に一つだけ伺いたいと思うのですけれども、最近どうなっているか分かりませんけれども、私は二つの切り口があると思いました。２の現状ということで減っているわけでありますが、あるいは検討会等々でお話に出ていれば、現状を教えていただきたい。","respondent":"高梨公園課長","answer":"しながわ水族館はケーブルテレビ品川と連携しまして、ＹｏｕＴｕｂｅで水族館の水槽のライブ映像を流すといったような取組みをさせていただきました。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"ここのところ、ＹｏｕＴｕｂｅに対する分析、あるいはもう少し活用の仕方を十分に検討していただく価値はあるのではないか。検討方いただきたいとは思うのですけれども、あるいはもう一つ、あるいはお考えを改めてお聞かせいただきたい。","respondent":"高梨公園課長","answer":"検討もしていない内容でございましたので、こういった媒体の活用というのは進んでいく方向であると考えておりますので、内容についてしっかりと勉強させていただきたいと考えています。","id":"exchange-021"},{"speaker":"大沢委員","kind":"意見","question":"その後、いろいろと先ほどお話しした付随した収入も考えられるわけでありますので、そこら辺の検討方をお願いできればと思います。ご答弁は要りませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"区立館としてできるのではないかということを思うのですけれどもいかがでしょうかということと、あと、今後の方針検討が令和３年度からということで。先ほど存廃という話とかもありましたけれども、そういったことも含めて、どういったことが検討されていくのかというのをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"１点目の、検討委員会の中では、大学ともしっかりと連携をしていければと所管としても考えているところです。今後の検討の内容についてなのですが、どこに設置するべきなのか、考えていければと考えているところです。","id":"exchange-023"},{"speaker":"せお委員","kind":"質問","question":"少し細かいことになってしまうのですけれども、来館者の方たちは、ここ近年ですと、アクセス方法はどれが一番多いのかとかが分かりましたら説明を求めました。","respondent":"高梨公園課長","answer":"平日とかは無料バスが多いといったことがあるのですが、入館者が多い土日ですと、やはり車の利用が多いということがあります。少し駅から離れてはいるものの、高速等からのアクセスがいいということで、車で来館されるお客様が多いという状況です。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"あまり移動したくないのです。この前視察に行ったときは何もない状態だったのですが、あそこら辺というのは今後どうなっていくのか、決まっていましたら説明を求めました。","respondent":"高梨公園課長","answer":"確かに改修前はいろいろと軽食であったり、グッズを出すお店を設置しておりました。飲み物等を買っていただいて、新しくなったデッキでお弁当を食べながらくつろいでいただきたいといった趣旨で設置する計画、予定となっています。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"いいですし、来ていただく方も喜んでいただけると思うので、そういったところもぜひ検討していただきたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/444693?Template=document&Id=6102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25481,"voices":85}},{"id":"r03-20210121-18","meetingId":"r03-cm01","date":"2021年1月21日","dateIso":"2021-01-21","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"品川区の総合体育館や戸越体育館はどういう状況なのか、そこら辺を少し教えていただきたいです。そこら辺のお考えと、お考えがあれば、その辺も説明を求めました。","respondent":"中元スポーツ推進課長","answer":"実際に設営するときにきちんとそういう場所を、入り口からの動線も含めて検討してつくっていくという形になるかと思います。施設改修ということよりは、あらかじめそういうスペースを考えながら席をつくっていくということで、行ってまいりたいと考えているところです。","id":"exchange-001"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる臨場感というのでしょうか、そうした対応をされているところもありますが、そういうものがいいのか。これは健常者と同じように楽しめる環境ということも、あってもいいのではないかと思うのですが、そういう点ではどのようにお考えか尋ねました。","respondent":"中元スポーツ推進課長","answer":"施設的には磁気ループのようなものを設置ということかと捉えているのですけれども、現在、受け入れ体制はとっております。今後、改修などのタイミングで、そのようなご要望がありましたら、検討して前向きに考えていきたいところです。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問・要望","question":"スポーツをやるきっかけというのは、見たり、聞いたり、触れたりというところからかなと思うと、そうした環境も整えていけるといいと思いました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"排斥というのでしょうか、私は上から観戦、観覧したいのだという選択の余地がなくなってしまうわけですよね。今日はこの委員会で、スポーツ推進課が所管する施設になろうかと思いますけれども、そのあたりの考え方について説明を求めました。","respondent":"中元スポーツ推進課長","answer":"施設の、改善の考え方ですが、必要に応じてそういうところは今後きちんと合理的配慮の中で考えていかなくてはいけないところだと認識しております。やはり何らかの対応というものが、そこも含めて、また調査・研究させていただければと思います。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"客席をどう確保するか、フレキシビリティな席の設えというのは絶対必要だと思いますので、これは強く要望しておきたいと思います。そういう考え方、設備のあり方はお願いしたいと思うのですけれど、再度何かご答弁ほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"委員おっしゃるように、そういうお声がないという状況でも、やはり先を見てきちんとそういう対応を今後心がけていきたいと思います。総合体育館や戸越体育館の周りにそのような施設がなかなかとれていないというところが、バランスがよくないかなということは実感しています。","id":"exchange-005"},{"speaker":"つる委員","kind":"提案","question":"これは再三、ハード面の土木関係の部署にも活用というところで提案をしているわけですけれど。私もやってみようという背中を押す、大きな材料の一つになるのではないのかと思いますので、ぜひそこは公共の担い手としてお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"提案","question":"それは、品川区文化芸術・スポーツのまちづくり条例が平成２０年から施行されていますけれど、議会からの提案をさせていただいた条例の一つです。ある程度方向性は、大きな感覚でお答えいただければと思うのですが、いかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"そのようなスポーツを見ることができるようなところを検討していきたいというようなことは少し書かせていただいているのですが、何しろやはり土地が。ただ、何かいい提案とかも含めて出てくると、そういうことももう少し前に考えていけるのかなと思っているところです。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区が独自でやることだけに限らず、いろいろな費用のやり方もあると思いますので、その辺も踏まえた上でご検討をお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"この２点を提案させていただきましたけれど、この点について、区の考えを伺わせてほしいと求めました。品川区で今、これらの現状というのはどうなっているのか、１点伺いたいと思いますとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"２点目の、現役の方も取り組める社会の実現というところでは、スポーツに取り組む時間が難しいというところがあります。なかなかスポーツセンターに来ることができない方も自宅でもできるとか、そのようなものも研究していきたいところです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"できるところから充実していくというのは、私は可能なのではないかと思うのですけれども、こちらはいかがでしょうか。先ほど、現状はどうなっていますかという質問もさせていただいたので、ぜひそちらについてもお聞かせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"初級の方が８人で、中級の方が２人ですか、いらっしゃいます。そのような、まさに身近なところで区民の方が、健常者の方も一緒にまず取り組んでいくというところを地道にやっているところです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういう、人材の育成なども含めて、障害者の方々のスポーツ環境の整備をできるところから、身近な自治体として充実していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"２０１９年の行財政改革特別委員会の資料の中で、アリーナ新設を進めるための、今回のこの議論なのですか。新設が予定されているのかどうかと併せて伺いたいのですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"各会派からいろいろな要望を出していただいて、行政がどうこうという話では、まず全くない。だから、計画があるないなどということも一切なく今日は議論しているので、それを念頭に質問していただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"確認","question":"では、アリーナの新設やそういう計画はないということで、今、確認をしました。〔「行政が決める話でもなくて」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"田中委員","kind":"確認","question":"今、オリンピック・パラリンピック推進特別委員会の中では、スポーツだけをする施設がアリーナとなっているのでしょうか。確認したいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡部副委員長","kind":"質問","question":"先ほどからのご質問、障害者スポーツに対してどういうふうに、それを念頭に質問されればいいことです。例えば障害者スポーツをどうしたいのか、区民の方々の声をどう届けたいのかということがあれば、それはお伺いすればいい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"では、フラットな状態で伺いたいのですけれども。そこら辺の考えというのを伺いたいと思いますし、皆さんとも議論ができたらと思うのですけれど、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"スポーツの環境を整えるという点でやはり優先すべきというのは、しっかりとした区民が使えるような、（課題として）すごく上がっているわけですね。そうした中で何を優先すべきかという点では、障害者スポーツの環境の充実、区には力を入れてほしいというのが私たちの意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"磁気ループについてのお話があって、ぜひ当事者の方たちの声を待つのではなく、聞きに行ってほしいということをいつも思っています。そういったことを求めたいのですが、いかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"障害者団体の方２名に入っていただいたりしておりますので、障害者福祉課も交えながらご紹介いただいて、ご意見を伺えればと思っています。体育館という大空間で果たしてそういうものがどういうふうに機能するのかとか、その辺のところも調査・研究させていただければと思います。","id":"exchange-019"},{"speaker":"田中委員","kind":"意見","question":"もしこの先改修があるようでしたら、当事者の方たち、車いす利用の方たちや視覚障害の方たちが実際にそこを使ってみて、こういうところをこうしてほしいといった声を聞いてほしいと思うのですが、そこら辺もご答弁いただけたらと思いますとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"今のところ改修の予定がないので、はっきりとはお答えが難しいのですが、もちろんそういう場合にはそのような方々のご意見も教えていただきながら、工夫してまいりたいと思ってあります。","id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都との立て分けの中で、城南地域にも東京都の障害者スポーツ施設を区が求めているという話もありましたが、それは本当に理想であるなと思います。知的障害者の方も年に１回の運動会を戸越体育館で行われていたり、障害者の方の利用のご紹介を少し教えてほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"今回は手持ちがございませんので回答ができないのですが、予約もなく参加できるような形でフリースポーツの場をつくらせていただいております。毎年９月には水泳大会ということで、今回はコロナで中止になっておりますが、そのような形で長年続けさせていただいているところです。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"今後は何かそういう考え方が必要ではないかと思いますので、そこら辺の視点も踏まえた施設のあり方もご検討ほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"それを活用していただくことによって人出があるわけですから、それによってまた地域も活性化していくのかなと考えます。これも質問というより要望になってしまうかもしれないのですが、何かの折に、そういう観点でぜひ考えてほしいとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-02","title":"大井ふ頭中央海浜公園の利用休止","agenda":"大井ふ頭中央海浜公園の利用休止","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"工事に伴う利用中止ということですが、具体的にはどのような内容の工事を、どこにやるのかということだけ、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"サブピッチも今は開放といいますか、ホッケー協会中心に利用しておりましたが、また追加で仮設の座席を設置します。スタッフの休憩所ですとか、選手の練習のピッチですね、そういったものの整備が行われるというふうに聞いております。","id":"exchange-024"},{"speaker":"新妻委員","kind":"確認","question":"１点だけ確認します。６月まではこのドッグランは使用可能で、７月以降、オリンピックの期間も含めて使えないというふうになるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"７月に入りますと、こちらは使えなくなるというふうに聞いております。オリンピックの期間も使用できないというふうに、今のところは聞いております。","id":"exchange-025"}]},{"id":"topic-03","title":"東京２０２０オリンピック聖火リレー","agenda":"東京２０２０オリンピック聖火リレー","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"現状が分かればというところですけれども、１年延びたということで、１年前にここで走る予定だった方たちは、今回どうなるのか。再度選定されているのか、その辺、状況を説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"基本的には、去年と同じ方が第一候補といいますか、お願いするというふうに聞いております。その中で、走りますよという方はそのまま走るというふうになっていると聞いておりますが、まだ現在調整中とは聞いております。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"せっかく決まった方なので、特段の何かがない限りは参加して、ここを走っていただければという思いですが。１年前に計画をしていた、どのような状況なのか、説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"コースに関しましては一応、特段問題もないのでそのままでいきたいということで、お話し差し上げていく予定です。１年延びたということで、そのあたりをどうするのかということで、去年やる予定だったことより少しスケールダウンをする可能性はあります。","id":"exchange-027"},{"speaker":"こんの委員","kind":"意見","question":"現状をありがとうございました。大変に悩ましい状況かと思いますけれども、ご担当の課長はじめ品川区の取り組みとしてご苦労をおかけしますが、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"去年のときも確認させていただいたかどうか忘れてしまったのですが、例えば、当然オリンピックの公式行事になってくるのですよね。それを説明するよう求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり間近に見るのが一番なのですけれども、それができない場合、やはりテレビやＹｏｕＴｕｂｅ等で体感できるというのがベストだと思います。喜んでいただけるような状況を、ぜひつくっていきたいと思っていますので、今後も検討して頑張っていきたいと思います。","id":"exchange-029"},{"speaker":"つる委員","kind":"意見","question":"今あったように東京都との役割分担ですとか、東京都ならＴＯＫＹＯ ＭＸの関係もあり、品川区ならもちろんケーブルテレビ品川。これはもうオリンピックが開催できる、パラリンピックが開催できるという大前提ですけれど、その辺も並行してぜひ進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"西村委員","kind":"意見","question":"ちょうど暑さ対策とか、いろいろなお話をしていたことを今思い出したのですが、加えて感染症対策ということで、本当に大変なご準備になってくると思うのですが、引き続きよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"少し教えていただきたいのが、エコラ、このキャラクターは今回がデビューということでしょうか。要望だけでもしますが、どうだったのかというところまで活用されるような取り組みを、お願いしたいと思います。","respondent":"提坂環境課長","answer":"１０数年前につくったキャラクターで、一応親しまれているキャラクターかなと認識していたのですが、今後ともアピールしていきたいと考えています。４年生の市民科の中で、５年生以降は社会科の中で、いろいろな活用方法を学校のほうでお願いしたいと考えています。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"内容について監修とかをお願いしたりということも、やはり必要なのではないかと思うのですが、そういったことはあったのか尋ねました。","respondent":"提坂環境課長","answer":"あくまでこれは委託ということなので、直接指示をするというとなかなか、委託の本来の目的から逸れてしまうので、なかなか難しい部分であるのですが。そういうことを何回か重ねて、実質（区の）監修のような形で、最終的なものができたという経緯があります。","id":"exchange-033"},{"speaker":"安藤委員","kind":"提案","question":"これは非常に分かりやすいのではないかということで提案もさせていただいたので、掲載されているのは非常にいいなと思うのですが。漫画で分かりやすく提示して考えてもらえるような資料こそ、挑戦すべきだったのではないかと思うのですけれど、いかがか尋ねました。","respondent":"提坂環境課長","answer":"新たに４年生になる方に配らせていただくので、その中で改訂とかも考えてありますので、そこでまた内容を少し改めさせていただきたいと考えています。みずから図書館で本を借りるとか、保護者の方に聞くとか、そういう形で勉強を進めていただければよろしいかなと考えています。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"原発の動きなども多くの世界で取り組まれているわけですから、そういう記述もあってこそ、ぜひ次回以降の冊子作りに生かしてほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"１年生から３年生はなぜ配ってないのかという確認と、それから、こういうご自宅への啓発は非常に大事なことであると考えています。環境課として、より啓発をしていくために、私が今申し上げたような考え方は、どのように考えていらっしゃるのか、教えてほしいと求めました。","respondent":"提坂環境課長","answer":"ＳＤＧｓは４年生には少し難しいかなと、そういう認識もあったので今回は入れていませんけれど、改訂のときに生かしていきたいと思います。来年４月に環境学習交流施設がオープンする予定ですので、その中でも、環境教育で充分使えるような素材を展示していきたいと考えています。","id":"exchange-036"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後、そうしたお考えを持っていかれたらいいのではないかと、再度要望したいと思います。行くだけで学習ということだけではなく、それはそれでもっと生きるのかなと思いますので、そのようなこともされてみてはいかがかか尋ねました。","respondent":"提坂環境課長","answer":"環境学習交流施設については、工事のほうについては着工したばかりです。運営内容については来年度、１年間かけて運営事業者候補者と練り上げていくところなので、その辺も検討してまいりたいと考えています。","id":"exchange-037"},{"speaker":"湯澤委員","kind":"提案","question":"これは提案なのですけれど、例えば各所でクイズ方式みたいなものにして、「こういうのはどうだと思う？これは提案ですけれど、何かご意見があればお願いしますとの意見を述べました。","respondent":"提坂環境課長","answer":"夏休みに１・２年生、３・４年生、５・６年生対象に３種類のエコチャレンジというクイズ方式の冊子を配ってあります。そういうものも好評な部分がありましたので、今後こういう漫画の中でもクイズ方式とかを取り入れられないか、その辺も研究したいと考えています。","id":"exchange-038"},{"speaker":"湯澤委員","kind":"意見","question":"「お父さん、お母さん、こういうのって何か知っている？」ということで、家庭内でこういう啓発をしていくということが、大変すばらしい試みだと思いますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"つる委員","kind":"提案","question":"ＰＤＦで見られるほうは今からでも可能なのかなと思うので、湯澤委員から提案もありましたので、可能な範囲で早目の対応がいいのかなと。要望で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"何かいろいろ、そうしたキャラクターの整理とかも、もっとしていくといいのかなと思っているのですけれども。そのあたり、いかがお考えなのか尋ねました。","respondent":"提坂環境課長","answer":"今後とも、地球温暖化防止ですとか、様々な環境問題に取り組んでく中で、このエコラを最大限活用して周知をしてまいりたいと思います。区の中でいろいろなキャラクターがあると思うのですけれど、その辺もまた環境課とともに整理をしていく必要があるのかなと考えています。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"ではエコラは、この黄色のエコラで統一していくのか、それとも何かいろいろな、メスとか、きょうだいとか、そういうのを登場させていくのでしょうか。説明を求めました。","respondent":"提坂環境課長","answer":"ぬいぐるみのほうもこういう色をしているのですが、グリーンというのははっきり言って、私も認識がなかったです。つけていないという話については、特にこれがオスだとかメスだとか、別に性別は特定していないものだと思います。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ分かりやすく、エコラというのも伝えていっていただきたいと思っていますので、よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"せっかく作成されているのですから、利用されたらいいなと思いますので、そこについてお知らせいただきたいです。今回１回だけの契約となっているのか、ほかのお話もつくっていくような契約になっているのかなどといったところもお知らせほしいと求めました。","respondent":"提坂環境課長","answer":"もちろん事前に教育委員会のほうと内容の検討を行ったのですが、配布時の説明ですとか活用方法というところについては。来年以降、とりあえず新４年生に配るということなので、連載ということは今のところ考えてございません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/343398?Template=document&Id=6588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":38988,"voices":106}},{"id":"r03-20210122-10","meetingId":"r03-cm01","date":"2021年1月22日","dateIso":"2021-01-22","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"ごめんなさい、ちょっと、ちゃんと聞き取りにくかっただけで、ワクチンのことについて、どんなことを確認したいのか、もう一回ちょっと説明、よく分からなくて。","respondent":"渡辺議長","answer":"であればやはり、事務局、とにかく事務局一元化で問合せをする。そして情報を前回のように共有するという形が望ましいという意味で、中身というよりはとにかく問合せを議会事務局に一本化したいという趣旨です。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"ちょっと確認なのですが、何というのですか、緊急事態宣言が終わっているはずではないですか。これは、学校側は今何か聞かれている情報というのは、どういう規模でやるのかというのは聞かれているのか尋ねました。","respondent":"渡辺議長","answer":"中でも議員への対応というのは非常に、お伝えして自粛されたほうが、現場がやりやすいのかなという思いです。その他の周辺状況はちょっと承知していないのですが。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8329,"voices":44}},{"id":"r03-20210216-10","meetingId":"r03-cm02","date":"2021年2月16日","dateIso":"2021-02-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"石田（秀）委員長","kind":"提案","question":"私から１点、提案があります。ここで先ほど言いましたように提案でありますが、それから２日目の歳入、何かご意見ありますか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"意見","question":"補正と歳入も同様にということで、趣旨は理解しました。人数的なところの目安はどうしましょうかということでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"}]},{"id":"topic-02","title":"標準市議会会議規則の改正","agenda":"標準市議会会議規則の改正","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"１点だけ確認で、それとも文言、これを入れたほうがいいのかというところが気になったところです。","respondent":"米田区議会事務局長","answer":"疾病の中に含むという解釈が一般的ではあるようですけれども、やむを得ないという事由に照らしても、同じようなとり方ができるかなと考えているものです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この欠席事由の明文化はぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"確認","question":"念のための確認なのですけれども、賛成なのですけれども、現状でもこうした理由で欠席届を出すということは別に問題はないということですよね。それを明文化しただけであって、今それを却下するとか、そういうことではないということの確認を求めました。","respondent":"米田区議会事務局長","answer":"委員おっしゃるとおり、事故の中に明文化された内容が種々入っていたということが、逆にわかりづらかったというようなことであり、内容が変わるものではございません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"請願への押印の見直しということで、賛成させてほしいと求めました。例えば一般質問の通告には印鑑は要らないのだけれども、精査して確認を進めるのも必要かなと思いますので、一言述べさせてほしいと求めました。","respondent":"米田区議会事務局長","answer":"お尋ねの件の１点ですけれども、別紙２の現行の品川区議会会議規則あるいは標準市議会会議規則の現行のものの第１３３条および第１３９条の第２項、規則上は押印がなくてもという内容になってあります。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認で、この邦文というところなのですけれども、点字で請願というか陳情があったことが記憶にあります。この邦文という扱い、あのときどうしたか、確認だけ。","respondent":"米田区議会事務局長","answer":"当時の対応ですけれども、点字とともに訳文を提出いただいて、議会の審査に付したです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"確認","question":"提出されたもの、要するに点字でも提出することができると、当時そういう確認だと私は記憶しているのです。確認したいのは、この確認だと前回思うのですけれども、よろしいか尋ねました。","respondent":"米田区議会事務局長","answer":"規則の書きぶりの中の邦文というところでの邦文ということが何を指すかというところになるかと思います。解釈といたしましては、邦文のものをあわせてご提出いただいて、それで審査を行っていくというのが基本的なスタンスかと思います。","id":"exchange-008"},{"speaker":"中塚委員","kind":"確認","question":"邦文をつけていただくことはあってもいいと思うのですけれども、点字でも提出ができるということを基本だと、私はそう思っていますし、前回もそこはそう確認されていると思うのですが、点字でも提出することができるということでよろしいのか、改めて伺いたいと思います。","respondent":"米田区議会事務局長","answer":"過去の事例においては、やはり訳文はつけていただいているということではあるようなのですけれども、その辺のところ、規則に照らしてどうかということについては、改めて委員会の中でもご協議いただければと思います。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"確認","question":"その範囲は確認していただく必要はあると思うのですけれども、そこを我々としてどうするかということでしょうね。というところではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"青年会議所ということなので、皆さんお仕事をされているという意味で、夕方５時からになるということなのか。やはり通常の執務時間内のほうが望ましいといえば望ましいので、そこだけご説明をお願いします。","respondent":"渡辺議長","answer":"ただ、向こうで持ち帰って役員等で検討していただいても、やはりあまり早い時間だと参加率が非常に低くなってしまうと。先方の希望する時間と私たちの現実問題とちょうど間ぐらいで、この午後５時から午後６時を過ぎないという形で落ち着いたということになります。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"多様な議会の実態をしっかりと反映していくという意味でも、希望も聞きながら、議運メンバー以外の会派の方々や無所属の方々の参加もぜひ考えていただきたいなという要望です。","respondent":"渡辺議長","answer":"ただし、先方の人数ですね、やはり議会の都合もあるし、先方の希望もあるしというところで、私も今、幅広く議員の参加を求めたいとは思っています。","id":"exchange-012"}]},{"id":"topic-04","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当日、一般質問が２名、案件としましては、同意案件として、監査委員の選任同意、現在の監査委員が引き続き決定、可決。後期高齢者の医療費窓口負担２割化の中止を求める意見書提出についての陳情ということで、これに関しては不採択という結果になっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを伺いたいのと、その２点、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"提案","question":"例えば令和４年度以降、今回提案のあった形の保険料でいかないと、若い方への負担が大きくなるという大きな問題が出てきております。この辺から、案件に関しては賛成をしておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5398#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":18319,"voices":80}},{"id":"r03-20210219-3","meetingId":"r03-c-budget","date":"2021年2月19日","dateIso":"2021-02-19","committee":"予算特別委員会","time":"午後 ０時２６分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/309623?Template=document&Id=1124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1980,"voices":18}},{"id":"r03-20210219-10","meetingId":"r03-cm02","date":"2021年2月19日","dateIso":"2021-02-19","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5400#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":1807,"voices":13}},{"id":"r03-20210222-6","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"区民委員会","time":"午前１０時００分～午後 １時３４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"町会・自治会活動活性化促進調査の実施状況","agenda":"町会・自治会活動活性化促進調査の実施状況","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"私から何点か質問します。資料裏面の設問の回答の２段目のところですが、平成２６年度と令和２年度というのは、順位が変わらないという認識でよろしいのか尋ねました。","respondent":"川島地域活動課長","answer":"順位は変わらないです。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"それで、３つ目の、区から依頼される仕事の増加というのは、先ほどご説明いただいたとおり、大幅に５０点以上減少しておりまして、区の認識としても、大体パーセンテージみたいなところで、どのぐらいの割合で、区が依頼している仕事が減ったという感覚をお持ちか尋ねました。","respondent":"川島地域活動課長","answer":"お願いする部分の業務の精査をしていただくお願い等というのを繰り返ししてきてございまして、そういったことがかなり、まちの方に対しても効果があったと認識しています。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"３％の町会・自治会がＺｏｏｍ等を使ったオンライン会合を行われたと思うのですけれども、そういったものというのは何かおありでしょうか。教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"多分、こういった町会は、コロナ禍ではありますが、通常であればいろいろなイベントを活発に行っているようなところ、それから、役員の方でいろいろな方を引っ張っていくような方がいるというところが、特徴の一つにはなるのではないかと私どもは認識しております。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問・要望","question":"オンラインに精通している方もいれば、そもそもパソコンもそうですし、スマートフォンもなかなかお持ちでない方もいらっしゃいます。その辺も含めて、ぜひ地域のオンライン化を進めていただきたいというのを意見としまして、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"裏面の組織運営上の課題で、３項目ある中の真ん中、活動従事者の固定化というところで、そもそもこれはどういうことか、改めてお聞きします。","respondent":"川島地域活動課長","answer":"こちらは町会長、それから町会の活動をされている役員の方が、なかなか代わりがいないということで、同じ方がずっと務めているところですとか、そういった状況を指すものだと認識しています。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"最初の説明のときに課長から、悪化しているみたいな説明があったのですけれども、固定化してしまうと、区と行政としては悪化しているという判断になるのか尋ねました。","respondent":"川島地域活動課長","answer":"すみません、私の説明が分かりにくくて申し訳ございません。前回平成２６年の調査のときが、今回２５７点ということで、なかなか状況が改善されていないというアンケートの結果だったです。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"いつも問題になるのが、町会に参加する方が人数的においても出てくるわけですから、ここをどう捉えて、区と行政としてはどのようにしていくのか。区の直接ではないわけですから、その辺も含めて数字で出ているわけですから、その辺についてはいかがか尋ねました。","respondent":"川島地域活動課長","answer":"そちらをしっかり把握して、これから先の支援につなげていくというところが、一つ大きいのかなと考えています。区の支援策も考えますし、それから、何か運営の見本になるようなところの紹介もするようなところで準備をしています。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"ではどうやって調べるのかというのがあると思うのですが、ボランティアの意欲はあるけれども、そこはなぜだろうというところが出てくると思うのです。現実に動かれている方たちだけではなくて、今回の調査でそういった入っていない人たちの調査というのは、何か考えられているのか尋ねました。","respondent":"川島地域活動課長","answer":"今回、その中にも幾つか入らない理由というのが挙げられていたかと思いますので、その辺もしっかり踏まえながら対策を練っていければと考えています。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問・要望","question":"世論調査とか、これから実際には加入促進に具体的に動いていただくのは町会長の皆さんだと思いますので、役に立つ資料にしてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"大倉委員","kind":"意見","question":"１００％を目指すということが、１００％を目指すというところも大事かなと思ったので、それについてお答えをお願いしますとの意見を述べました。","respondent":"川島地域活動課長","answer":"回答数が、８５％の回答だったです。地域特性という形にもなるとは思うのですが、なかなかその辺で回答が難しかったと分析しています。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"活動がそもそもないのかどうかも含めて、今お話を伺っていて思ったので、アプローチしながらやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"は前提の部分なのですけれども、こちらのアンケート調査を実施するに当たっての予算が６６０万円ということで、こちらの６６０万円の予算の内訳であるとか、あとは、調査をした母体というのが民間の調査会社などの業務委託等であるのか、まずそこをお伺いします。","respondent":"川島地域活動課長","answer":"こちらの調査費の金額は、ほぼ調査委託先、ダイナックス都市環境研究所というところへの業務委託という形になっております。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"そちらの調査会社の選定理由、選定方法を説明するよう求めました。","respondent":"川島地域活動課長","answer":"簡易型プロポーザルという形で提案をいただきまして、その業者を選定したという経緯です。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"ほかに何社ほど、そちらはプロポーザルに参加なさいましたか尋ねました。","respondent":"川島地域活動課長","answer":"私の記憶ベースですが、業者の申込みが３社ほどございまして、実際にご提案いただいたのは２社だったということで、その２社の中から提案を聴きまして選定して、こちらに決定させていただいたという経緯です。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"はヒアリングの座組であるとか、連絡であるとか、どこまでをこの６６０万円の中でやっていらっしゃるのか尋ねました。","respondent":"川島地域活動課長","answer":"こちらの業務委託の中では、打合せ、資料作成と、それからアンケートの項目の作成・入力・集計・分析、それからヒアリング調査につきましても、内容の検討ですとか、お声がけの対象の選定とかまとめ、報告書のまとめも含めて、委託の内容に入っているものです。","id":"exchange-015"},{"speaker":"くにば委員","kind":"質問","question":"前回平成２６年度と同じ業者なのかどうかという部分と、この項目を付け加えてほしいだとか、そういった項目の選定にどれぐらいまで関わっていたのかなというのを伺いたいです。","respondent":"川島地域活動課長","answer":"こちらの業者につきましては、前回の平成２６年度のアンケートも実施したところになります。それから、アンケートの項目、それから内容につきましては、私ども地域活動課で中心になって考えたものを実施したものです。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"それはお送りしているかどうかという点と、そちらの共有に関して、どうなさっているのか伺いたいです。","respondent":"川島地域活動課長","answer":"今ご指摘いただきました、アンケートの結果をどのように活かしていくか、それから、どのように周知していくかというのは、非常に大事なところです。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"では、前回は公表でなくて、今おっしゃった形、冊子でお送りして情報共有はしていなかったのでしょうか。今回は準備しているということだったのですけれども、前回について伺いたいです。","respondent":"久保田地域振興部長","answer":"町会長にお集まりいただいて、協働のあり方研究会というものを立ち上げて、その中でいろいろご意見をいただいてきたものです。アンケート調査もやりましたし、そういった町会のあり方検討みたいなのもやって、町会・自治会には議事録等も含めて公表はしてきたです。","id":"exchange-018"},{"speaker":"くにば委員","kind":"質問","question":"実際に品川区の町会・自治会はどういう形の自治会なのだろうとか、この結果を公表したほうがいいかなというのが個人的な所感です。こちらの４４項目について、それぞれ自由記入欄というのは設けたのか尋ねました。","respondent":"川島地域活動課長","answer":"自由記入欄を設けさせていただきまして、様々なご意見を書き加えていただいております。こちらがなかなか、まだまとまらないところではあります。","id":"exchange-019"},{"speaker":"くにば委員","kind":"質問","question":"そちらの自由項目欄等に関しても、全てアンケートをいただいた後に電話でヒアリングしていらっしゃいますか尋ねました。","respondent":"川島地域活動課長","answer":"電話での聞き取りという形では、してございません。","id":"exchange-020"},{"speaker":"くにば委員","kind":"質問","question":"町会・自治会の方のこれに関しての今の課題はどうだろうと、ふと立ち返って考えたときに、それで記入なされたものです。よりよい結果が得られるとか、先方に対してもいい情報提供ができるかなと思うのですけれども、そこに関してご意見を伺いたいです。","respondent":"川島地域活動課長","answer":"かなり多岐にわたる項目をいただいております。これは今後の進め方にも関わってくるところですので、今こちらで判断するのはなかなか難しいということで、ご理解いただければと思います。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問","question":"ぜひともそれに関しては、今回のアンケート調査の６６０万円というのはさておきで、実施していったほうがいいかなとは思います。そちらが１点と、こちらは中間報告書というのは取りまとめられないのか尋ねました。","respondent":"川島地域活動課長","answer":"中間まとめにつきましては、公共用という形ではなくて、取りまとめて冊子で提出させるような形になっておりますので、そちらは作っていただくということになっております。","id":"exchange-022"},{"speaker":"くにば委員","kind":"質問","question":"そちらに関しては、区民委員会だけでも共有はできないのでしょうか。我々でも年に１回見るだけで、あったほうがよろしいかなと思うのですけれども、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"３月頃にはそろそろ、有用なものでございましたら、機を見て公表させていただければと考えています。補助制度の説明ですとか、お話を聴く機会はありますので、今まで以上に丁寧にやっていきたいと考えています。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"４番目のカテゴリーごとのグループヒアリングについて伺いたいのですけれども、かいつまんでどういった内容が具体的なヒアリング調査として出てきたのかという部分と、このカテゴリーをつくった目的を伺いたいのですけれども。","respondent":"川島地域活動課長","answer":"２０１町会・自治会のうちで１８、女性の会長も大変なところがあるだろうということが、まず一つ。もっといっぱい意見はあったのですが、主なところはそのようなところです。","id":"exchange-024"},{"speaker":"くにば委員","kind":"意見","question":"話が長いかどうかという部分は性差がどれぐらいあるのか分からないのですけれども、なぜ性差を設けて意見を聴くのかなという部分が、ちょっと気になった部分でしたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"だからオンライン会議の実施も３％ということですけれども、特筆してまとめていくべきではないかと思うのですが、そこはどうでしょうか。地域別にどういう特徴なのかとか、してほしいなと思うのですけれども、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"文献調査と、地域センター職員に対するヒアリング調査ということで、こちらは６月から９月ぐらいまでにかけて実施したものです。アンケートの回答率というところでも地域差は出ておりまして、荏原、地域特性の部分につきましても何らかの形でまとめて公表できればと考えています。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今まさにコロナ禍というところで、なかなか話を聞き取るというのもできない状況かもしれないのですけれども、そこは丁寧にやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"提案","question":"令和４年度の課題解決に向けた提案とか支援拡充の検討の中にしっかりと盛り込まれて、世論調査を確認すると、調査をされる対象というのは。令和４年度のところに向かっての具体的な、いろいろあると思うのですけれども、その辺りについて何かあれば説明を求めました。","respondent":"川島地域活動課長","answer":"区民の方には広く行った調査ですので、その辺も勘案しまして、区の支援策を決めていく。どのような形で支援していくのかということ、実際の区の支援策に反映できるように、しっかりやっていきたいと考えています。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"提案","question":"地域の人たちがどこに何を求めているかというと、それ以外の方というのは、なかなかそういう情報の入手手段がない。逆にやれることも出てきていると思うので、令和４年の提案だとか支援拡充のところを、本当にやっていただきたいとの意見を述べました。","respondent":"川島地域活動課長","answer":"なかなか具体的に、こういう形でこれをやればというのがないのがつらいところではありますが、まちの方に寄り添いまして、しっかり、どういった形で支援ができるのかということは考えていきたいと考えています。","id":"exchange-029"}]},{"id":"topic-02","title":"品川区町会自治会連合会ホームページ新設支援の状況","agenda":"品川区町会自治会連合会ホームページ新設支援の状況","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"２行目の後半の「独自の情報ツールを持たない町会・自治会が、町会・自治会の情報、イベント等を更新していくということなのでしょうか。どういう感じなのか教えていただけますか。","respondent":"川島地域活動課長","answer":"こちらは情報の提供依頼という形で出しまして、町会から紙媒体等で出していただいたものを、区がアップして更新していくというイメージでつくっていく予定です。","id":"exchange-030"},{"speaker":"小芝委員","kind":"質問","question":"そうすると、必ずしも町会・自治会のイベント全てが役所のほうに上がってくるわけでもないということもあるのですか。１００％の行事が区のほうに上がってくるわけではないということか尋ねました。","respondent":"川島地域活動課長","answer":"当然、漏れてしまうところは出てくると思います。ぜひこれをお伝えしたい、こちらに掲載したいという話で出していただいたものが中心で掲載されていくです。","id":"exchange-031"},{"speaker":"小芝委員","kind":"意見","question":"先ほどの促進調査のお話と関連してくると思うのですが、町会の中枢で動かれている方々のＩＣＴスキルも伸ばしていただくように、ぜひその辺の後方支援もお願いいたしまして、終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"松本委員","kind":"意見","question":"そこを尊重するべきだというお話もあったかと思うのですけれども、とはいえ、金銭的な負担がどの程度なのかというのは重要な点だと思うのです。","respondent":"川島地域活動課長","answer":"今回の町会の紹介ページの中で、確認をした上で情報を入れておりますので、そこまでいくのはなかなか難しいのかなというところではあります。会則も当然、住んでいる方に提示できるというのが一つではあると思いますので、その辺は課題として捉えさせていただければと思います。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問・要望","question":"各ページに載せる際に、町会長に、恐らくどういう情報を上げてくださいみたいなフォームをお送りすることになっているかと思うのです。難しいところは理解しますけれども、これは要望としますけれども、そういった工夫も引き続きご検討いただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"確認","question":"独自の情報ツールを持たない町会・自治会がということですが、持っているところがどれぐらいあって、こういう形なのか。情報ツールを持っている町会・自治会に、この連合会ホームページからリンクで飛んでいけるという形になっているのかというのを確認したいのですが。","respondent":"川島地域活動課長","answer":"こちらは区が明治大学と協定を結びまして支援しているものです。それから、ホームページを持っているところは、今回の品川区の町会自治会連合会のホームページと相互リンクを貼らせていただく予定です。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問","question":"こちらの連合会ホームページに関して、今後の運営体制、あとは来年度以降のサポートに関しての予算、その他にも予算が出るのであれば、そちらの２点を伺いたいです。","respondent":"川島地域活動課長","answer":"今回、３か月分のサポートということで先ほど説明させていただきましたが、こちらは３万６,３００円の１２か月分ということで、年間のサポートをお願いするような形になってあります。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"ということは、これが１月から３月分ということで、残りの４月から１２月分も既に契約済みで、令和３年度の予算には計上済みということでよろしいのか尋ねました。","respondent":"川島地域活動課長","answer":"新年度予算も予算要求済みという形になってあります。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"こちらがサポート費なのですけれども、これはコンテンツの更新料、更新作業が全て含まれるのでしょうか。それをサポートするという形なのか、コンテンツの更新も丸ごとやってくださるのか、いずれなのか説明を求めました。","respondent":"川島地域活動課長","answer":"こちらは丸ごとお願いするのではなくて、区でやるものを支援していただくという形の契約になってあります。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問","question":"データ上のトラブルであったりとかする場合に、あくまでサポートをするという形で、あとは全て区の所管の職員の方がなさるのでしょうか。町会・自治会の方はなさらないのか尋ねました。","respondent":"川島地域活動課長","answer":"目指すところではあるのですが、まずは区がやりまして、そちらを町会・自治会の情報発信の支援をしていくという形で立ち上げていくというものです。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"なので、そこに関しては能動的に働きかけていただきたいと思うのが１点です。どこからアクセスを増やすのか、どういうところからリンクを貼っていただくのか、考えていらっしゃる施策がありましたら説明を求めました。","respondent":"川島地域活動課長","answer":"今、準備をしておりますので、媒体を持っているところはこちらに網羅できるようにしていきたいと考えています。今まで町会活動をしていなかった方、町会活動がどんなものかも分からないという方が、見て分かるような形にしていきたいと思ってあります。","id":"exchange-040"},{"speaker":"くにば委員","kind":"質問","question":"そういった、区で町会・自治会に関してお知らせするためにＱＲコードを入れる、あとＵＲＬを入れる予定というのはいかがか尋ねました。","respondent":"川島地域活動課長","answer":"入れられるところは入れていく方針でやっておりますので、できるだけ最新の媒体が使える部分についてはそれを活かして、加入促進につなげていきたいと思ってあります。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問・要望","question":"要するにＱＲコードですから、様々な場所に事あるごとに、町会自治会連合会のホームページのＵＲＬを読み込めるＱＲコードを貼っていただきたいなと。ここに自治会の特徴や活動内容などを確認できますという部分、何かお考えがある部分があれば、聞かせてほしいと求めました。","respondent":"川島地域活動課長","answer":"読んでみようと思われるような形になるように、改善というか、努めていきたいと考えています。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問・要望","question":"先ほどご答弁のありました４４ですか、全体の１０分の１程度で、情報がこれ以上取りようがない。訴求できるかなと思うのですけれども、そういったページのつくりであるとかに関して、何かお話ありますか尋ねました。","respondent":"川島地域活動課長","answer":"確かに流れていってしまわないような形になるというのが重要なところだと思いますので、これからどのように運営していくかというところで、できるだけ反映できればと考えています。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問","question":"こちらは４月から本格運用開始ということで、去年いろいろとお話を伺った中で、期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"つる副委員長","kind":"質問","question":"まずは、ホームページをつくって知っていただくということが目的のところに書いてあるのですけれども、どうやって見るのですか。その辺のアプローチの仕方をどのように、マーケティング的な観点かもしれませんけれども、お持ちなのか、説明を求めました。","respondent":"川島地域活動課長","answer":"どんな活動をしているのかと知っていただけたらと思ったのですけれども、なかなか今のお話も聞きますと、難しいところもあるのかなです。色ですとか、視覚的な部分も含めて考えたつもりではあるのですけれども、その辺をしっかり踏まえて改善に努めていきたいと考えています。","id":"exchange-045"},{"speaker":"つる副委員長","kind":"意見","question":"５０代、６０代、７０代の人たちに広がっていくというのです。そういう工夫のところを、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"川島地域活動課長","answer":"すみません、１点だけ。町会・自治会の加入は今、電子申請でできるような形になってありますので、ご案内します。","id":"exchange-046"}]},{"id":"topic-03","title":"令和２年国勢調査","agenda":"令和２年国勢調査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"１日幾らとか、そういうので決めるのでしょうか、教えてください。２３％は回答していないということになるならば、これが正確な国勢調査になるのでしょうか、なると行政側は思うのか尋ねました。","respondent":"川島地域活動課長","answer":"実日数は、任命期間が３か月と長いのですけれども、実働の期間というのはもう少しこちらよりも短くなると考えています。調査の回答というところの７割で、インターネットと郵便での回答が７割程度という形になりますので、１００％に近づくように。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問・要望","question":"平均でどのぐらいあるのですかということと、必ずこの委員会でお知らせしていただきたいと思うのですけれども、それはいかがですかということです。その辺についてもお伺いします。","respondent":"川島地域活動課長","answer":"それが６月ということですので、そちらで回答率等、数字が出たところで報告をする予定です。それから、罰則の話ですが……。","id":"exchange-048"},{"speaker":"藤原委員","kind":"質問","question":"こういう質問を毎回してしまうのですけれども、国のことですから、事務的なことは区がこういう形でやったとしても。でも、その考え方についてどう思われるか、ぜひ担当の課長としてお伺いしたいのです。","respondent":"川島地域活動課長","answer":"こちらの国勢調査も統計法に基づいて実施しているものでございまして、統計法にこういう記載があるということで、案内の中にも記載していますが、我々は、罰則があるから書きなさいということではなくて、お願いをして書いていただくというスタンスで調査を進めてまいりました。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今までは対面して説明などもしていたりしたのかもしれないですけれども、ポストインにしたことで回答率が下がっているとか、今の時点でそういう情報が分かったら教えていただきたいのですけれども。","respondent":"川島地域活動課長","answer":"非対面式でもいいですという話になりまして、当然、ネットでの回答率というのは伸びているという形になっております。正式な分母というのでしょうか、前回と比べてネットの回答が伸びているという形で、回答もしやすいというところもあったのかと分析しています。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、対面してお伝えするというのも大事だと思うのですけれども、ポストインでもそこまで変わりがないということであると、今後、説明は大事だと思うのですけれども、調査員の皆さんの負担を減らすというところでは、そういうのもありかなとなっていく状況なのか尋ねました。","respondent":"川島地域活動課長","answer":"一回こういった簡略化をした後、また厳しくするというのもなかなか難しいと思うので、この流れは変わらないような気がしています。","id":"exchange-051"},{"speaker":"くにば委員","kind":"意見","question":"こちらの６.２％高いというのは、そちらに関しての分析と見解を、まずお教えくださいとの意見を述べました。","respondent":"川島地域活動課長","answer":"２３区でいいますと４位という形になって、回答するほうにとっても簡単に済むという、簡略化されたというところの効果があったのではないかと見ているところです。","id":"exchange-052"},{"speaker":"くにば委員","kind":"質問","question":"なぜそうやって東京都で４位になるぐらい施策が成功したのか、ここがよかったのではないか、東京都で４位というのは物すごいことですから。何となく結果４位だったというのではなく、何がよかったのかという分析が大事だと思うので、そこに関してお考えを説明するよう求めました。","respondent":"川島地域活動課長","answer":"これは１回５分ぐらいの番組で、繰り返し流されるものですけれども、職員が出演して国勢調査のお願いをしたと。それから、こういった今まで使っていない媒体を使ったことで、効果が表れたのではないかと考えています。","id":"exchange-053"},{"speaker":"くにば委員","kind":"質問・要望","question":"例えば、コロナ禍で在宅率が上昇したではないですか。２回、３回ぐらい訪問しないと、そういった報告等での分析が何かあれば伺いたいです。","respondent":"川島地域活動課長","answer":"２月下旬の東京都への第１次の要計表というものの提出をもって一段落してくるというところですので、少し詰めて考えていきたいと考えています。これからというところです。","id":"exchange-054"},{"speaker":"くにば委員","kind":"質問","question":"こちらのコールセンターへのクレームについて伺いたいのですが、クレーム内容に変化があったのかどうか。例えば、コロナ禍なので、訪問しないでほしいという方々が一定数いらっしゃったと思います。","respondent":"川島地域活動課長","answer":"前回が同じような形で５,３７７件ということだったので、やはり数は増えているです。あまり強硬なクレームがあったという報告は受けておりませんので、淡々と分からない部分と、それから不明な点のお問合せがあったと認識しています。","id":"exchange-055"}]},{"id":"topic-04","title":"第１４号議案 品川区地域センターの設置に関する条例の一部を改正する条例、および(2)第１５号議案 品川区立区民集会所条例の一部を改正する条例","agenda":"第１４号議案 品川区地域センターの設置に関する条例の一部を改正する条例、および(2)第１５号議案 品川区立区民集会所条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど定員数が全体ので説明されたのですけれども、今日の資料では、表の一番右に広さが１部屋ずつ書いてあるので、比較したいと思うので、現区民集会所の広さ、定員数も教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"現在の広さ、区民集会所が３室合計で２７６.３m2、新しいところが２７０.７７m2という予定になっております。現行の区民集会所の第一集会室が１４３.７５m2、第二集会室が５０.０５m2、第三集会室が８２.５m2です。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"この周辺地域の町会長にも話を伺わせていただいたのですけれども、ぜひ使いやすい設備にしてほしいという声を寄せていただきました。その辺はどう考えているか尋ねました。","respondent":"川島地域活動課長","answer":"地元への説明ということですが、それから会計の役員会に出席しまして、概略を説明しています。２月の町会長会議で、荏原第二地区も含めて説明にお伺いする予定だったのですが、また説明のほうはお伺いできればと考えています。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、駐輪場は地下にはならないですか。なので、新しく移転するところの駐輪場というのは、平設置なのか、地下なのか、そこを伺いたい。","respondent":"川島地域活動課長","answer":"駐輪場が約２０台分という形で、有料と聞いているのですけれども、地下か地上かという形ですが、分からないのですけれども、駐輪場は２０台分という形で配置されて、準備されているです。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地下かどうかは分からないのですか。現集会所は東急の２階でしたか、どういう経緯で現第一区民集会所は区分所有という形になったのか、説明を求めました。","respondent":"川島地域活動課長","answer":"今のところの２階部分を、３億円余ということで聞いておりますが、現在に至ると聞いてあります。武蔵小山商店街振興組合と武蔵小山マンション管理組合、品川区による区分所有になっているです。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"この場所も武蔵小山のまちづくり方針というのですか、４棟目の開発ビルが建つ予定になっているので、その跡地活用というのはどうなっているのか伺いたいと思います。","respondent":"川島地域活動課長","answer":"男女共同参画センターの仮移転の場所と、それから、図書の取次サービスの移転先になるという予定と聞いてあります。両方とも暫定利用という形です。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に地域の皆さんが求めているもの、これ以上の超高層は要らないという声が６割を超えて届いているのです。それが毎年なわけですから、新しくなって便利になるけれども、この辺の考えはいかがか尋ねました。","respondent":"川島地域活動課長","answer":"当然、新しくて利便性のいいところに移ってくると、経費というのがかかる部分というのは出てくると思いますので、その辺はしっかり説明していきたいと考えております。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"利用料の部分に、そうしたかかる部分が反映されなくて、本当によかったとは思っているのですけれども、きれいになって便利になるにしても、まだまだ不足している区民の集会所だったり集う場というのを、なくさないようなまちづくりというのをすべきだと、改めて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"駐輪場の話が出たのでお伺いしたいのですけれども、地下かどうかというのは分からないというところで、無料ではないかと思うのです。それは、無料だったものが有料になるということでいいのか尋ねました。","respondent":"川島地域活動課長","answer":"多分、こちらは区役所の駐車場とかと同じで、地域センターに用のある方については１時間以内は無料になるとか、そういった扱いになると聞いているのですけれども、詳細の扱いについては、まだ詳しいところは分かっておりません。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問・要望","question":"もう１点、所管は違うのですけれども、今、武蔵小山で問題になっているのは、シェアサイクルの駐輪場が足りないというところがあります。６分ぐらい離れたところに１か所あって、これは民間の部分ですから難しいとは思うのですけれども、そこはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうするときに１時間とかだと、現状使えているような無料になるサービスというか、利用の仕方というのをぜひ検討してほしいと求めました。集会室もそういう意味では、そっちも使えないということなのか、そこの確認だけ。","respondent":"川島地域活動課長","answer":"こちらは区民集会所も併せて新しいところに移転するという形になりますので、そちらの跡地の使い方が変わってくるという形になります。","id":"exchange-065"},{"speaker":"大倉委員","kind":"意見","question":"では、全体も移って、そちらで基本的に使って、集会所というのはもうなくなるという理解で、分かりました。先ほどお伝えした駐輪場等の結果をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それと、駐車場代が１００万円とありましたが、これは地域センター所有の車両を置く駐車代という理解ですか。あの建物だけで２０台なのですか、車で来られる方の駐車場というのはあるのでしょうか、説明を求めました。","respondent":"川島地域活動課長","answer":"駐車場代という形で説明した部分につきましては、荏原第一地域センターの車の駐車場代という形になります。それから、駐輪場はもっと台数があるはずですけれども、地域センターの部分が２０台と割り当てられているという考え方です。","id":"exchange-067"},{"speaker":"つる副委員長","kind":"質問","question":"すみません、一旦ここで切りますが、その辺はどうか尋ねました。","respondent":"川島地域活動課長","answer":"一時的に物の搬入ですとか、それから、一時的に車でないと来られない方もいるかもというところもあります。少しその辺は、どこまで交渉できるか分からないのですけれども、駐車場の余地のところを確認させていただければと思います。","id":"exchange-068"},{"speaker":"つる副委員長","kind":"質問・要望","question":"他課としっかりと連携・協議等していただきたいこととしては、ちょうど角の位置というのでしょうか、スピードを結構出してくるところでもあるのです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、区民の集会所を残してほしいと。そこに応えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759222?Template=document&Id=2890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":44788,"voices":183}},{"id":"r03-20210222-7","meetingId":"r03-cm02","date":"2021年2月22日","dateIso":"2021-02-22","committee":"厚生委員会","time":"午前１０時００分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(8)から行います。 それでは、(8)第２３号議案 品川区手数料条例の一部を改正する条例","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(8)から行います。 それでは、(8)第２３号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"１個１個非常にややこしかったのですけれども、デジタル化という背景があったということなのですけれども、単にそれだけなのでしょうか。戸籍のほうはその質問です。","respondent":"木村戸籍住民課長","answer":"５年間という形で保存されておりまして、例えば所有者不明の土地を探索したりなど、その５年を１５０年保存という形に変えたのです。実際にそのことで、今までは特に明記されていなかったのですが、そのことで改めてこの除票についても明記をしようということでされたものです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"２,０００m2以上だったものが３００m2以上と、やはりその趣旨をお伺いしたいということと、やはり実際にかなり増えるのでしょうか。ほかの２３区でも同じ数字、同じ額が定められるのか、その辺のこともお伺いしたいと思います。","respondent":"長尾建築課長","answer":"どのくらい増える、対象が拡大することでどのくらい建物として増える見込みかというところです。東京都の手数料の設定も、同じ内容でこれまでも来ておりまして、今回の改正も同じ形で足並みをそろえて改正するという内容になっております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それをお伺いしたいということと、見直しがあるということによって、将来の値上げというものが見込まれているのかということが第２点です。値上げといえば値上げですし、ここのところがどうしてこのようになったのかということがいま一つよく分からないのですけれども、よろしいか尋ねました。","respondent":"鈴木生活衛生課長","answer":"今回値上げがないかですけれども、先ほど経過措置でご説明したように、基本的に値上げはございません。保健所としての証明の１種類ということで、通常の諸証明の３００円を当てていたもので、そういう経過で今回設定をしたものです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"国が設定して、この８７０円でやれというように言ってきたということで理解すればよろしいのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"事務としては都道府県、もしくは各区の事務になりますので、基本的には自治体ごとで定めるものになります。ただ２３区のほかの区を見ましても、国と同じ業務内容ということで証明書の額を合わせたというのが、大半の区での基本的な考え方です。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"端的に伺っていきたいと思います。内容的にはもうこれ、法の改正なので賛成なのですけれども、そこについて説明を求めました。","respondent":"鈴木生活衛生課長","answer":"これに伴う、それから保健所での対応の違いですけれども、ＨＡＣＣＰに沿ったものに適用できるようなアドバイスや支援をするということになります。先ほどご説明したように、金額を変えておりませんが、業務については大分変わってくるところがあるというふうに考えております。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"確認の業務が増えるという認識でいいのか、主査ですか、確認したいと求めました。","respondent":"鈴木生活衛生課長","answer":"再度ご質問の内容に関しましては、基本的に業務量として大きく変化はないかと思いますが、そのご相談の内容の適用業種によっては、これまでの許可、届出よりも必要書類が増えたり、そのご相談内容が増えたりする可能性はあるというふうに考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そして手数料を見直すというのはいつなのか、３年後なのか、そこのスケジュールを教えていただきたいということが１点です。２３区統一だというようなことだったのですけれども、２３区統一なのか、２３区の状況も説明を求めました。","respondent":"鈴木生活衛生課長","answer":"基本的には先ほどご説明したように、それから都や各区の動向などを見ながらということなので、何年後などというように定めているわけではありません。今回も２３区、ほぼどこも据え置きをベースに考えておりますので、大体似た金額の区がほとんどです。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"食品衛生のところで伺いたいのですが、今、これ今まで対象ではなかったところが対象に加わるということがあり得るのかどうなのか。これ別に、どうせ税金を払うときに控除されるから、会社で払うのはいいとして、どのような説明を区内事業者に伝えていくのですか、これ。","respondent":"鈴木生活衛生課長","answer":"は変更についての案内ですが、先ほど申し上げましたように、全ての業種の方がこの１年で更新にかかるわけではございません。そのときにも制度の変更についてはお知らせしますので、詳しく説明をするということで考えております。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう要望ですけれども、品川区は商店街が強いではないですか。すみません、長時間。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"第３０号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"第３０号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"要するにせめて国保運協と同じ資料を出していただきたいのですけれども、出せない理由でもあるのでしょうか。どうして出されなかったのか尋ねました。","respondent":"池田国保医療年金課長","answer":"昨年と比べまして、今年はその意見の回答と同じようなことで、内容自体は充実させていただいたところです。要するにこちらの条例の改正にとって大変重要なものかというと、ほとんどないですので、その辺も特段意識はしていないところです。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"まだまだ私分かっていないから、とんちんかんな質問をするかもしれません、今日も。国保運協で出された資料、例えば私が勉強させてもらったのはこれですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"分厚い資料を出せと言っているわけでもないのですから。これがなぜ加わったのか、もう１回きちんとご説明いただきたいのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"この４３万円の人だけでなく、１０万円掛ける被保険者数引く１を加えることで同じ金額、やっているところです。以上でよろしいでしょうか。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問","question":"この式でなぜ現行と同じになるのですか。現行と同じになるのなら、今の式のままでいいのではないか尋ねました。","respondent":"池田国保医療年金課長","answer":"基礎控除相当額の基礎額を４３万円に引き上げるということと、より受けやすくなるということで法律がなっているということで改正するものですので。よろしいでしょうか。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"次の質問。〔「まとめて質問して」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"おくの委員","kind":"質問・要望","question":"この式で求められる、２割減額というものが出てくるのですが、加入世帯の。５割減額、２割減額の方は、加入世帯の何％になるのか尋ねました。","respondent":"池田国保医療年金課長","answer":"この計算で出した場合ですけれども、これはまだ私どもで計算のほうをしておりませんので、これでやった場合何人というのはお答えできないところです。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"では個々の数があるのなら、個々の世帯数を説明するよう求めました。","respondent":"池田国保医療年金課長","answer":"５割減額世帯が５,６０３世帯、２割減額世帯が４,６６３世帯、合計で２万５,７３５世帯という形になります。なお、加入世帯につきましては５万３,１９１世帯です。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから昨年度の賦課総額も教えていただきたい。それから、その賦課総額が均等割では幾ら、所得割では幾らということも教えていただきたいのですけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"今日おつけしております資料の５ページ目、それと後期高齢者支援分、介護納付金分ということになってあります。細かな均等割など……。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"所得割対均等割というのは６１対３９で変わっていないのですけれども、これ均等割が８００円下がって、所得割が上がっているのはなぜでしょうか。これは一体なぜ上がったのかというところ、今年上がったのはどう考えているのかということをお伺いしたいと思います。","respondent":"池田国保医療年金課長","answer":"それと品川区の来年度見込みの所得を見ましたところで、２３区で収入のある区ですと、５７対４３などといった形になってくるところです。２３区でも、他区でも２％以上の割合になっているところが多く出るというようなことを予想しているところではあります。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"なので、運協でこれだけの資料を作っているわけですから、だって運協で１５ページ作っているのです。いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"資料のほうは、来年度またさらに精査して、きれいな形にします。余計なものはつけませんけれども、きれいな形でより見やすいものをおつけしたいと思います。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の賦課総額、賦課総額というのは保険料で賄う総額ですから、この額はぜひ出していただきたいと思うのです。４％をそのまま、令和２年度の最終的な法定外繰入というのは幾らだったのか、その法定外繰入れについても教えてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"令和２年度につきましては、基本的に補正をかけて、予定では８億９,５００万円というような形を今見込んでいるところです。令和３年度の、当初予算としては、今その他の一般会計繰入金のほうについておよそ１０億円ということを見込んでいる、ご審議いただくところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"賦課総額というのは保険料で賄う、この賦課総額はぜひ来年度の資料には出していただきたいと要望させてほしいと求めました。７９億円は出すというように言ったのですから、そこのところを求めるべきではないかと思うのですけれども、その点についても伺います。","respondent":"池田国保医療年金課長","answer":"国のほうで激変緩和措置額について１９億６,０００万円を出すというような形で、今年につきましては特に要請というところまではいっておりません。確定係数……。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やはり国保料を皆で引き下げるためにそのようなことを要望していこうというようなことにならないものなのかどうか、いかがでしょうか。課長会などでもずっと求めてきたと思うのですけれども、もっと広い１８歳まで、ぜひ無料化をしてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"こちらのほうはこれまでも子どもの均等割について軽減するようにということを２３区の区長会に要望させていただいているところですし、来年度以降についても引き続き、特別区として国のほうには要望するということになっているところです。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に区長会でもずっと求めていると。私たちもずっと子どもの均等割の無料化ということを求めてきましたけれども、全額無料だったり、区としてもぜひ強力に求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"おくの委員","kind":"意見","question":"反対です。コロナ禍でこれだけ大変なときに、いろいろ法定外繰入れなどを入れて引き下げるべきところを、負担が増えるような値上げということでは反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-03","title":"第１６号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","agenda":"第１６号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"返さなければいけない、普通の人は当然借りたものだから返すということなのでしょうけれども、返せない事情というものがあると思うのです。そのときにどのようにして返しますかという、割と柔軟に対応できているのか、その辺のところを少しお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"なお、この１７人のうち２名の方につきまして、一部で延滞金が発生しているという状況です。この延滞金が発生している２名につきましては、基本的に、その方たちの返済能力に応じた返済計画をそれぞれ個別に立てているです。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"そのように話合いをして返済計画を立てるというような状態になってしまうような方というのは、継続的に出てくるものなのでしょうか。従来、これまでに。","respondent":"宮尾高齢者福祉課長","answer":"延滞金が発生する状況にまでなってしまうケースというのは、本当に確率としては非常に低いものだというふうに捉えております。そのような選択肢もありますので、そのような方はそもそもこの制度で借りないで、ご自身でお金を出しているという状況もあります。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"今現在は無理のない形で返済は進んでいる状態と見ていいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"杓子定規にこのような返し方をしてくださいということは設定していません。繰り返しになりますが、その方ご自身の返済能力に応じて、返済計画を話合いの上で決めさせていただいているところです。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"確認","question":"本当にいい制度だなと思うのですけれども、一応確認です。今回は「３％」とは書かずに「法定利率」という形で書いてあるということで、特にもう条例の変更も要らない、このようなことでよろしいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"委員のご指摘のとおりです。その文言によりまして、これからは利率が変更になったごとに条例改正ということはなくなるというような手続きに今後なっていきます。","id":"exchange-028"}]},{"id":"topic-04","title":"これより、(2)第１７号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","agenda":"これより、(2)第１７号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ショートステイの方を減らして特養ホームの方を増やすということですけれども、そのご趣旨を教えてほしいと求めました。ショートステイを減らすことで不都合はないのか、特養ホームを増やすということで、何かその辺のご趣旨をお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"そのために、ショートステイの枠を一部特養ホームのほうに振替えるという対応を取らせていただきたいというふうに考えております。これまで使っていた方が使えなくなる、そういったことのないように、この８名分の振替という人数を出させていただいたところです。","id":"exchange-029"},{"speaker":"おくの委員","kind":"質問・要望","question":"区民の要望という点から、ショートステイの利用者、利用要望が減っていて、特養ホームの要望が増えているというように理解してよろしいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"特にそのようなご要望を受けてということではなく、ちょっと繰り返しになりますが、あくまでも特養ホームの受入れを増やす、そのためにショートステイの枠を一部有効活用すると、このような趣旨です。","id":"exchange-030"}]},{"id":"topic-05","title":"第１８号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第１８号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"１０万円ずれているのが３段階だけ、８・９・１０段階だけで７段階から下の人は１０万円ずれていないというところはなぜなのか、ご説明ください。それをお願いいたしますとの意見を述べました。","respondent":"宮尾高齢者福祉課長","answer":"なぜこの３段階なのかというお尋ねですけれども、その増税分を低所得の方の保険料引下げに既にそういった措置が取られております。こういったことも併せ考えますと、こういった措置が取られたというようにも推測されます。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"なので、全ての人に対して１０万円を、ここでは規定しないで引くという計算の仕方をするということなのでしょうか。それで、それはずっとこの先そのような形で続く、少なくとも第８期は続くと考えればいいのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"１点目のご質問につきましては、委員のお見込みのとおりです。なお、現時点では特に時限的なということではなく、少なくとも第８期に関してはこのままの体制でいくというふうに見込んでいるところです。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"合計所得金額ということなので、給与所得控除や公的年金控除を引いたところの額が合計所得金額ということになりますよね。そうすると、基礎控除の部分というのは、この介護保険料を計算するに当たり基礎控除が１０万円プラスになるということは関係してくるのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"趣旨としては、とにかく今回の税制改正で、この改正を行わないと所得が１０万円高く見積もられてしまう方が出てきてしまう。今回さらに１０万円を上げて、この税制改正で所得が１０万円アップするという事態を避けるために、このような趣旨です。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そこのところをここに反映しないで、保険料がそのことによって高くならないようにという配慮がされるということで理解すればいいということですよね。私が一般質問でお伺いしたときに、２０２０年度というのは、それによって基金の影響はどのような状況になっているのかということを説明するよう求めました。","respondent":"宮尾高齢者福祉課長","answer":"様々国のほうで講じておりますし、区のほうでもそれに合わせた補正予算等を組んで対応させていただいているところです。こういったことが影響していると思われますので、今のところ特に大きな変化はないという状況です。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"合計所得２,０００万円以上で２.８倍というのが一番最高になっていますけれども、２３区の中で１８区が１５段階から１７段階にしているのです。５倍、１４段階というのはやはり２３区の中でも一番少ない段階だし、２.８倍というのも一番少ない倍数なのです。","respondent":"宮尾高齢者福祉課長","answer":"ただ、これは一概に、１つの参考にはいたしますけれども、ではそれに品川区が右に倣えでいいのかと。２３区あればそれぞれの状況がありますので、すなわちすぐに品川区がこれよりさらに多段階化に踏み切るという考えは、現在のところはございません。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区長会、全国市町村長会ですか、５％の調整金というのをそれにプラスするようにという要望書をかつて出していたと思うのです。私はぜひそのようなものを改めて求めていただきたいと思うのですけれども、その辺のところの動きについてもお聞かせほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"直近ですと２３区の課長会では、特にそのような話題というのは、テーマというものは出ていなかったというように記憶をしております。ただ、全国の知事会などで、一部要求が出ているということは聞いたことがあります。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"共産党は本来であれば５割を国が持つというような方向で提案しているところですけれども、まずそこのところでは一致できるのではないかと思うのです。","respondent":"宮尾高齢者福祉課長","answer":"介護保険全体というか、制度の根幹に関わる部分でもありますので、その点に関しては引き続き国の動向等をしっかり注視して、健全な制度運営に努めてまいりたいと考えています。","id":"exchange-037"},{"speaker":"おくの委員","kind":"質問・要望","question":"具体的なイメージとしてどのようなものなのかも、ご一緒に教えてくださればありがたいと思います。栄養管理を計画的に行うことを求めるとなっていますけれども、これが一体どのようなことなのかも一緒に教えていただければありがたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"第１９号議案の指定地域密着型サービスと申しますのは、あるいは認知症対応型の通所介護、こういったものがこちらの条例の対象になってきます。例えばこのサービスのうち要支援者の方にも対象を広げているものが、こちらの第２０号議案の条例の対象となるサービスとなってきます。","id":"exchange-038"},{"speaker":"おくの委員","kind":"質問","question":"もう少し具体的に言うと、どのようなことなのかなと思ったのですけれども、それを具体的に教えていただければということです。要するに３０人以上のものですけれども、それはどのレベルの法律なり、条例で規律されているのかということを説明するよう求めました。","respondent":"宮尾高齢者福祉課長","answer":"それぞれ各施設のほうで、または管理栄養士等の下で、しっかりと施設のほうでプランを立てていくという内容です。これは指定権限が都道府県のほうになってまいりますので、都道府県で同様の改正を行っていくものと推察されます。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"確認","question":"何というのですか、これはもう報告で確認できると思うのですが、これ。それはいつどの時点で確認をするのか、今決まったことを誰がどこで確認するのかというところを、これについて説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"実行性のあるものになる、こういったものをしっかりと見ていくというのは、一義的には保険者である品川区になろうかと思われます。押しつけではなくて１つの参考にしてくださいというような情報が出てくると思われますので、こういったところから始めていきたいと考えています。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"流れとするとそのようなことなのかなと思います。いずれにしても、つくったはいいけれども魂入れずのようなものだとあれだと思いますから、そこはしっかり継続して見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"虐待の問題から、そのようなＢＣＰ計画から、このようなものは今の段階ではまだどこもできていないということなのでしょうか。その点が１点と、区がどのような形で関わっていくのか、現状と区がこれからどう関わっていくのかというあたりを改めてお願いします。","respondent":"宮尾高齢者福祉課長","answer":"やはりこれから、国のほうからも、いろいろな方針に基づいた具体的な内容を盛り込んだ通知等がどんどん出てくると思われます。そういったところで情報提供をしっかりして、意見交換をして情報共有を図る、こういったことも当然に保険者としてやっていくべきだと考えています。","id":"exchange-042"},{"speaker":"おくの委員","kind":"質問","question":"先ほどと同じような質問ですけれども、この指定介護予防支援事業者というのは、いわゆる要支援の方のケアプランを作る事業者の方のことでしょうか。そうであれば、区内に何か所あるか説明するよう求めました。","respondent":"宮尾高齢者福祉課長","answer":"第２１号議案のほうですね。すなわち地域包括支援センターとなりますので、品川区の場合は高齢者福祉課および在宅介護支援センターということになります。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"３年前ですか、これと似たようなものが議案にかかったことがありましたけれども、そのときにも私申し上げたのですが。その点についてはいかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"あるいは地区の在宅介護支援センターの統括ということ、あるいは在宅介護支援センターのサポート、役割というようになりますので。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"在支は指定介護予防支援事業者にはならないということなのですか。なぜなのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"保健師の資格を持った職員は本課、高齢者福祉課のほうに複数名在籍しております。必要に応じて、その辺は有機的に連携を取りながら、日々介護保険制度の健全運営に向けて努力をしています。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、在支は指定介護予防支援事業者にはならないということなのですか。登録されているのは高齢者福祉課で、指定介護予防支援事業者としてはなっていない、地域包括支援センターにもなっていないということなのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"先ほどの繰り返しになりますが、品川区は高齢者福祉課と２０の在宅介護支援センターとして、それで１つの、１か所の指定、地域包括の事業者として１か所の指定を受けているものです。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"地域包括はそれで分かりました。高齢者福祉課が登録されていて、その１か所で、そのサブセンターというような形になっているのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"繰り返しになりますが、高齢者福祉課と在宅介護支援センター２０か所、これで１か所としての指定を受けているです。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１か所で品川区の全員分の介護予防のケアプランを組むという、これはこのままずっと問題ないということでいくのでしょうか。改めて伺います。","respondent":"宮尾高齢者福祉課長","answer":"繰り返しになりますが、品川区は高齢者福祉課のほうに保健師の職員を配置しています。２０の在宅介護支援センターがサブセンターとして有機的に連携を取りながら、日々介護予防支援を行っているところです。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"唯一１か所だけで保健師も配置しないままやっている、これは本当に厚生労働省の方針からも、私は反していると思うのです。そのような点では、改めて保健師、社会福祉士、この配置をしっかりと、在支のところに配置していただきたいと、改めて申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-06","title":"第２９号議案 指定管理者の指定","agenda":"第２９号議案 指定管理者の指定","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"そのような一体的な建物の管理が必要だったという理由での公募だったということですよねという確認を行いたいということが１つです。利用者や当事者の皆さん、家族の皆さんから要望書が出されたり、ご利用なさっている皆さんからいろいろ切実な内容のご要望をいただきました。","respondent":"築山障害者施策推進担当課長","answer":"１つ目のご質問ですが、建物管理を含む総合的・一体的な管理運営を行っていただくために実施したということが理由となっております。公正公平な実施というところで、選定委員会でも外部の委員を複数名入れておりまして、公正公平な審査のほうを実施しています。","id":"exchange-050"},{"speaker":"おくの委員","kind":"質問・要望","question":"それから利用者の方のお声ですけれども、どこに反映されたのかと私は伺っているので、反映したかという私の質問に答えたことにはならないと思います。どこに反映されているのかと私はお伺いしたのであって、その点お答えほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"１点目ですけれども、客観的に審査、選定を行ったものです。資料１で選考基準の方をつけしていますが、２点目の質問の回答にもなりますけれども、満足度が高いということもある中での審査をしています。","id":"exchange-051"},{"speaker":"おくの委員","kind":"質問・要望","question":"そう思いますけれども、いかがでしょうか。お伺いいたします。","respondent":"築山障害者施策推進担当課長","answer":"１の項目全てサービスの向上を図るといったようなところですとか、選定の過程におきまして、そういった意味で反映はされているというものです。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"もし併せて伺えれば教えてほしいのですけれども、障害をお持ちの方々の意見というのを広く聞いて反映していただかなければならないと僕は思うのです。ですから僕は、利用者といいながら、改めてそこのところだけきちんと説明いただけけますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"おくの委員","kind":"質問・要望","question":"全体のではなくて、今利用されている方から具体的な要望が出ているわけです。だから、それでは説明になっていないのではないですかと私は思うのですけれども、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"事業者の選定に当たりましては、また同じ回答になりますけれども、別紙１の選考基準を定めまして、それぞれの委員に審査、選定をしていただきまして、総合的に判断したものです。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"提案","question":"というよりは、今利用されている方のお声、また、現指定管理者にもご意見を伺いました。この点について、最も優れた提案をされたのが福栄会だったということは理解しましたとの意見を述べました。","respondent":"築山障害者施策推進担当課長","answer":"やはり総合支援施設は区立の拠点施設であるということで、区立の指定管理者には区の意向に沿った運営をしていただきたいということがやはりあります。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"確認","question":"第４回定例会の一般質問の通告の直前でしたから、これは係争中ですから、区として評価はできないと思っています。ですので事実として伺いたいのですが、こうした報道が指定管理者としての業務に影響が出ないのかどうかということの確認をされたのかどうかと。","respondent":"築山障害者施策推進担当課長","answer":"運営事業者のほうの回答といたしまして、選定の中で、総合的・一体的に実施をするのは難しいのではないかというようなご指摘もございました。区のほうでもハラスメントに対しての基本方針を掲げていますとおり、ハラスメントにつきましては決して容認するものではないと。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここからは先ほど伺った皆さんのご意見から、要望も含めて伺いたいと思うのですけれども、実施しているということが書いてあります。向上させる努力と、これは結果というものが求められてくると思うのですけれども、そこについてのお考えも伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"福栄会のほうも、現事業者が非常に頑張って取組まれていて、利用者満足度が高いということも十分に認識しておりました。今の質が落ちないよう、質を担保し、ご利用者に引き続き安心して施設を使っていただけるよう取組んでまいりたいと考えております。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回の陳情でも代表的な団体、５団体ですか、その中でも多くの団体が要望を上げてこられている。それはどのようなものがいいのか、やはり今後どうしても必要になってくるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"利用者や団体の意見を聴きながら施策を進めていく、サービスを提供していくということはとても大事なことだと認識しております。区といたしましても、これまで障害福祉計画の策定等では団体ヒアリングやアンケート等を取りながら実施をしてきたのですけれども、今後ご利用者。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回この指定管理者が、現指定管理者が決まった２０１４年、２０１５年ですか、そのときに私もすごい大きな期待とともに、やはり不安もありました。ですから、本当に「この子らを世の光に」と、この理念をぜひ今後品川区の障害者福祉に際して言っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"改めて伺いたいのは、公募の趣旨と施設の設置目的から指定管理者として最も優れている団体を選定したというような答弁だったのです。地域生活支援拠点では福栄会がプラスの提案をしていたとか、それで最終的には福栄会が高い点数になって選ばれたという形になっているわけですとの意見を述べました。","respondent":"築山障害者施策推進担当課長","answer":"審査会ですけれども、当初は２名外部の選定委員が入る予定でございました。もう一人は医師を予定していたのですけれども、新型コロナウイルス感染症の対応のため、欠席という形になりました。","id":"exchange-060"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"外部委員の名前を公表できないということはないと思いますので、ぜひそれはお答えいただきたいと思うのですけれども、いかがでしょうか。その点についてはいかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"外部委員のお名前につきましてですが、こちらは先ほども言いましたけれども、特に現時点でお名前を公表するということは考えておりません。あらかじめ条例に基づく選定基準を踏まえた選考基準を設けまして、客観的、公正公平に選定をしたものとなっております。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"指定管理者を決定するのはこの議会で決定するわけですから、品川区が選んだものを議会で決定するのに、どう判断したらいいか分からない。そのところでなぜ福栄会でいいのではないかと選ぶことができるのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"それから、公正公平な判断ですが、こちらも選定された事業者については、先ほどご説明したとおり、選定理由をお答えいたしました。今回選定した理由をご説明していますというところでの回答とします。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"考え方を変えてまで区の意向に従う、そのような事業者であるべきだということを区が求めるということに、逆になるのではないですか、そうなると。量を求められるけれども、そのようなものであるべきではないかと思うのですが、その点はどう考えられるか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"その発言に至った理由も説明されておりまして、区が出している公募要領があるのですが、それを見て考えに開きがあるというように感じたと。協議をしながら意見が違っても進めていくということは大事かなとは思うのですが、難しいと判断、不安に感じられる委員が多かったです。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"よりよい質を求めたい、本当に当事者のために頑張っていきたいというようなところでお互いにやっているわけですから、いかがでしょうか。そういう点では、それが影響あったのかどうなのか、その点についても伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"指定管理者と区が協議を行いながら施設運営を行っていくことは、大事なことだと考えております。それから、今回の報道に関することにつきましては、これは影響はかなりございました。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"現場でどれだけ一生懸命やっても、そのようにトップの人がハラスメントを起こしたというようなことが理由で選定から外されると、そのようなことも影響を与えたという、そのような意味で確認されるか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"区のほうで何かコメントできる立場にはありませんので、訴えられているというような関係性がある中で、総合的・一体的な管理運営をしていくことは難しいだろうと判断せざるを得なかったです。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これから指定管理者が品川区の福栄会という形で、もしも議会で選ばれたとしたら、１年半くらいあるわけです。その中でどのようにこの事業者のことに対して、この選定に対して、当事者や団体の皆さんに説明をしていくのか、その点について伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"現指定管理者、次期指定管理者、区も中に一緒に入りまして、引継ぎを行ってまいります。説明会、ご利用者の意向を踏まえながら、丁寧に対応していく考えです。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどのもう１回確認です。それと利用者との定期的な意見聴取の場を構築してほしいということ、やはり利用者中心のサービスをこれからもさらに向上していってほしいということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"今まで１４年ですか、１５年ですか、初めてですか。その場にいたわけではないから、どのような言い方をされたのかも分からないのだけれども、ちょっと考え方の乖離があったのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"おくの委員","kind":"質問・要望","question":"利用者の方々の継続を求める声、やはりそれを無視して決めたと言わざるを得ないと私は思います。議案に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-07","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"第９号に関しては、令和３年陳情第１号の協定締結、各々に対して細かい協定というのは普通締結するものなのですか。普通区と民間とかだと協定締結などと聞くのですが、区で区立施設を運営してもらう事業者と協定締結などをするのか。","respondent":"築山障害者施策推進担当課長","answer":"現在の指定管理者との契約につきましては、全施設個別に協定の方を結んでいるところです。","id":"exchange-070"},{"speaker":"渡部委員","kind":"確認","question":"その確認だけなので、どのようなものなのかと思って。いいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"現在のところから減らさないでほしいというものですから、やはり選択肢をもっと増やしてほしい、このお声は非常に大きいです。今のところが悪いというわけではないけれども増やしてほしい、積極的に捉えていただきたいなと思うのですけれども、この２点お伺いしたいと思います。","respondent":"築山障害者施策推進担当課長、松山障害者福祉課長","answer":"丁寧な対応が必要だと考えていますので、次期指定管理者とまずは話をさせていただき、丁寧に進めていただきたいと考えています。もちろん利用者に迷惑をかけないよう、丁寧に進めてまいりたいと考えています。 これまでも相談支援事業所についてですけれども、選択の機会の拡大が図れるように、新たな事業所を誘致してまいっております。今後もその他のサービス、あるいは施設等につきましても、積極的に充実を図ってまいりたいと考えております。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう研さんをやっていると思うのですが、そのようなところもぜひ、ますます意識をしていただきたいというところでの質問です。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そしてグローも引き続きやりたいということになったら、そのような可能性というのはあるのでしょうか。品川区がこれからも指定特定相談支援事業所を公募する場合、グローが応募することはできるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"民間の障害者の相談支援事業所につきましては、一定程度整備していると認識はしております。今後につきまして、在宅介護支援センターの併設型につきましては、来年度２か所ということで増設をする予定です。","id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もし公募が行われた場合に、ゆうゆうに応募してやっていただきたいという、そのような可能性というのはあるのでしょうか。にっせいかんが３法人と一緒に、にっせいかんについては今後どうなっていく見通しなのか、その点についてもお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"現事業者がこれからも事業を継続される、あるいは２点目の公募に応募するといったようなことにつきましては、現事業者の意向もありますし、公募ですから、どなたでも全国的に広く募るです。","id":"exchange-075"},{"speaker":"西村委員","kind":"質問・要望","question":"引き継ぎが無事遂行するように見届けていただきたいということと、場合によっては区からもサポートをしてほしいと求めました。利用者の皆さんに改めて期待を持って安心していただけるように施設運営をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出すということで、不採択です。まだ本会議の議決は出ていませんけれども、方向性が見えた段階ですので、現在より減らすことがないということに関しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう先ほど決定しているとおりですので、また別の機会に要望等もさせてほしいと求めました。今回は不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問・要望","question":"継続への要望は本当に熱意あるもので、大事にしなければいけないと思います。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"議案審査の様々な議論の下で確立されたということで、それを踏まえてです。１つだけ言うと、区として、ぜひ協力して一緒に一体となって施設の運営を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"意見","question":"協定締結というのはそもそも全ての事業者とやっているとのことですので、重ねてここでまた、こちらで議決をする必要はないのかなというところです。お気持ちはよく分かりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"昨年の１１月９日、この陳情の中にある施設整備を区に求める陳情が出されて、安全対策をより高くということで採択を主張しました。今回のこの陳情は選定事業者との間で協定締結を求めるもので、ご存じのとおり、選定すべきではないということを表明したばかりですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"あくつ委員","kind":"質問","question":"現地採用もかなりされていると伺っています。区が、やはり第三者が間に入っていただいて、利用者にとって不利益のない引継ぎをぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。引継ぎの部分と、区内の障害をお持ちの方々が利用しやすい施設にということで、併せて申し述べさせていただいて終わりにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/715198?Template=document&Id=3588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":79516,"voices":318}}]);
